  "skill.ferocity.crescendoStaccato": "\uD3ED\uC8FC \uC911 \uC544\uAD70 [[basic-attack|\uAE30\uBCF8 \uACF5\uACA9]] \uC801\uC911\uB9C8\uB2E4 {damage} \uD53C\uD574\uB7C9\uC744 \uAC00\uC9C4 [[mette-staccato|\uC2A4\uD0C0\uCE74\uD1A0]]\uAC00 \uCD94\uAC00\uB85C \uBC1C\uB3D9\uD55C\uB2E4.",
  "skill.ferocity.crescendoStaccato.power": "[[atk|\uACF5\uACA9\uB825]] {percent}%\uC758",
  "skill.ferocity.crescendoStaccato.amount": "[[damage-value|{amount}]]\uC758",
  "skill.ferocity.pontusRage": "\uB9E4\uCD08 \uC804\uC7A5\uC758 \uBAA8\uB4E0 \uC801\uC5D0\uAC8C \uCD5C\uB300 [[hp|\uCCB4\uB825]]\uC758 {percent}%\uC5D0 \uD574\uB2F9\uD558\uB294 [[fixed-damage|\uACE0\uC815 \uD53C\uD574]]\uB97C \uC8FC\uACE0 \uBAA8\uB4E0 \uD68C\uBCF5\uC744 \uB9C9\uB294\uB2E4.",
  "skill.ferocity.tailwindRally": "\uBAA8\uB4E0 \uC544\uAD70\uC774 \uACF5\uACA9\uD560 \uB54C\uB9C8\uB2E4 \uC624\uB974\uB294 [[ferocity|\uC57C\uC131]] \uAC8C\uC774\uC9C0\uC640 \uAD81\uADF9\uAE30 \uAC8C\uC774\uC9C0\uAC00 \uAC01\uAC01 {ferocity}, {energy}\uC529 \uB298\uC5B4\uB09C\uB2E4.",
  "skill.ferocity.sharedOverpaint": "\uD3ED\uC8FC \uC911 \uBAA8\uB4E0 \uC544\uAD70\uC758 [[basic-attack|\uAE30\uBCF8 \uACF5\uACA9]]\uC774 [[overpaint|\uB367\uCE60]]\uC744 \uD568\uAED8 \uC313\uB294\uB2E4.",
  "skill.ferocity.tidalVigor": "\uB9E4\uCD08 [[missing-hp|\uC783\uC740 \uCCB4\uB825]]\uC758 {percent}%\uB97C \uD68C\uBCF5\uD558\uACE0 [[attack-speed|\uACF5\uACA9 \uC18D\uB3C4]]\uAC00 {speed}% \uC99D\uAC00\uD55C\uB2E4.",
  "skill.ferocity.butcherFeast": "\uD3ED\uC8FC \uD6C4 \uB2E4\uC74C {attacks}\uBC88\uC758 [[basic-attack|\uAE30\uBCF8 \uACF5\uACA9]]\uC740 [[butcher|\uC190\uC9C8]]\uC744 \uC989\uC2DC \uD130\uB728\uB9B0\uB2E4. [[butcher|\uC190\uC9C8]]\uC774 \uD130\uC9C4 \uD53C\uD574\uC758 {percent}%\uB9CC\uD07C \uC0DD\uC874 \uC544\uAD70 \uC804\uCCB4\uB97C \uD68C\uBCF5\uC2DC\uD0A8\uB2E4.",
  "skill.ferocity.adamantBody": "{shield}\uB9CC\uD07C [[shield|\uBCF4\uD638\uB9C9]]\uC744 \uC5BB\uB294\uB2E4. \uC774\uD6C4 [[basic-attack|\uAE30\uBCF8 \uACF5\uACA9]] {attacks}\uD68C \uB3D9\uC548 [[attack-speed|\uACF5\uACA9 \uC18D\uB3C4]]\uAC00 {percent}% \uC624\uB978\uB2E4.",
  "skill.ferocity.adamantBody.shieldPercent": "\uCD5C\uB300 \uCCB4\uB825\uC758 {percent}%",
  "skill.ferocity.venomousEncore": "[[attack-speed|\uACF5\uACA9 \uC18D\uB3C4]]\uAC00 {percent}% \uC99D\uAC00\uD55C\uB2E4. [[basic-attack|\uAE30\uBCF8 \uACF5\uACA9]]\uC774 \uC790\uC2E0\uC758 [[poison|\uC911\uB3C5]]\uC5D0 \uAC78\uB9AC\uC9C0 \uC54A\uC740 \uC801\uC5D0\uAC8C\uB294 \uC911\uB3C5\uC744 \uBD80\uC5EC\uD558\uACE0, \uC774\uBBF8 \uAC78\uB9B0 \uC801\uC5D0\uAC8C\uB294 \uADF8 \uC911\uB3C5\uC744 [[liquidate|\uCCAD\uC0B0]]\uD55C\uB2E4.",
  "skill.ferocity.knockbackSlam": "{loaded}[[concussion|\uB1CC\uC9C4\uD0D5]]\uC774 \uD655\uC815 \uCE58\uBA85\uD0C0\uAC00 \uB418\uACE0, \uADF8 \uC801\uC744 [[knockback|\uB0A0\uB824\uBC84\uB9B0\uB2E4]]. \uB0A0\uB824\uBC84\uB9B0 \uB4A4\uC5D0\uB294 \uAC00\uC7A5 \uAC00\uAE4C\uC6B4 \uC801\uC744 \uD45C\uC801\uC73C\uB85C \uB2E4\uC2DC \uC9C0\uC815\uD55C\uB2E4.",
  "skill.ferocity.knockbackSlam.loaded": "\uD3ED\uC8FC\uC5D0 \uB4E4\uC5B4\uAC00\uBA74 [[concussion|\uB1CC\uC9C4\uD0D5]]\uC774 \uACE7\uBC14\uB85C \uC7A5\uC804\uB41C\uB2E4. ",
  "skill.ferocity.stormAim": "\uD3ED\uC8FC \uC911 [[basic-attack|\uAE30\uBCF8 \uACF5\uACA9]]\uC774 \uB300\uC0C1\uC758 [[def|\uBC29\uC5B4\uB825]]\uACFC [[res|\uC800\uD56D\uB825]]\uC744 {percent}%\uB9CC\uD07C \uB354 \uC9C0\uB098\uCE5C\uB2E4.",
  "skill.ferocity.frenzyGaze": "\uD3ED\uC8FC \uC911 [[basic-attack|\uAE30\uBCF8 \uACF5\uACA9]]\uC5D0 \uC801\uC911\uD55C \uC801\uC744 {seconds}\uCD08 \uB3D9\uC548 [[frenzy|\uAD11\uB780]]\uC2DC\uD0A8\uB2E4. [[transfer|\uC804\uC774]]\uB41C \uD0C0\uACA9\uC73C\uB85C\uB294 \uBC1C\uB3D9\uD558\uC9C0 \uC54A\uB294\uB2E4.",
  "skill.ferocity.battleHeat": "\uD3ED\uC8FC\uC5D0 \uB4E4\uC5B4\uAC00\uB294 \uC21C\uAC04 \uB113\uC740 \uBC94\uC704\uC758 \uC801\uC744 {seconds}\uCD08 \uB3D9\uC548 [[taunt|\uB3C4\uBC1C]]\uD55C\uB2E4. \uB9E4\uCD08 \uC790\uC2E0\uC758 \uC8FC\uC704 \uBAA8\uB4E0 \uC801\uC5D0\uAC8C \uCD5C\uB300 \uCCB4\uB825\uC758 {percent}%\uB9CC\uD07C [[fixed-damage|\uACE0\uC815 \uD53C\uD574]]\uB97C \uC900\uB2E4. \uD3ED\uC8FC \uB3D9\uC548 [[nodonia-elation|\uD76C\uC5F4]]\uC758 \uD68C\uBCF5\uB7C9\uC774 {healPercent}% \uC99D\uAC00\uD55C\uB2E4.",
  "skill.ferocity.graffitiRun": "[[move-speed|\uC774\uB3D9 \uC18D\uB3C4]]\uAC00 {percent}% \uC99D\uAC00\uD558\uACE0 [[basic-attack|\uAE30\uBCF8 \uACF5\uACA9]]\uC744 \uD558\uC9C0 \uC54A\uB294\uB2E4. \uB9E4\uCD08 \uC790\uC2E0\uC758 \uC8FC\uC704 \uBAA8\uB4E0 \uC801\uC5D0\uAC8C {damage}\uC758 [[magical-damage|\uB9C8\uBC95 \uD53C\uD574]]\uB97C \uC8FC\uACE0 [[vandalism|\uBC34\uB35C\uB9AC\uC998]]\uC744 \uD55C \uACB9 \uC313\uC73C\uBA70 {seconds}\uCD08 \uB3D9\uC548 [[taunt|\uB3C4\uBC1C]]\uD55C\uB2E4.",
  "skill.ferocity.furCoat": "\uD3ED\uC8FC\uC5D0 \uB4E4\uC5B4\uAC00\uB294 \uC21C\uAC04 \uC790\uC2E0\uC758 \uBAA8\uB4E0 \uC0C1\uD0DC\uC774\uC0C1\xB7\uB514\uBC84\uD504\uB97C \uC9C0\uC6B0\uACE0 \uCD5C\uB300 \uCCB4\uB825\uC758 {percent}% [[shield|\uBCF4\uD638\uB9C9]]\uC744 \uC5BB\uB294\uB2E4. \uD3ED\uC8FC \uC911\uC5D0\uB294 [[def|\uBC29\uC5B4\uB825]]\uACFC [[res|\uC800\uD56D\uB825]]\uC774 {guardPercent}% \uC624\uB978\uB2E4.",
  "skill.ferocity.shellResolve": "\uD3ED\uC8FC\uC5D0 \uB4E4\uC5B4\uAC00\uB294 \uC21C\uAC04 \uC790\uC2E0\uC758 \uBAA8\uB4E0 \uC0C1\uD0DC\uC774\uC0C1\xB7\uB514\uBC84\uD504\uB97C \uC9C0\uC6B0\uACE0 [[shell|\uC870\uAC00\uBE44]]\uB97C {stacks}\uACB9 \uC5BB\uB294\uB2E4. \uD3ED\uC8FC \uC911\uC5D0\uB294 \uC870\uAC00\uBE44\uAC00 {seconds}\uCD08\uB9C8\uB2E4 \uB2E4\uC2DC \uD130\uC9C8 \uC218 \uC788\uB2E4.",
  "skill.ferocity.cautery": "[[attack-speed|\uACF5\uACA9 \uC18D\uB3C4]]\uAC00 {percent}% \uC99D\uAC00\uD558\uACE0, \uBD80\uC5EC\uD558\uB358 [[shield|\uBCF4\uD638\uB9C9]]\uC774 \uAC19\uC740 \uC591\uC758 \uC989\uC2DC \uD68C\uBCF5\uC73C\uB85C \uBC14\uB010\uB2E4.",
  "skill.ferocity.splitVolley": "\uD3ED\uC8FC \uC911 \uBAA8\uB4E0 \uC77C\uBC18 \uACF5\uACA9\uC774 [[split-arrow|\uAC08\uB798\uD654\uC0B4]]\uC774 \uB418\uACE0 \uC0AC\uAC70\uB9AC\uAC00 {reach} \uC99D\uAC00\uD55C\uB2E4.",
  "skill.ferocity.summonPackFrenzy": "[[summon-kuro|\uCFE0\uB85C]]\uC640 [[summon-shiro|\uC2DC\uB85C]]\uAC00 \uD568\uAED8 \uD3ED\uC8FC\uD55C\uB2E4.",
  "skill.ferocity.overclock": "[[attack-speed|\uACF5\uACA9 \uC18D\uB3C4]]\uAC00 {percent}% \uC624\uB974\uACE0, \uC790\uC2E0\uACFC [[summon-dimo|\uB514\uBAA8]]\uAC00 {shield}\uB9CC\uD07C [[shield|\uBCF4\uD638\uB9C9]]\uC744 \uC5BB\uB294\uB2E4(\uD3ED\uC8FC\uAC00 \uC808\uBC18\uCBE4 \uC9C0\uB098\uBA74 \uC0AC\uB77C\uC9C4\uB2E4). \uB514\uBAA8 \uC8FC\uC704 \uB113\uC740 \uBC94\uC704\uC758 \uC801\uC5D0\uAC8C \uB9E4\uCD08 {damage}\uAC00 \uB4E4\uC5B4\uAC04\uB2E4.",
