var CHAPTER_46 = {
  id: "bond.ella.4",
  startNodeId: "n1",
  titleCard: { title: "\uBE44 \uC624\uB294 \uB0A0 \uCC98\uB9C8 \uBC11", subtitle: "\uC5D8\uB77C \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 1" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC624\uD6C4\uBD80\uD130 \uB0B4\uB9B0 \uBE44\uAC00 \uB9C8\uB2F9\uC744 \uC801\uC2E0\uB2E4. \uB9C8\uB2F9 \uD55C\uD3B8 \uCC98\uB9C8 \uBC11 \uB9C8\uB8E8\uC5D0 \uC5D8\uB77C\uAC00 \uC549\uC544 \uC788\uB2E4. \uC774\uB9C8\uC640 \uC18C\uB9E4\uC758 \uBD80\uC801\uC744 \uD55C \uC7A5\uC529 \uAC00\uB9CC\uD788 \uC4F8\uC5B4 \uBCF8\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uC5D8\uB77C", body: "\uC544, \uC5F0\uAD6C\uC6D0. \uC624\uB298\uC740 \uB9C8\uB2F9\uC5D0 \uBABB \uB098\uAC00\uC694. \uC774\uB9C8\uC758 \uBD80\uC801\uC774 \uC816\uC73C\uBA74 \uC548 \uB418\uAC70\uB4E0\uC694. \uBE44\uAC00 \uADF8\uCE60 \uB54C\uAE4C\uC9C0 \uC5EC\uAE30\uC11C \uC26C\uC5B4\uC694.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uCC98\uB9C8 \uB05D\uC5D0\uC11C \uBE57\uBC29\uC6B8\uC774 \uC77C\uC815\uD55C \uAC04\uACA9\uC73C\uB85C \uB5A8\uC5B4\uC9C4\uB2E4. \uC5D8\uB77C\uB294 \uADF8 \uAC04\uACA9\uC5D0 \uB9DE\uCD94\uC5B4 \uC228\uC744 \uACE0\uB974\uACE0 \uC788\uB2E4. \uC18C\uB9AC\uAC00 \uC5C6\uB294 \uC0AC\uB78C\uC774 \uC18C\uB9AC \uC18D\uC5D0 \uC549\uC544 \uC788\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uC18C\uB9E4\uC758 \uBD80\uC801\uC740 \uC774\uBBF8 \uD55C \uBC88 \uC811\uD600 \uC788\uB2E4. \uB204\uAC00 \uBD99\uC5EC \uC900 \uAC83\uC778\uC9C0\uB294 \uC5D8\uB77C\uB3C4 \uAE30\uC5B5\uD558\uC9C0 \uBABB\uD55C\uB2E4\uACE0 \uD588\uB2E4.)", choices: [
      { id: "sit", label: "\uC606\uC790\uB9AC\uC5D0 \uC549\uC544 \uAC19\uC774 \uBE44\uB97C \uBCF8\uB2E4", nextId: "n5a" },
      { id: "ask", label: "\uADF8 \uBD80\uC801\uC740 \uB204\uAC00 \uBD99\uC5EC \uC900 \uAC74\uC9C0 \uBB3B\uB294\uB2E4", nextId: "n5b" }
    ] },
    { id: "n5a", speaker: "\uC5D8\uB77C", body: "\uC549\uC73C\uC138\uC694, \uC549\uC73C\uC138\uC694. \uC694\uC998 \uAC83\uB4E4\uC740 \uC131\uC9C8\uC774 \uAE09\uD574\uC11C \uBE44 \uC624\uB294 \uB0A0\uC5D0\uB3C4 \uAC00\uB9CC\uD788 \uBABB \uC788\uB294\uB370, \uC5F0\uAD6C\uC6D0\uC740 \uC549\uC544 \uC788\uC744 \uC904 \uC544\uC2DC\uB124\uC694. \uBCF4\uAE30 \uC88B\uC544\uC694.", nextId: "n6" },
    { id: "n5b", speaker: "\uC5D8\uB77C", body: "\uAE00\uC384\uC694\u2026 \uB204\uAC00 \uBD99\uC600\uB294\uC9C0\uB294 \uBAA8\uB974\uACA0\uC5B4\uC694. \uB2E4\uB9CC \uC816\uC73C\uBA74 \uC548 \uB41C\uB2E4\uB294 \uAC83\uB9CC \uC54C\uC544\uC694. \uC774\uC720\uB294 \uBAB0\uB77C\uB3C4 \uC9C0\uD0A4\uAC8C \uB418\uB294 \uAC8C \uC788\uC796\uC544\uC694.", nextId: "n6" },
    { id: "n6", speaker: "", body: "\uB3C4\uB514\uC640 \uD30C\uB8E8\uC544\uAC00 \uB9C8\uB2F9\uC5D0\uC11C \uBE44\uB97C \uB9DE\uC73C\uBA70 \uB6F0\uC5B4\uB2E4\uB2CC\uB2E4. \uB458\uC774 \uB9C8\uB8E8 \uCABD\uC73C\uB85C \uC190\uC744 \uD754\uB4E4\uC5C8\uB2E4.", nextId: "n7" },
    { id: "n7", speaker: "\uB3C4\uB514", body: "\uC5D8\uB77C, \uAC19\uC774 \uB180\uC790! \uBE44 \uB9DE\uC544\uB3C4 \uAD1C\uCC2E\uC544, \uAE08\uBC29 \uB9C8\uB974\uB2C8\uAE4C!", nextId: "n8" },
    { id: "n8", speaker: "\uC5D8\uB77C", body: "\uAD1C\uCC2E\uACE0 \uB9D0\uACE0\uC694. \uB300\uC2E0 \uC800\uB294 \uC5EC\uAE30\uC11C \uAD6C\uACBD\uD560\uAC8C\uC694. \uD55C \uBC88 \uB118\uC5B4\uC9C0\uBA74 \uC77C\uC5B4\uB098\uB294 \uB370 \uC2DC\uAC04\uC774 \uAC78\uB9AC\uB2C8\uAE4C\uC694. \uB2E4\uCE58\uC9C0\uB9CC \uB9D0\uACE0 \uB180\uC544\uC694.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uBE57\uC904\uAE30\uAC00 \uC870\uAE08\uC529 \uAC00\uB298\uC5B4\uC9C4\uB2E4. \uC5D8\uB77C\uC758 \uC2DC\uC120\uC740 \uB9C8\uB2F9\uC744 \uAC00\uB85C\uC9C8\uB7EC \uB6F0\uB294 \uC544\uC774\uB4E4\uC744 \uB530\uB77C\uAC04\uB2E4. \uC785\uAF2C\uB9AC\uAC00 \uC544\uC8FC \uC870\uAE08 \uC62C\uB77C\uAC00 \uC788\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uC5D8\uB77C", body: "\uC5F0\uAD6C\uC6D0, \uBE44\uAC00 \uADF8\uCE58\uBA74 \uB9C8\uB2F9\uC5D0 \uAC19\uC774 \uC11C \uBD10\uC694. \uCC9C\uCC9C\uD788 \uC6C0\uC9C1\uC774\uB294 \uBC95\uC744 \uAC00\uB974\uCCD0 \uB4DC\uB9B4\uAC8C\uC694. \uC11C\uB450\uB974\uC9C0 \uC54A\uB294 \uAC83\uB3C4 \uD798\uC774\uC5D0\uC694." }
  ]
};
var CHAPTER_66 = {
  id: "bond.ella.6",
  startNodeId: "n1",
  titleCard: { title: "\uB290\uB9AC\uAC8C \uD558\uB294 \uD798", subtitle: "\uC5D8\uB77C \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 2" },
  nodes: [
    { id: "n1", speaker: "", body: "\uBE44 \uAC20 \uC544\uCE68\uC758 \uB9C8\uB2F9. \uC816\uC740 \uD759\uB0C4\uC0C8 \uC18D\uC5D0\uC11C \uC5D8\uB77C\uAC00 \uD55C \uD314\uC744 \uCC9C\uCC9C\uD788 \uB4E4\uC5B4 \uC62C\uB9B0\uB2E4. \uADF8 \uB4A4\uB85C \uB3C4\uB514\uC640 \uD30C\uB8E8\uC544\uAC00 \uC11C\uD22C\uB974\uAC8C \uAC19\uC740 \uC790\uC138\uB97C \uB530\uB77C \uD55C\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uB3C4\uB514", body: "\uC5D8\uB77C, \uC774\uAC70 \uC5B4\uB824\uC6CC. \uD314\uC774 \uC790\uAFB8 \uBE68\uB9AC \uAC00 \uBC84\uB824. \uCC9C\uCC9C\uD788 \uD558\uB824\uB2C8\uAE4C \uC624\uD788\uB824 \uD798\uB4E4\uC5B4.", nextId: "n3" },
    { id: "n3", speaker: "\uC5D8\uB77C", body: "\uADF8\uAC8C \uC815\uC0C1\uC774\uC5D0\uC694. \uBE60\uB974\uAC8C \uD558\uB294 \uAC74 \uC26C\uC6CC\uC694. \uB290\uB9AC\uAC8C \uD558\uB294 \uAC74 \uBAB8\uC774 \uD558\uB294 \uC77C\uC774 \uC544\uB2C8\uB77C \uB9C8\uC74C\uC774 \uD558\uB294 \uC77C\uC774\uAC70\uB4E0\uC694.", nextId: "n4" },
    { id: "n4", speaker: "", body: "\uD30C\uB8E8\uC544\uAC00 \uCC38\uC9C0 \uBABB\uD558\uACE0 \uC5D8\uB77C\uC758 \uC190\uBAA9\uC744 \uD5A5\uD574 \uB2EC\uB824\uB4E0\uB2E4. \uC5D8\uB77C\uC758 \uC190\uBAA9\uC774 \uC544\uC8FC \uC870\uAE08 \uB3CC\uC544\uAC14\uACE0 \uD30C\uB8E8\uC544\uB294 \uD480\uC369 \uB118\uC5B4\uC84C\uB2E4. \uB2E4\uCE58\uC9C0 \uC54A\uAC8C \uBC1B\uCCD0 \uC8FC\uB294 \uC190\uAE38\uC774\uB2E4.", nextId: "n5" },
    { id: "n5", speaker: "\uD30C\uB8E8\uC544", body: "\uB610 \uB118\uC5B4\uC84C\uC5B4\u2026 \uC5D8\uB77C\uB294 \uC5B4\uB5BB\uAC8C \uC774\uB807\uAC8C \uC548 \uC544\uD504\uAC8C \uB118\uC5B4\uB728\uB824?", nextId: "n6" },
    { id: "n6", speaker: "\uC5D8\uB77C", body: "\uBD99\uC774\uACE0, \uD480\uACE0, \uBCF4\uB0B4\uC694. \uC810(\u7C98)\xB7\uD654(\u5316)\xB7\uBC1C(\u767C)\uC774\uC5D0\uC694. \uC0C1\uB300\uAC00 \uC624\uB294 \uD798\uC744 \uD55C \uBC88 \uBD99\uB4E4\uC5B4\uC11C \uD754\uB4E4\uACE0 \uAC00\uB358 \uBC29\uD5A5\uC73C\uB85C \uB0B4\uBCF4\uB0B4\uB294 \uAC70\uC608\uC694. \uBC00\uC9C0 \uC54A\uC544\uB3C4 \uB3FC\uC694.", nextId: "n7" },
    { id: "n7", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uC5D8\uB77C\uAC00 \uCC9C\uCC9C\uD788 \uC790\uC138\uB97C \uD480\uC790 \uB9C8\uB2F9\uC758 \uC544\uC774\uB4E4\uC774 \uC228\uC744 \uACE0\uB978\uB2E4. \uC544\uBB34\uB3C4 \uC11C\uB450\uB974\uC9C0 \uC54A\uB294 \uB3D9\uC548 \uC544\uCE68 \uD587\uC0B4\uC774 \uB9C8\uB2F9 \uB05D\uAE4C\uC9C0 \uB2FF\uB294\uB2E4.)", choices: [
      { id: "try", label: "\uB098\uB3C4 \uD55C \uBC88 \uD574 \uBD10\uB3C4 \uB418\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4", nextId: "n8a" },
      { id: "watch", label: "\uC790\uC138\uAC00 \uC544\uB984\uB2F5\uB2E4\uACE0 \uB9D0\uD574 \uC900\uB2E4", nextId: "n8b" }
    ] },
    { id: "n8a", speaker: "\uC5D8\uB77C", body: "\uADF8\uB7FC\uC694, \uADF8\uB7FC\uC694. \uC190\uC744 \uC774\uB807\uAC8C \uC62C\uB9AC\uACE0\u2026 \uC544\uB2C8, \uC5B4\uAE68\uB294 \uB0B4\uB824\uC694. \uAE09\uD558\uC9C0 \uC54A\uC544\uC694. \uC5F0\uAD6C\uC6D0\uC740 \uC81C\uAC00 \uBCF8 \uC0AC\uB78C \uC911 \uB450 \uBC88\uC9F8\uB85C \uC798 \uB530\uB77C \uD558\uB124\uC694.", nextId: "n9" },
    { id: "n8b", speaker: "\uC5D8\uB77C", body: "\uC544\uC774\uACE0, \uADF8\uB7F0 \uB9D0\uC744 \uD574 \uC8FC\uC2DC\uBA74 \uC5BC\uAD74\uC774 \uC870\uAE08 \uB530\uB73B\uD574\uC838\uC694. \uCE6D\uCC2C\uBC1B\uB294 \uAC74 \uC624\uB798 \uC0B4\uC544\uB3C4 \uC775\uC219\uD574\uC9C0\uC9C0 \uC54A\uB124\uC694.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uC5D8\uB77C\uAC00 \uC544\uC774\uB4E4\uC744 \uD55C \uC904\uB85C \uC138\uC6B4\uB2E4. \uB9E8 \uB05D\uC5D0 \uC5F0\uAD6C\uC6D0\uB3C4 \uC11C \uC788\uB2E4. \uBAA8\uB450\uAC00 \uAC19\uC740 \uC18D\uB3C4\uB85C \uD55C \uD314\uC744 \uB4E4\uC5B4 \uC62C\uB9B0\uB2E4. \uBD80\uC801\uC774 \uC544\uCE68 \uBC14\uB78C\uC5D0 \uC544\uC8FC \uC870\uAE08 \uD754\uB4E4\uB9B0\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uC5D8\uB77C", body: "\uC774\uB807\uAC8C \uB2E4 \uAC19\uC774 \uB290\uB9AC\uAC8C \uC11C \uC788\uC73C\uBA74\uC694, \uC2DC\uAC04\uC774 \uC6B0\uB9AC \uCABD\uC73C\uB85C \uAC78\uC5B4\uC640 \uC918\uC694. \uC11C\uB450\uB974\uB294 \uC138\uC0C1\uC5D0\uC11C\uB294 \uBCF4\uAE30 \uB4DC\uBB38 \uC120\uBB3C\uC774\uC9C0\uC694." }
  ]
};
var CHAPTER_86 = {
  id: "bond.ella.8",
  startNodeId: "n1",
  titleCard: { title: "\uC2DC\uB9D0\uC11C\uB97C \uC4F0\uB294 \uBC24", subtitle: "\uC5D8\uB77C \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 3" },
  nodes: [
    { id: "n1", speaker: "", body: "\uD55C\uBC24\uC758 \uC219\uC18C \uBCF5\uB3C4. \uBC29\uB9C8\uB2E4 \uBD88\uC774 \uAEBC\uC84C\uB294\uB370 \uBB38\uC774 \uD558\uB098 \uB5A8\uC5B4\uC838 \uB098\uAC04 \uBC29 \uC606 \uC791\uC740 \uCC45\uC0C1\uC5D0\uC11C\uB9CC \uBD88\uBE5B\uC774 \uC0C8\uC5B4 \uB098\uC628\uB2E4. \uC5D8\uB77C\uAC00 \uBD93\uC744 \uB4E4\uACE0 \uC549\uC544 \uC788\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uC5D8\uB77C", body: "\uC544\uC774\uACE0, \uC5F0\uAD6C\uC6D0. \uC544\uC9C1 \uC548 \uC8FC\uBB34\uC138\uC694? \uC800\uB294 \uC2DC\uB9D0\uC11C\uB97C \uC4F0\uB294 \uC911\uC774\uC5D0\uC694. \uC624\uB298\uC740 \uC7A5\uC774 \uC138 \uC7A5\uC774\uB098 \uB418\uB124\uC694.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uCC45\uC0C1 \uC704\uC5D0\uB294 \uBB38\uC9DD\uC774 \uBD80\uC11C\uC9C4 \uACBD\uC704\uC11C\uAC00 \uC313\uC5EC \uC788\uB2E4. \uC774\uB984\uB780\uC740 \uBAA8\uB450 \uC5D8\uB77C\uAC00 \uC544\uB2CC \uB2E4\uB978 \uC774\uB984\uC774\uACE0 \uD544\uCCB4\uB9CC \uC5D8\uB77C\uC758 \uAC83\uC774\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uB9E8 \uC704 \uC7A5\uC758 \uC774\uB984\uB780\uC5D0 \uB809\uC2DC\uC544\uC758 \uC774\uB984\uC774 \uC801\uD600 \uC788\uB2E4. \uBC18\uC131\uBB38 \uB9D0\uBBF8\uC5D0\uB294 \uC815\uC131\uC2A4\uB7EC\uC6B4 \uC0AC\uACFC \uBB38\uC7A5\uC774 \uC774\uC5B4\uC9C4\uB2E4.)", choices: [
      { id: "ask", label: "\uC9C1\uC811 \uC4F0\uAC8C \uD558\uC9C0 \uC54A\uACE0 \uB300\uC2E0 \uC368 \uC8FC\uB294 \uC774\uC720\uB97C \uBB3B\uB294\uB2E4", nextId: "n5a" },
      { id: "help", label: "\uBA39\uC744 \uAC08\uC544 \uC8FC\uACA0\uB2E4\uACE0 \uD55C\uB2E4", nextId: "n5b" }
    ] },
    { id: "n5a", speaker: "\uC5D8\uB77C", body: "\uADF8 \uC544\uC774\uB4E4\uC740 \uC55E\uC73C\uB85C \uB2EC\uB9AC\uB290\uB77C \uB4A4\uB97C \uB3CC\uC544\uBCFC \uD2C8\uC774 \uC5C6\uC796\uC544\uC694. \uB4A4\uB294 \uC81C\uAC00 \uBCF4\uBA74 \uB418\uC9C0\uC694.", nextId: "n6" },
    { id: "n5b", speaker: "\uC5D8\uB77C", body: "\uADF8\uB7FC \uACE0\uB9D9\uAC8C \uBC1B\uACA0\uC5B4\uC694. \uBA39\uC774 \uC9C4\uD560\uC218\uB85D \uAE00\uC528\uAC00 \uC624\uB798 \uAC04\uB2F5\uB2C8\uB2E4. \uC774 \uC2DC\uB9D0\uC11C\uB3C4 \uC624\uB798 \uB0A8\uACA0\uC9C0\uC694? \uD6C4\uD6C4.", nextId: "n6" },
    { id: "n6", speaker: "", body: "\uBCF5\uB3C4 \uC800\uD3B8\uC5D0\uC11C \uBC1C\uC18C\uB9AC\uAC00 \uC694\uB780\uD558\uAC8C \uB2E4\uAC00\uC628\uB2E4. \uB809\uC2DC\uC544\uAC00 \uBB38\uC774 \uC5C6\uB294 \uBC29 \uC55E\uC5D0 \uBA48\uCDB0 \uC11C\uC11C \uCC45\uC0C1\uC758 \uBD88\uBE5B\uC744 \uBCF4\uACE0 \uC5BC\uC5B4\uBD99\uB294\uB2E4.", nextId: "n7" },
    { id: "n7", speaker: "\uB809\uC2DC\uC544", body: "\u2026\uC5D8\uB77C, \uADF8 \uC2DC\uB9D0\uC11C\uB294 \uB0B4\uAC00 \uC4F8\uAC8C\uC694. \uB0B4\uAC00 \uBD80\uC21C \uBB38\uC774\uB2C8\uAE4C\uC694. \uB9E4\uBC88 \uB9E1\uAE38 \uC218\uB294 \uC5C6\uC796\uC544\uC694.", nextId: "n8" },
    { id: "n8", speaker: "\uC5D8\uB77C", body: "\uADF8\uB7FC \uAC19\uC774 \uC4F0\uAE30\uB85C \uD574\uC694. \uCC98\uC74C \uD55C \uC904\uC740 \uB809\uC2DC\uC544\uAC00, \uB098\uBA38\uC9C0\uB294 \uC81C\uAC00\uC694. \uC694\uC998 \uAC83\uB4E4\uC774\uB77C\uACE0 \uB2E4 \uC131\uC9C8\uC774 \uAE09\uD55C \uAC74 \uC544\uB2C8\uB124\uC694. \uC774\uB7F0 \uAC74 \uB9C8\uC74C\uC5D0 \uB4E4\uC5B4\uC694.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uB809\uC2DC\uC544\uAC00 \uCB48\uBF1B\uAC70\uB9AC\uBA70 \uBD93\uC744 \uBC1B\uC544 \uB4E0\uB2E4. \uCCAB \uC904\uC774 \uC090\uB6A4\uAC8C \uC801\uD78C\uB2E4. \uC5D8\uB77C\uB294 \uADF8 \uC090\uB6A4\uC5B4\uC9C4 \uAE00\uC528 \uC544\uB798\uC5D0 \uBC18\uB4EF\uD55C \uD55C \uC904\uC744 \uC774\uC5B4 \uC4F4\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uC5D8\uB77C", body: "\uC5F0\uAD6C\uC6D0, \uBB38\uC9DD\uC740 \uBD80\uC11C\uC838\uB3C4 \uB2E4\uC2DC \uB2EC\uBA74 \uB3FC\uC694. \uC81C\uAC00 \uB9C8\uC74C \uC4F0\uB294 \uAC74 \uBD80\uC21C \uC0AC\uB78C\uC774 \uC790\uAE30 \uC190\uC73C\uB85C \uAE00\uC744 \uC4F0\uAC8C \uD558\uB294 \uAC70\uB78D\uB2C8\uB2E4. \uC624\uB298 \uBC24\uC740 \uC88B\uC740 \uBC24\uC774\uC5D0\uC694." }
  ]
};
var CHAPTER_106 = {
  id: "bond.ella.10",
  startNodeId: "n1",
  titleCard: { title: "\uCC98\uC74C \uB9DE\uB294 \uBE44", subtitle: "\uC5D8\uB77C \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 4" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC5B4\uC2A4\uB984\uC774 \uB0B4\uB9B0 \uB9C8\uB2F9\uC5D0 \uAC00\uB294 \uBE44\uAC00 \uB2E4\uC2DC \uC2DC\uC791\uB41C\uB2E4. \uC5D8\uB77C\uB294 \uCC98\uB9C8 \uB05D\uC5D0 \uC11C\uC11C \uC774\uB9C8\uC758 \uBD80\uC801\uC5D0 \uC190\uAC00\uB77D\uC744 \uC62C\uB838\uB2E4. \uC624\uB298\uC740 \uCC98\uB9C8 \uBC16\uC5D0 \uC11C \uC788\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uC5D8\uB77C", body: "\uC5F0\uAD6C\uC6D0, \uC624\uB298\uC740 \uC81C\uAC00 \uD558\uB098 \uD574 \uBCF4\uB824\uACE0\uC694. \uC774 \uBD80\uC801\uC694, \uC218\uC2ED \uB144\uC744 \uC816\uC9C0 \uC54A\uAC8C \uC9C0\uCF1C \uC654\uB294\uB370 \uC815\uC791 \uC816\uC73C\uBA74 \uC5B4\uB5BB\uAC8C \uB418\uB294\uC9C0\uB294 \uD55C \uBC88\uB3C4 \uBCF8 \uC801\uC774 \uC5C6\uC5B4\uC694.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uC5D8\uB77C\uAC00 \uC774\uB9C8\uC758 \uBD80\uC801\uC744 \uCC9C\uCC9C\uD788 \uB5BC\uC5B4 \uB0B8\uB2E4. \uC18C\uB9E4\uC758 \uBD80\uC801\uB3C4 \uD55C \uC7A5 \uD55C \uC7A5 \uD480\uC5B4 \uC190\uBC14\uB2E5\uC5D0 \uC62C\uB824\uB193\uB294\uB2E4. \uC885\uC774\uB294 \uC624\uB798\uB41C \uB9CC\uD07C \uBD80\uB4DC\uB7FD\uAC8C \uC811\uD600 \uC788\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uBD80\uC801\uC5D0\uB294 \uAE00\uC790\uAC00 \uAC70\uC758 \uB0A8\uC544 \uC788\uC9C0 \uC54A\uB2E4. \uBA87 \uD68D\uC774 \uB2F3\uC544 \uD754\uC801\uB9CC \uACA8\uC6B0 \uBCF4\uC778\uB2E4.)", choices: [
      { id: "hold", label: "\uBD80\uC801\uC740 \uB0B4\uAC00 \uD488\uC5D0 \uB123\uC5B4 \uB450\uACA0\uB2E4\uACE0 \uD55C\uB2E4", nextId: "n5a" },
      { id: "stay", label: "\uC606\uC5D0\uC11C \uAC19\uC774 \uBE44\uB97C \uB9DE\uACA0\uB2E4\uACE0 \uD55C\uB2E4", nextId: "n5b" }
    ] },
    { id: "n5a", speaker: "\uC5D8\uB77C", body: "\uADF8\uB7FC \uB9E1\uAE38\uAC8C\uC694. \uC816\uAC8C \uB450\uC9C0 \uB9D0\uC544 \uC8FC\uC138\uC694. \uC544, \uC544\uB2C8, \uC816\uC5B4\uB3C4 \uAD1C\uCC2E\uC544\uC694. \uADF8 \uB9D0\uC744 \uC81C\uAC00 \uD558\uAC8C \uB420 \uC904\uC740 \uBAB0\uB790\uB124\uC694.", nextId: "n6" },
    { id: "n5b", speaker: "\uC5D8\uB77C", body: "\uAC19\uC774 \uB9DE\uC544 \uC8FC\uC2DC\uBA74 \uB4E0\uB4E0\uD558\uC9C0\uC694. \uB458 \uB2E4 \uD760\uBED1 \uC816\uC73C\uBA74 \uB204\uAC00 \uBA3C\uC800 \uAC10\uAE30 \uAC78\uB9AC\uB098 \uB0B4\uAE30\uB77C\uB3C4 \uD560\uAE4C\uC694? \uD6C4\uD6C4.", nextId: "n6" },
    { id: "n6", speaker: "", body: "\uC5D8\uB77C\uAC00 \uCC98\uB9C8 \uBC16\uC73C\uB85C \uD55C \uAC78\uC74C \uB0B4\uB514\uB3A0\uB2E4. \uAC00\uB294 \uBE57\uC904\uAE30\uAC00 \uC774\uB9C8\uC640 \uC5B4\uAE68\uC5D0 \uB2FF\uB294\uB2E4. \uC5D8\uB77C\uB294 \uB208\uC744 \uAC10\uC740 \uCC44 \uD55C\uCC38\uC744 \uC6C0\uC9C1\uC774\uC9C0 \uC54A\uB294\uB2E4.", nextId: "n7" },
    { id: "n7", speaker: "\uC5D8\uB77C", body: "\u2026\uCC28\uAC11\uB124\uC694. \uADF8\uB9AC\uACE0 \uC774\uC0C1\uD558\uAC8C \uC2DC\uC6D0\uD574\uC694. \uBAB8\uC774 \uAD73\uC5B4 \uC788\uC5B4\uB3C4 \uBE44\uB294 \uC548\uAE4C\uC9C0 \uB2FF\uB294\uAD70\uC694. \uC624\uB798 \uC0B4\uC558\uB294\uB370\uB3C4 \uBAB0\uB790\uC5B4\uC694.", nextId: "n8" },
    { id: "n8", speaker: "", body: "\uC5D8\uB77C\uAC00 \uCC9C\uCC9C\uD788 \uD55C \uD314\uC744 \uB4E4\uC5B4 \uC62C\uB9B0\uB2E4. \uC810\xB7\uD654\xB7\uBC1C. \uBE57\uC904\uAE30\uAC00 \uD314\uC744 \uD0C0\uACE0 \uD758\uB7EC\uB0B4\uB9AC\uB2E4 \uB9C8\uC9C0\uB9C9 \uC190\uB05D\uC5D0\uC11C \uD55C\uAEBC\uBC88\uC5D0 \uD280\uC5B4 \uD769\uC5B4\uC9C4\uB2E4. \uB9C8\uB2F9 \uC704\uB85C \uAC00\uB298\uACE0 \uD558\uC580 \uBB3C\uBCF4\uB77C\uAC00 \uBC88\uC9C4\uB2E4.", nextId: "n9" },
    { id: "n9", speaker: "\uC5D8\uB77C", body: "\uBD88\uBA78\uC774\uB77C\uB294 \uAC74 \uC8FD\uC9C0 \uC54A\uB294 \uAC8C \uC544\uB2C8\uB77C \uC816\uC5B4\uB3C4 \uC11C \uC788\uB294 \uAC70\uC600\uB098 \uBD10\uC694. \uC5F0\uAD6C\uC6D0, \uC774 \uB9D0\uC740 \uC81C\uAC00 \uBC29\uAE08 \uC9C0\uC5C8\uC5B4\uC694. \uB9C8\uC74C\uC5D0 \uB4DC\uC168\uC73C\uBA74 \uC88B\uACA0\uB124\uC694.", nextId: "n10" },
    { id: "n10", speaker: "\uC5D8\uB77C", body: "\uBD80\uC801\uC740 \uC774\uC81C \uC18C\uB9E4 \uC548\uCABD\uC5D0\uB9CC \uB123\uC5B4 \uB458\uAC8C\uC694. \uC816\uC744 \uB54C\uB294 \uAC19\uC774 \uC816\uACE0\uC694. \uBE44 \uC624\uB294 \uB0A0 \uB9C8\uB2F9\uC5D0 \uAC19\uC774 \uC11C \uC904 \uC0AC\uB78C\uC774 \uC0DD\uACBC\uC73C\uB2C8, \uC774\uC81C \uCC98\uB9C8 \uBC11\uB3C4 \uC2EC\uC2EC\uD558\uC9C0 \uC54A\uACA0\uB124\uC694." }
  ]
};
var ELLA_STORY = {
  relicId: "ella",
  fossilRecord: "\uACE0\uC6D0\uC758 \uC790\uAC08\uCE35\uC5D0\uC11C \uCF54\uBFD4 \uD558\uB098\uC640 \uC55E\uB2E4\uB9AC\uBF08\uAC00 \uD568\uAED8 \uB098\uC654\uB2E4. \uBF08\uC758 \uC131\uC7A5\uC120\uC774 \uC720\uB09C\uD788 \uCD18\uCD18\uD558\uACE0 \uACB9\uC774 \uB9CE\uC544, \uAC19\uC740 \uC885 \uD45C\uBCF8 \uC911 \uAC00\uC7A5 \uC624\uB798 \uC0B0 \uAC1C\uCCB4\uB85C \uBD84\uB958\uB410\uB2E4.",
  diary: '\uC5D8\uB77C\uB294 \uBAB8\uC774 \uAD73\uC5B4 \uC788\uB2E4. \uBCF5\uC6D0 \uC9C1\uD6C4 \uACC4\uCE21\uB300\uAC00 \uC8FC\uC800\uC549\uC544 \uD55C \uBC88 \uAC08\uC558\uACE0 \uCF00\uC5B4\uC2E4 \uBC14\uB2E5\uC7AC\uB3C4 \uB2E4\uC2DC \uAE54\uC558\uB294\uB370, \uC815\uC791 \uBCF8\uC778\uC740 \uC18C\uB9AC \uC5C6\uC774 \uAC77\uB294\uB2E4. \uD558\uB8E8\uC758 \uB300\uBD80\uBD84\uC744 \uB9C8\uB2F9\uC5D0\uC11C \uAC19\uC740 \uB3D9\uC791\uC744 \uC544\uC8FC \uB290\uB9AC\uAC8C \uBC18\uBCF5\uD558\uBA70 \uBCF4\uB0B4\uACE0, \uC5B4\uB9B0 \uB810\uB9AD\uB4E4\uC774 \uD749\uB0B4 \uB0B4\uBA70 \uB2EC\uB824\uB4E4\uBA74 \uC190\uBAA9\uB9CC \uC0B4\uC9DD \uB3CC\uB824 \uD558\uB098\uC529 \uB118\uC5B4\uB728\uB9AC\uACE0\uB294 \uB2E4\uC2DC \uCC98\uC74C \uC790\uC138\uB85C \uB3CC\uC544\uAC04\uB2E4. \uC573\uB41C \uC5BC\uAD74\uB85C "\uC694\uC998 \uAC83\uB4E4\uC740 \uC131\uC9C8\uC774 \uAE09\uD574"\uB77C\uACE0 \uB9D0\uD558\uB294 \uAC83\uC774 \uC5EC\uB7EC \uBC88 \uAD00\uCC30\uB410\uB2E4. \uC774\uB9C8\uC640 \uC18C\uB9E4\uC758 \uBD80\uC801\uC740 \uC816\uC73C\uBA74 \uC548 \uB41C\uB2E4\uBA70 \uBE44 \uC624\uB294 \uB0A0\uC5D0\uB294 \uCC98\uB9C8 \uBC11\uC5D0\uC11C\uB9CC \uC6C0\uC9C1\uC778\uB2E4. \uBB38\uC9DD\uC774 \uBD80\uC11C\uC9C4 \uB0A0 \uBC24\uC774\uBA74 \uC2DC\uB9D0\uC11C \uC4F0\uB294 \uBD93\uC18C\uB9AC\uAC00 \uB4E4\uB9AC\uB294\uB370, \uC4F0\uB294 \uC774\uB294 \uB300\uAC1C \uBD80\uC21C \uCABD\uC774 \uC544\uB2C8\uB2E4.',
  /** 일지 맨 끝에 회색으로 서는, 엘라가 연구원에게 건네는 한마디. 뽑기 대사와 다른 일상의 목소리다. */
  closingLine: "\uBE44 \uC624\uB294 \uB0A0\uC740 \uCC98\uB9C8 \uBC11\uC5D0\uC11C \uAE30\uB2E4\uB9B4\uAC8C\uC694, \uC5F0\uAD6C\uC6D0. \uC11C\uB450\uB97C \uC77C\uC740 \uC5C6\uC73C\uB2C8 \uCC9C\uCC9C\uD788 \uC640\uC694.",
  questions: [
    {
      id: "ella-talisman",
      prompt: "\uC5D8\uB77C\uC758 \uC774\uB9C8\uC640 \uC18C\uB9E4\uC5D0 \uBD99\uC740 \uBD80\uC801\uC5D0\uB294 \uBB34\uC5C7\uC774 \uC801\uD600 \uC788\uC5B4?",
      choices: [
        {
          id: "letters",
          label: "\uAE00\uC790\uAC00 \uBB34\uC5C7\uC778\uC9C0 \uC870\uC2EC\uC2A4\uB7FD\uAC8C \uBB3B\uB294\uB2E4",
          reply: "\uAE00\uC384\uC694, \uB2F3\uC544\uC11C \uC800\uB3C4 \uBABB \uC77D\uC5B4\uC694. \uC77D\uC744 \uC218 \uC5C6\uC5B4\uB3C4 \uBD99\uC5B4 \uC788\uB2E4\uB294 \uAC8C \uC911\uC694\uD55C \uBD80\uC801\uB3C4 \uC788\uB294 \uBC95\uC774\uC796\uC544\uC694.",
          note: "\uBD80\uC801\uC758 \uAE00\uC790\uB294 \uAC70\uC758 \uB2F3\uC544 \uC77D\uC744 \uC218 \uC5C6\uC5C8\uB2E4. \uBCF8\uC778\uB3C4 \uBB34\uC2A8 \uB73B\uC778\uC9C0 \uBAA8\uB978\uB2E4\uACE0 \uD588\uB2E4."
        },
        {
          id: "touch",
          label: "\uD55C \uBC88 \uB9CC\uC838 \uBD10\uB3C4 \uB418\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC73C\uC74C, \uB208\uC73C\uB85C\uB9CC \uBD10 \uC8FC\uC138\uC694. \uB2FF\uC73C\uBA74 \uB2F3\uC744\uAE4C \uBD10\uC11C\uC694. \uC190\uC774 \uB2FF\uC740 \uBD80\uC801\uC774 \uAF64 \uC624\uB798 \uAC71\uC815\uB418\uAC70\uB4E0\uC694.",
          note: "\uBD80\uC801\uC5D0 \uC190\uC744 \uB300\uB824 \uD558\uC790 \uD55C \uAC78\uC74C \uBB3C\uB7EC\uC130\uB2E4. \uB208\uC73C\uB85C \uBCF4\uB294 \uAC83\uB9CC \uD5C8\uB77D\uD588\uB2E4."
        },
        {
          id: "rain",
          label: "\uBE44 \uC624\uB294 \uB0A0\uC5D4 \uBD80\uC801\uC774 \uAC71\uC815\uB418\uACA0\uB2E4\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\uB9DE\uC544\uC694, \uADF8\uB798\uC11C \uBE44 \uC624\uB294 \uB0A0\uC740 \uCC98\uB9C8 \uBC11\uC5D0\uC11C \uC9C0\uB0B4\uC9C0\uC694. \uC5F0\uAD6C\uC6D0\uB3C4 \uAC19\uC774 \uC788\uC5B4 \uC8FC\uC2DC\uBA74 \uC2EC\uC2EC\uD558\uC9C0 \uC54A\uC744 \uAC70\uC608\uC694.",
          note: "\uBE44 \uC774\uC57C\uAE30\uB97C \uD558\uC790 \uCC98\uB9C8 \uBC11 \uB9C8\uB8E8\uB97C \uAC00\uB9AC\uCF30\uB2E4. \uC790\uB9AC\uB97C \uBC18\uCBE4 \uBE44\uC6CC \uB450\uC5C8\uB2E4."
        }
      ]
    },
    {
      id: "ella-stance",
      prompt: "\uC5D8\uB77C\uB294 \uC65C \uB9C8\uB2F9\uC5D0\uC11C \uAC19\uC740 \uB3D9\uC791\uC744 \uADF8\uB807\uAC8C \uB290\uB9AC\uAC8C \uBC18\uBCF5\uD574?",
      choices: [
        {
          id: "slow",
          label: "\uB290\uB9AC\uAC8C \uD558\uB294 \uAC8C \uB354 \uC5B4\uB835\uC9C0 \uC54A\uC73C\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uADF8\uB7FC\uC694, \uC544\uC8FC \uC5B4\uB824\uC6CC\uC694. \uBE60\uB974\uAC8C\uB294 \uB204\uAD6C\uB098 \uD558\uB294\uB370 \uB290\uB9AC\uAC8C\uB294 \uC624\uB798 \uC0B0 \uC0AC\uB78C\uB9CC \uD574\uC694. \uC774\uAC74 \uC790\uB791\uC774\uC5D0\uC694, \uD6C4\uD6C4.",
          note: "\uB290\uB9AC\uAC8C \uD558\uB294 \uAC83\uC774 \uB354 \uC5B4\uB835\uB2E4\uACE0 \uD588\uB2E4. \uAC19\uC740 \uB3D9\uC791\uC744 \uBC18\uBCF5\uD558\uB294 \uB3D9\uC548 \uD55C \uBC88\uB3C4 \uC18D\uB3C4\uAC00 \uB2EC\uB77C\uC9C0\uC9C0 \uC54A\uC558\uB2E4."
        },
        {
          id: "body",
          label: "\uAD73\uC740 \uBAB8\uC744 \uD480\uB824\uB294 \uAC70\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uD480\uB9AC\uC9C4 \uC54A\uC544\uC694. \uB2E4\uB9CC \uAD73\uC740 \uCC44\uB85C \uC5B4\uB5BB\uAC8C \uC6C0\uC9C1\uC774\uB294\uC9C0 \uC775\uD788\uB294 \uC911\uC774\uC9C0\uC694. \uAD73\uC740 \uBAB8\uB3C4 \uC4F8 \uC904 \uC54C\uBA74 \uBC29\uD328\uAC00 \uB41C\uB2F5\uB2C8\uB2E4.",
          note: "\uAD73\uC740 \uBAB8\uC744 \uD478\uB294 \uAC83\uC774 \uC544\uB2C8\uB77C \uAD73\uC740 \uCC44\uB85C \uC4F0\uB294 \uBC95\uC744 \uC775\uD788\uB294 \uAC83\uC774\uB77C\uACE0 \uB2F5\uD588\uB2E4."
        }
      ]
    },
    {
      id: "ella-elder",
      prompt: "\uC5D8\uB77C\uB294 \uC65C \uC5B4\uB9B0 \uB810\uB9AD\uB4E4\uC5D0\uAC8C '\uC694\uC998 \uAC83\uB4E4'\uC774\uB77C\uACE0 \uD574?",
      choices: [
        {
          id: "scold",
          label: "\uD63C\uB0B4\uB294 \uB9D0\uC774\uB0D0\uACE0 \uC2AC\uCA4D \uBB3B\uB294\uB2E4",
          reply: "\uC544\uC774\uACE0, \uD63C\uB0B4\uB294 \uAC8C \uC544\uB2C8\uC5D0\uC694. \uADC0\uC5EC\uC6CC\uC11C \uD558\uB294 \uB9D0\uC774\uC9C0\uC694. \uC131\uC9C8\uC740 \uAE09\uD574\uB3C4 \uD558\uB294 \uC9D3\uC740 \uB2E4 \uC0AC\uB791\uC2A4\uB7FD\uC796\uC544\uC694.",
          note: "\uD63C\uB0B4\uB294 \uB9D0\uC774 \uC544\uB2C8\uB77C\uACE0 \uD588\uB2E4. \uB9D0\uC744 \uB9C8\uCE5C \uC9C1\uD6C4 \uB3C4\uB514\uAC00 \uB118\uC5B4\uC9C0\uC790 \uAC00\uC7A5 \uBA3C\uC800 \uC190\uC744 \uBED7\uC5C8\uB2E4."
        },
        {
          id: "age",
          label: "\uAC89\uBAA8\uC2B5\uC774 \uC573\uB418\uB2E4\uACE0 \uB9D0\uD574 \uBCF8\uB2E4",
          reply: "\uC5BC\uAD74\uC740 \uADF8\uB807\uC9C0\uC694. \uD558\uC9C0\uB9CC \uB9C8\uC74C\uC740 \uC774 \uB9C8\uB2F9\uC758 \uB3CC\uB9CC\uD07C \uC624\uB798\uB410\uC5B4\uC694. \uB3CC\uC774 \uB9D0\uC744 \uD558\uBA74 \uC774\uB7F0 \uB9D0\uD22C\uC77C \uAC70\uC608\uC694.",
          note: "\uC573\uB41C \uC5BC\uAD74\uC774\uB77C\uACE0 \uD558\uC790 \uD55C\uB3D9\uC548 \uBA3C \uACF3\uC744 \uBCF4\uC558\uB2E4. \uC774\uB0B4 \uB9C8\uB2F9\uC758 \uB3CC\uC744 \uD558\uB098 \uAC00\uB9AC\uCF30\uB2E4."
        },
        {
          id: "doc",
          label: "\uC2DC\uB9D0\uC11C\uB97C \uB300\uC2E0 \uC368 \uC8FC\uB294 \uAC83\uB3C4 \uADF8\uB798\uC11C\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uADF8\uAC74 \uB610 \uB2E4\uB978 \uC774\uC57C\uAE30\uC608\uC694. \uC4F4 \uC0AC\uB78C\uC740 \uB2E4\uC2DC\uB294 \uBB38\uC744 \uC548 \uBD80\uC218\uC9C0 \uC54A\uC544\uB3C4 \uB418\uB3C4\uB85D, \uC4F0\uB294 \uB9C8\uC74C\uB9CC \uC54C\uB824 \uC8FC\uACE0 \uC2F6\uC740 \uAC70\uC9C0\uC694.",
          note: "\uC2DC\uB9D0\uC11C \uC774\uC57C\uAE30\uB97C \uAEBC\uB0B4\uC790 \uBD93\uC744 \uC954 \uC190\uC774 \uBA48\uCDC4\uB2E4. \uC774\uC720\uB97C \uAE38\uAC8C \uB9D0\uD558\uC9C0 \uC54A\uACE0 \uC6C3\uAE30\uB9CC \uD588\uB2E4."
        }
      ]
    }
  ],
  bondStories: { 4: CHAPTER_46, 6: CHAPTER_66, 8: CHAPTER_86, 10: CHAPTER_106 },
  bondLines: [
    // 0 — 낯선 사이. 점잖고 느긋한 해요체.
    ["\uCC98\uC74C \uBD59\uACA0\uC5B4\uC694, \uC5D8\uB77C\uC608\uC694. \uB290\uB9AC\uAC8C \uAC77\uB294 \uD3B8\uC774\uB77C \uBA3C\uC800 \uAC00\uC154\uB3C4 \uC88B\uC544\uC694. \uC81C \uAC78\uC74C\uC740 \uC18C\uB9AC\uAC00 \uC5C6\uC73C\uB2C8 \uB180\uB77C\uC9C0 \uB9C8\uC138\uC694.", "\uC5F0\uAD6C\uC6D0, \uC774\uB807\uAC8C \uBD88\uB7EC\uB3C4 \uB418\uC9C0\uC694? \uBD80\uB974\uAE30 \uC26C\uC6B4 \uB9D0\uC774 \uC624\uB798 \uAC00\uB294 \uBC95\uC774\uB77C\uC11C\uC694.", "\uC800\uB294 \uB9C8\uB2F9\uC5D0 \uC788\uC5B4\uC694. \uAE09\uD55C \uC77C\uC774 \uC544\uB2C8\uBA74 \uC640\uC11C \uCC9C\uCC9C\uD788 \uB9D0\uC500\uD558\uC138\uC694."],
    // 1
    ["\uC624\uB298\uB3C4 \uB9C8\uB2F9\uC5D0 \uB098\uAC00\uC694. \uAC19\uC740 \uB3D9\uC791\uC774\uB77C\uB3C4 \uC5B4\uC81C\uC640\uB294 \uC870\uAE08 \uB2EC\uB77C\uC694. \uADF8\uAC78 \uC54C\uC544\uBCF4\uB294 \uC7AC\uBBF8\uAC00 \uC788\uC9C0\uC694.", "\uC694\uC998 \uAC83\uB4E4\uC740 \uC131\uC9C8\uC774 \uAE09\uD574\uC11C\uC694, \uD5C8\uD5C8. \uADF8\uB798\uB3C4 \uC5F0\uAD6C\uC6D0\uC740 \uC11C\uB450\uB974\uC9C0 \uC54A\uC544 \uBCF4\uC5EC\uC11C \uC88B\uC544\uC694.", "\uC774\uB9C8\uC758 \uBD80\uC801\uC740 \uC2E0\uACBD \uC4F0\uC9C0 \uB9C8\uC138\uC694. \uC624\uB798\uB41C \uC2B5\uAD00 \uAC19\uC740 \uAC70\uC608\uC694."],
    // 2
    ["\uC190\uBAA9\uC744 \uC774\uB807\uAC8C \uC0B4\uC9DD \uB3CC\uB9AC\uBA74 \uD070 \uD798\uC774 \uBE44\uAEF4\uAC00\uC694. \uBC1C\uACBD\uC740 \uD798\uC73C\uB85C \uD558\uB294 \uAC8C \uC544\uB2C8\uB77C \uAE38\uC744 \uC5F4\uC5B4 \uC8FC\uB294 \uC77C\uC774\uC5D0\uC694.", "\uBE44 \uC62C \uAC83 \uAC19\uC740 \uB0A0\uC740 \uCC98\uB9C8 \uBC11\uC5D0 \uBBF8\uB9AC \uC640 \uC788\uC5B4\uC694. \uC81C\uAC00 \uBA3C\uC800 \uC549\uC544 \uC788\uC73C\uBA74 \uC5F0\uAD6C\uC6D0\uB3C4 \uC62C \uACF3\uC774 \uC0DD\uAE30\uB2C8\uAE4C\uC694.", "\uAC77\uB294 \uC18C\uB9AC\uAC00 \uC548 \uB09C\uB2E4\uACE0 \uB180\uB77C\uC2DC\uB358\uB370, \uBCF5\uB3C4\uC5D0\uC11C \uB9C8\uC8FC\uCE58\uBA74 \uBA3C\uC800 \uD5DB\uAE30\uCE68\uC774\uB77C\uB3C4 \uD560\uAE4C\uC694?"],
    // 3
    ["\uC810(\u7C98)\uC740 \uBD99\uB294 \uAC70\uC608\uC694. \uC0C1\uB300\uAC00 \uC624\uBA74 \uB193\uCE58\uC9C0 \uC54A\uACE0 \uD55C \uBC88 \uBD99\uB4E4\uC9C0\uC694. \uBD99\uB4E4\uACE0 \uB098\uBA74 \uB9C8\uC74C\uC774 \uB193\uC5EC\uC694.", "\uC5B4\uB9B0 \uB810\uB9AD\uB4E4\uC774 \uB2EC\uB824\uB4E4 \uB54C\uB9C8\uB2E4 \uD558\uB098\uC529 \uBC1B\uC544 \uC8FC\uB294 \uAC8C \uD558\uB8E8\uC758 \uB099\uC774\uC5D0\uC694. \uB118\uC5B4\uB728\uB824\uB3C4 \uB2E4\uCE58\uC9C4 \uC54A\uC544\uC694.", "\uC5F0\uAD6C\uC6D0\uC774 \uC640 \uC8FC\uC2DC\uBA74 \uB9C8\uB2F9\uC774 \uC870\uAE08 \uB354 \uD658\uD574\uC838\uC694. \uC774\uAC74 \uCE6D\uCC2C\uC774\uB2C8 \uADF8\uB0E5 \uBC1B\uC73C\uC138\uC694, \uD6C4\uD6C4."],
    // 4 — 장 4 이후: 비 오는 날 처마 밑.
    ["\uC624\uB298\uB3C4 \uBE44\uAC00 \uC624\uB124\uC694. \uCC98\uB9C8 \uBC11 \uC790\uB9AC\uB97C \uBE44\uC6CC \uB480\uC5B4\uC694. \uC5F0\uAD6C\uC6D0 \uC790\uB9AC\uB294 \uB298 \uAC19\uC740 \uCABD\uC774\uC5D0\uC694.", "\uBE44 \uC624\uB294 \uB0A0\uC740 \uC18C\uB9AC\uAC00 \uC88B\uC544\uC694. \uBE57\uBC29\uC6B8 \uAC04\uACA9\uC744 \uC138\uB2E4 \uBCF4\uBA74 \uD558\uB8E8\uAC00 \uAE08\uBC29 \uAC00\uC694.", "\uBE44 \uC624\uB294 \uB0A0\uC5D0 \uB3C4\uB514\uC640 \uD30C\uB8E8\uC544\uAC00 \uB9C8\uB2F9\uC744 \uB6F0\uC5B4\uB2E4\uB2C8\uB294 \uAC8C \uC88B\uC544\uC694. \uAD6C\uACBD\uB9CC \uD574\uB3C4 \uC816\uC740 \uAE30\uBD84\uC774 \uB4E4\uC5B4\uC694."],
    // 5
    ["\uD654(\u5316)\uB294 \uD480\uC5B4 \uC8FC\uB294 \uAC70\uC608\uC694. \uC0C1\uB300\uC758 \uD798\uC774 \uAC08 \uACF3\uC744 \uC783\uC73C\uBA74 \uC800\uC808\uB85C \uD480\uB824\uC694. \uC2F8\uC6C0\uB3C4 \uB9C8\uC74C\uB3C4 \uBE44\uC2B7\uD574\uC694.", "\uC544\uC774\uB4E4\uC5D0\uAC8C \uCC9C\uCC9C\uD788 \uD558\uB294 \uBC95\uC744 \uAC00\uB974\uCE58\uB294 \uC911\uC774\uC5D0\uC694. \uCC98\uC74C\uC5D4 \uC5B4\uB824\uC6CC\uB3C4 \uBAB8\uC774 \uBA3C\uC800 \uC54C\uC544\uCC44\uC694.", "\uC5F0\uAD6C\uC6D0\uB3C4 \uC228\uC774 \uAC00\uC060 \uB550 \uD55C \uD314\uB9CC \uCC9C\uCC9C\uD788 \uB4E4\uC5B4 \uBCF4\uC138\uC694. \uADF8\uAC83\uB9CC\uC73C\uB85C\uB3C4 \uC2DC\uAC04\uC774 \uB290\uB824\uC838\uC694."],
    // 6 — 장 6 이후: 느리게 하는 힘.
    ["\uC624\uB298 \uC544\uCE68\uC5D4 \uB9C8\uB2F9\uC5D0\uC11C \uC544\uBB34\uB3C4 \uB6F0\uC9C0 \uC54A\uC558\uC5B4\uC694. \uB2E4\uB4E4 \uCC9C\uCC9C\uD788 \uAC77\uAE38\uB798 \uAD1C\uD788 \uBFCC\uB4EF\uD588\uC9C0\uC694.", "\uC5F0\uAD6C\uC6D0\uC758 \uC5B4\uAE68\uAC00 \uCC98\uC74C\uBCF4\uB2E4 \uB9CE\uC774 \uB0B4\uB824\uAC14\uC5B4\uC694. \uADF8\uAC8C \uC81C\uC77C \uD070 \uC218\uB828\uC774\uC5D0\uC694.", "\uC11C\uB450\uB974\uB294 \uC138\uC0C1\uC5D0\uC11C \uB290\uB9AC\uAC8C \uC11C \uC788\uB294 \uAC74 \uC6A9\uAE30\uAC00 \uC788\uC5B4\uC57C \uD574\uC694. \uC5F0\uAD6C\uC6D0\uC740 \uC6A9\uAE30\uAC00 \uC788\uC73C\uC138\uC694."],
    // 7
    ["\uBC1C(\u767C)\uC740 \uBCF4\uB0B4\uB294 \uAC70\uC608\uC694. \uBD99\uB4E4\uACE0 \uD480\uACE0 \uB098\uC11C \uAC00\uB358 \uBC29\uD5A5\uC73C\uB85C \uD55C \uBC88\uC5D0 \uB0B4\uBCF4\uB0B4\uC9C0\uC694. \uB9C8\uC9C0\uB9C9\uC774 \uAC00\uC7A5 \uC9E7\uC544\uC694.", "\uC778(\u5F15)\uC740 \uB04C\uC5B4\uB2F9\uAE30\uB294 \uD798\uC774\uC5D0\uC694. \uC81C \uCABD\uC73C\uB85C \uC624\uAC8C \uB9CC\uB4E4\uBA74 \uC800\uB294 \uAC00\uB9CC\uD788 \uC788\uC5B4\uB3C4 \uB418\uB2C8\uAE4C\uC694.", "\uC800\uB294 \uAE09\uD560 \uAC8C \uC5C6\uC5B4\uC11C \uC11C \uC788\uB294 \uCABD\uC774 \uD3B8\uD574\uC694."],
    // 8 — 장 8 이후: 시말서.
    ["\uBD93 \uC954 \uC190\uC774 \uC624\uB298\uC740 \uAC00\uBCBC\uC6CC\uC694. \uB4A4\uC5D0\uC11C \uC9C0\uCF1C\uBCF4\uB294 \uAC83\uB3C4 \uD574 \uBCF4\uB2C8 \uD560 \uB9CC\uD558\uB124\uC694.", "\uBA39\uC774 \uC9C4\uD560\uC218\uB85D \uAE00\uC528\uAC00 \uC624\uB798 \uAC00\uC694. \uADF8\uB798\uC11C \uC2DC\uB9D0\uC11C\uB9CC\uD07C\uC740 \uBA39\uC744 \uC815\uC131\uC2A4\uB808 \uAC08\uC9C0\uC694.", "\uC5F0\uAD6C\uC6D0, \uBC24\uB2A6\uAC8C\uAE4C\uC9C0 \uBD88 \uCF1C \uB450\uBA74 \uB208 \uC0C1\uD574\uC694. \uC800\uB294 \uAD1C\uCC2E\uC73C\uB2C8 \uBA3C\uC800 \uC26C\uC138\uC694."],
    // 9
    ["\uAD73\uC740 \uBAB8\uC73C\uB85C\uB3C4 \uC624\uB298\uC740 \uACC4\uB2E8\uC744 \uC18C\uB9AC \uC5C6\uC774 \uB450 \uBC88 \uC62C\uB790\uC5B4\uC694. \uBABB \uB4E4\uC73C\uC168\uC8E0? \uD6C4\uD6C4.", "\uBE44\uAC00 \uC62C \uAC83 \uAC19\uC740 \uB0A0, \uC694\uC998\uC740 \uB9C8\uB2F9\uC5D0 \uBA3C\uC800 \uB098\uAC00 \uBCFC\uAE4C \uACE0\uBBFC\uC774 \uB3FC\uC694. \uC544\uC8FC \uC870\uAE08\uC694.", "\uC5F0\uAD6C\uC6D0\uC774 \uACC1\uC5D0 \uC788\uC73C\uB2C8 \uB9C8\uC74C\uC774 \uB193\uC5EC\uC694. \uBE44 \uC624\uB294 \uB0A0 \uB9C8\uB2F9\uC774 \uB35C \uC4F8\uC4F8\uD558\uB124\uC694."],
    // 10 — 마음을 연 사이. 비를 맞아도 괜찮은 사이.
    ["\uC5F0\uAD6C\uC6D0, \uC624\uB298 \uBE44\uB294 \uB9DE\uC544\uB3C4 \uAD1C\uCC2E\uACA0\uC5B4\uC694. \uAC19\uC774 \uC11C \uC904 \uC0AC\uB78C\uC774 \uC788\uC73C\uB2C8\uAE4C\uC694. \uC544\uC8FC \uC2DC\uC6D0\uD560 \uAC70\uC608\uC694.", "\uBD80\uC801\uC740 \uC18C\uB9E4 \uC548\uCABD\uC5D0 \uB123\uC5B4 \uB480\uC5B4\uC694. \uC816\uC744 \uB550 \uAC19\uC774 \uC816\uB294\uB2E4\uACE0 \uC57D\uC18D\uD588\uC73C\uB2C8\uAE4C\uC694.", "\uB2E4\uC74C\uC5D4 \uC6B0\uC0B0 \uC5C6\uC774 \uB098\uAC00\uC694. \uAC10\uAE30\uB294 \uAC78\uB824\uB3C4 \uAC19\uC774 \uAC78\uB9AC\uBA74 \uB418\uB2C8\uAE4C\uC694. \uD6C4\uD6C4."]
  ]
};

