init_define_import_meta_env();
var CHAPTER_412 = {
  id: "bond.pachi.4",
  startNodeId: "n1",
  titleCard: { title: "\uBD80\uC11C\uC9C4 \uACBD\uCCA9", subtitle: "\uD30C\uCE58 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 1" },
  nodes: [
    { id: "n1", speaker: "", body: "\uCF00\uC5B4\uC2E4 \uC55E \uBCF5\uB3C4. \uBB38\uC9DD \uD558\uB098\uAC00 \uBE44\uC2A4\uB4EC\uD788 \uAE30\uB300\uC5B4 \uC11C \uC788\uACE0 \uBC14\uB2E5\uC5D0\uB294 \uACBD\uCCA9 \uC870\uAC01\uC774 \uD769\uC5B4\uC838 \uC788\uB2E4. \uADF8 \uC606\uC5D0\uC11C \uC548\uC804\uBAA8\uB97C \uC4F4 \uD30C\uCE58\uAC00 \uC785\uC5D0 \uC0AC\uD0D5\uC744 \uBB3C\uACE0 \uD314\uC9F1\uC744 \uB07C\uACE0 \uC788\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uD30C\uCE58", body: "\uC544, \uC544\uB2C8\uC57C. \uC774\uBC88\uC5D4 \uB0B4\uAC00 \uD55C \uAC70 \uC544\uB2C8\uAC70\uB4E0. \uBB38\uC774 \uBA3C\uC800 \uB098\uC654\uC5B4. \uB098\uB294 \uADF8\uB0E5 \uC9C0\uB098\uAC00\uB824\uACE0 \uD588\uC744 \uBFD0\uC774\uC57C.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uACBD\uCCA9 \uC790\uAD6D \uC704\uC5D0 \uC548\uC804\uBAA8\uC640 \uAC19\uC740 \uB192\uC774\uC758 \uD760\uC9D1\uC774 \uC120\uBA85\uD558\uAC8C \uB098 \uC788\uB2E4. \uD30C\uCE58\uAC00 \uBAA8\uB978 \uCC99 \uC2DC\uC120\uC744 \uB3CC\uB9AC\uC790 \uC785 \uC548\uC758 \uC0AC\uD0D5\uC774 \uC774\uC5D0 \uBD80\uB52A\uD600 \uB531 \uC18C\uB9AC\uB97C \uB0B8\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uBCF5\uC6D0 \uCCAB\uB0A0\uC5D0\uB3C4 \uAC19\uC740 \uBB38\uD2C0\uC774\uC5C8\uB2E4. \uD30C\uCE58\uB294 \uC54C\uBA74\uC11C\uB3C4 \uAC19\uC740 \uC790\uB9AC\uC5D0\uC11C \uBD80\uB52A\uD614\uB2E4.)", choices: [
      { id: "ask", label: "\uC65C \uC790\uAFB8 \uBA38\uB9AC\uB85C \uBC1B\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4", nextId: "n5a" },
      { id: "tool", label: "\uB9D0\uC5C6\uC774 \uACF5\uAD6C\uD568\uC744 \uAC00\uC838\uC628\uB2E4", nextId: "n5b" }
    ] },
    { id: "n5a", speaker: "\uD30C\uCE58", body: "\u2026\uC55E\uC774 \uC548 \uBCF4\uC5EC\uC11C \uADF8\uB798\uC694, \uBCF4\uC2A4. \uBB38\uC774 \uC788\uB294 \uC904 \uC54C\uBA74 \uACE0\uAC1C\uB97C \uC219\uC774\uB294\uB370, \uC548 \uBCF4\uC774\uBA74 \uADF8\uB0E5 \uAC00\uAC70\uB4E0\uC694. \uBCC0\uBA85 \uC544\uB2C8\uC5D0\uC694.", nextId: "n6" },
    { id: "n5b", speaker: "\uD30C\uCE58", body: "\u2026\uBB50\uC608\uC694, \uADF8\uAC74. \uACE0\uCE58\uB77C\uB294 \uAC70\uC608\uC694? \uC544, \uC54C\uC558\uC5B4\uC694, \uC54C\uC558\uB2E4\uACE0\uC694. \uB204\uAC00 \uC548 \uD55C\uB300\uC694?", nextId: "n6" },
    { id: "n6", speaker: "", body: "\uD30C\uCE58\uAC00 \uD55C\uCC38 \uD22C\uB35C\uB300\uB2E4\uAC00 \uCB48\uADF8\uB824 \uC549\uC544 \uACBD\uCCA9 \uC870\uAC01\uC744 \uD558\uB098\uC529 \uC90D\uB294\uB2E4. \uC190\uC740 \uAC70\uCE60\uC9C0\uB9CC \uBAA8\uC73C\uB294 \uC21C\uC11C\uB294 \uC815\uD655\uD558\uB2E4. \uC0AC\uD0D5 \uAECD\uC9C8\uC774 \uC8FC\uBA38\uB2C8\uC5D0\uC11C \uAC19\uC774 \uB538\uB824 \uB098\uC628\uB2E4.", nextId: "n7" },
    { id: "n7", speaker: "\uB3C4\uB514", body: "\uD30C\uCE58! \uB610 \uBB38 \uBD80\uC248\uC5B4? \uAE30\uB85D\uD574\uC57C \uD558\uB294\uB370! \uC774\uAC8C \uC138 \uBC88\uC9F8\uC57C, \uC54C\uC9C0?", nextId: "n8" },
    { id: "n8", speaker: "\uD30C\uCE58", body: "\uC138\uC9C0 \uB9C8! \uC54C\uC558\uC5B4, \uAE30\uB85D\uD574. \uADFC\uB370 \uACE0\uCE58\uB294 \uAC83\uB3C4 \uAC19\uC774 \uAE30\uB85D\uD574. \uBD80\uC21C \uAC83\uB9CC \uC4F0\uBA74 \uBD88\uACF5\uD3C9\uD558\uC796\uC544.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uB3C4\uB514\uAC00 \uB180\uB780 \uB208\uC73C\uB85C \uC218\uCCA9\uC5D0 \uD55C \uC904\uC744 \uB354 \uC801\uB294\uB2E4. \uD30C\uCE58\uAC00 \uB4DC\uB77C\uC774\uBC84\uB97C \uBE44\uB6A4\uAC8C \uC950\uACE0 \uB098\uC0AC\uB97C \uB3CC\uB9AC\uC790, \uBB38\uC9DD\uC774 \uCC9C\uCC9C\uD788 \uC81C \uC790\uB9AC\uB85C \uB3CC\uC544\uC628\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uD30C\uCE58", body: "\u2026\uB2E4 \uB410\uC5B4\uC694, \uBCF4\uC2A4. \uC774\uBC88\uC5D4 \uC548 \uBD80\uC218\uACE0 \uACE0\uCCE4\uC5B4\uC694. \uADFC\uB370 \uB2E4\uC74C\uC5D0 \uB610 \uBD80\uC218\uBA74 \uC5B4\uCA4C\uC8E0. \uADF8\uAC74 \uADF8\uB54C \uC0DD\uAC01\uD574\uC694." }
  ]
};
var CHAPTER_612 = {
  id: "bond.pachi.6",
  startNodeId: "n1",
  titleCard: { title: "\uC0AC\uD0D5 \uAECD\uC9C8\uC744 \uC90D\uB294 \uB0A0", subtitle: "\uD30C\uCE58 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 2" },
  nodes: [
    { id: "n1", speaker: "", body: "\uD574 \uC9C8 \uB158\uC758 \uC911\uC815. \uBCA4\uCE58 \uBC11\uACFC \uD654\uB2E8 \uAC00\uC7A5\uC790\uB9AC\uC5D0 \uCCB4\uB9AC\uC0C9 \uC0AC\uD0D5 \uAECD\uC9C8\uC774 \uAE38\uC744 \uB530\uB77C \uC810\uC810\uC774 \uB5A8\uC5B4\uC838 \uC788\uB2E4. \uADF8 \uB05D\uC5D0 \uD30C\uCE58\uAC00 \uC788\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uCF04\uD1A0", body: "\uC57C, \uC774\uAC70 \uC804\uBD80 \uB124 \uAC70\uC9C0? \uC774\uAC8C \uB300\uCCB4 \uBA87 \uAC1C\uC57C. \uCCAD\uC18C \uB2F4\uB2F9\uC774 \uC6B8\uACA0\uB2E4.", nextId: "n3" },
    { id: "n3", speaker: "\uD30C\uCE58", body: "\uC54C\uC558\uB2E4\uACE0! \uC8FC\uC6B8 \uAC70\uC57C! \uC9C0\uAE08 \uB9C9 \uC8FC\uC6B0\uB824\uB358 \uCC38\uC774\uC5C8\uC5B4. \uB9D0\uD558\uAE30 \uC804\uBD80\uD130 \uC8FC\uC6B0\uB824\uACE0 \uD588\uB2E4\uACE0.", nextId: "n4" },
    { id: "n4", speaker: "", body: "\uCF04\uD1A0\uAC00 \uAECC\uC744 \uC539\uC73C\uBA70 \uB208\uC379\uC744 \uC62C\uB9B0\uB2E4. \uD30C\uCE58\uAC00 \uB208\uC744 \uAD74\uB9AC\uBA70 \uD5C8\uB9AC\uB97C \uC219\uC774\uACE0, \uD55C \uAC1C\uC529 \uC9D1\uC5B4 \uB4E4 \uB54C\uB9C8\uB2E4 \uC8FC\uBA38\uB2C8\uC5D0 \uB123\uB294\uB2E4. \uD55C \uAC1C\uB3C4 \uBE7C\uBA39\uC9C0 \uC54A\uB294\uB2E4.", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uD30C\uCE58\uAC00 \uC90D\uB294 \uC18D\uB3C4\uAC00 \uC810\uC810 \uB290\uB824\uC9C4\uB2E4. \uAECD\uC9C8 \uD558\uB098\uB97C \uC624\uB798 \uB4E4\uC5EC\uB2E4\uBCF4\uACE0 \uC788\uB2E4.)", choices: [
      { id: "help", label: "\uC606\uC5D0\uC11C \uAC19\uC774 \uC90D\uB294\uB2E4", nextId: "n6a" },
      { id: "ask", label: "\uC65C \uC790\uAFB8 \uBC84\uB9AC\uB290\uB0D0\uACE0 \uBB3C\uC5B4\uBCF8\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uD30C\uCE58", body: "\u2026\uBCF4\uC2A4\uAE4C\uC9C0 \uC8FC\uC6B8 \uD544\uC694\uB294 \uC5C6\uC5B4\uC694. \uC81C \uAC70\uC796\uC544\uC694. \uADFC\uB370 \uAC19\uC774 \uD574 \uC8FC\uC2DC\uBA74 \uBE68\uB9AC \uB05D\uB098\uAE34 \uD558\uACA0\uB124\uC694. \uC544, \uACE0\uB9C8\uC6CC\uC694.", nextId: "n7" },
    { id: "n6b", speaker: "\uD30C\uCE58", body: "\uBC84\uB9AC\uB824\uACE0 \uBC84\uB9AC\uB294 \uAC8C \uC544\uB2C8\uB77C\uC694. \uC0AC\uD0D5 \uBA39\uB2E4 \uBCF4\uBA74 \uC190\uC774 \uBC14\uBE60\uC11C \uC78A\uC5B4\uBC84\uB824\uC694. \uC78A\uC5B4\uBC84\uB838\uB2E4\uB294 \uAC78 \uC544\uB294 \uC21C\uAC04\uC5D0\uB294 \uC774\uBBF8 \uD55C\uCC38 \uB4A4\uACE0\uC694.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uB9C8\uC9C0\uB9C9 \uAECD\uC9C8\uC744 \uC90D\uACE0 \uC77C\uC5B4\uC11C\uB824\uB294\uB370 \uC548\uC804\uBAA8 \uCC59\uC774 \uD654\uB2E8 \uAC00\uC9C0\uC5D0 \uAC78\uB9B0\uB2E4. \uD30C\uCE58\uAC00 \uC228\uC744 \uD55C \uBC88 \uD06C\uAC8C \uB0B4\uC26C\uACE0 \uCC9C\uCC9C\uD788 \uACE0\uAC1C\uB97C \uC219\uC5EC \uAC00\uC9C0\uB97C \uD53C\uD55C\uB2E4. \uBD80\uC218\uC9C0 \uC54A\uB294\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "\uCF04\uD1A0", body: "\u2026\uC624, \uBD80\uC218\uC9C0 \uC54A\uC558\uB124. \uB300\uB2E8\uD55C\uB370? \uBC15\uC218 \uCCD0 \uC904\uAE4C?", nextId: "n9" },
    { id: "n9", speaker: "\uD30C\uCE58", body: "\uB180\uB9AC\uC9C0 \uB9C8! \uC774 \uC815\uB3C4\uB294 \uB098\uB3C4 \uD574! \uAC00\uB054\uC740\u2026 \uAC00\uB054\uC740 \uD560 \uC218 \uC788\uB2E4\uACE0.", nextId: "n10" },
    { id: "n10", speaker: "\uD30C\uCE58", body: "\uBCF4\uC2A4, \uC9C0\uC801\uBC1B\uB294 \uAC70 \uC2EB\uC5B4\uC694. \uADFC\uB370 \uC9C0\uC801\uBC1B\uACE0 \uC8FC\uC6B0\uBA74 \uADF8\uB2E4\uC74C\uC5D4 \uC548 \uBC84\uB9AC\uAC8C \uB418\uB354\uB77C\uACE0\uC694. \uADF8\uAC8C \uB354 \uC2EB\uC5B4\uC694. \uB9DE\uB294 \uB9D0\uC774\uB77C\uC11C\uC694." }
  ]
};
var CHAPTER_812 = {
  id: "bond.pachi.8",
  startNodeId: "n1",
  titleCard: { title: "\uC55E\uAE38\uC744 \uB6AB\uB294 \uC790\uB9AC", subtitle: "\uD30C\uCE58 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 3" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC784\uBB34 \uB3C4\uC911\uC758 \uC881\uC740 \uD1B5\uB85C. \uC704\uCABD\uC5D0\uC11C \uB099\uC11D\uC774 \uC3DF\uC544\uC9C8 \uAE30\uBBF8\uAC00 \uC788\uACE0, \uB4A4\uC5D0\uC11C\uB294 \uD2F0\uC544\uC640 \uC720\uD2F0\uAC00 \uC870\uC2EC\uC2A4\uB808 \uB530\uB77C\uC624\uACE0 \uC788\uB2E4. \uD30C\uCE58\uAC00 \uAC00\uC7A5 \uC55E\uC5D0 \uC11C \uC788\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uD1B5\uB85C \uC911\uAC04\uC5D0\uC11C \uCC9C\uC7A5\uC774 \uD55C \uBC88 \uC6B8\uB9B0\uB2E4. \uBA3C\uC9C0\uAC00 \uC3DF\uC544\uC9C4\uB2E4.)", nextId: "n3" },
    { id: "n3", speaker: "\uD30C\uCE58", body: "\uBCF4\uC2A4, \uC5EC\uAE30\uC11C \uB9C9\uC744\uAC8C\uC694. \uB2E4 \uC9C0\uB098\uAC08 \uB54C\uAE4C\uC9C0\uC694. \uBA3C\uC800 \uAC00\uB77C\uACE0 \uD558\uC138\uC694. \uD22C\uB35C\uB300\uB294 \uAC74 \uB098\uC911\uC5D0 \uD560\uAC8C\uC694.", nextId: "n4" },
    { id: "n4", speaker: "", body: "\uD30C\uCE58\uAC00 \uC548\uC804\uBAA8\uB97C \uACE0\uCCD0 \uC4F0\uACE0 \uB450 \uBC1C\uC744 \uBC8C\uB824 \uD1B5\uB85C \uD55C\uAC00\uC6B4\uB370\uB97C \uB9C9\uACE0 \uC120\uB2E4. \uC0AC\uD0D5\uC740 \uC5B4\uB290\uC0C8 \uC785\uC5D0\uC11C \uBE60\uC838 \uC8FC\uBA38\uB2C8\uB85C \uB4E4\uC5B4\uAC00 \uC788\uB2E4. \uC7A5\uB09C\uAE30\uB294 \uC5B4\uB514\uC5D0\uB3C4 \uC5C6\uB2E4.", nextId: "n5" },
    { id: "n5", speaker: "\uD2F0\uC544", body: "\uD30C, \uD30C\uCE58! \uBA3C\uC9C0\uAC00 \uC5C4\uCCAD \uB5A8\uC5B4\uC838! \uBC18\uC9DD\uC774\uB294 \uAC74 \uD558\uB098\uB3C4 \uC5C6\uC5B4!", nextId: "n6" },
    { id: "n6", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uB099\uC11D \uC18C\uB9AC\uAC00 \uC810\uC810 \uCEE4\uC9C4\uB2E4. \uD30C\uCE58\uC758 \uC5B4\uAE68\uAC00 \uC544\uC8FC \uC870\uAE08 \uB5A8\uB9B0\uB2E4.)", choices: [
      { id: "trust", label: "\uBBFF\uACE0 \uC788\uB2E4\uACE0 \uB9D0\uD558\uACE0 \uBAA8\uB450\uB97C \uBA3C\uC800 \uBCF4\uB0B8\uB2E4", nextId: "n7a" },
      { id: "swap", label: "\uAD50\uB300\uD574 \uC8FC\uACA0\uB2E4\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n7b" }
    ] },
    { id: "n7a", speaker: "\uD30C\uCE58", body: "\u2026\uB2F9\uC5F0\uD788 \uBBFF\uC5B4\uC57C\uC8E0. \uC81C\uAC00 \uD558\uB294 \uAC74 \uC11C \uC788\uB294 \uAC83\uBFD0\uC774\uB2C8\uAE4C\uC694. \uAC00\uC694, \uBCF4\uC2A4. \uC804 \uB9C8\uC9C0\uB9C9\uC5D0 \uB530\uB77C\uAC08\uAC8C\uC694.", nextId: "n8" },
    { id: "n7b", speaker: "\uD30C\uCE58", body: "\uAD50\uB300\uC694? \uC548 \uB3FC\uC694. \uC5EC\uAE30\uB294 \uC81C \uC790\uB9AC\uC608\uC694. \uBCF4\uC2A4\uAC00 \uC815\uD574 \uC900 \uC790\uB9AC\uB77C\uC11C\uC694. \uC815\uD574 \uC92C\uC73C\uB2C8\uAE4C \uC9C0\uD0AC\uAC8C\uC694.", nextId: "n8" },
    { id: "n8", speaker: "", body: "\uB4A4\uB530\uB974\uB358 \uC774\uB4E4\uC774 \uD558\uB098\uC529 \uD30C\uCE58\uC758 \uC606\uC744 \uC9C0\uB098\uAC04\uB2E4. \uC720\uD2F0\uAC00 \uC9C0\uB098\uAC00\uBA70 \uD30C\uCE58\uC758 \uC548\uC804\uBAA8\uB97C \uD1A1 \uAC74\uB4DC\uB9AC\uACE0 \uAC04\uB2E4. \uD30C\uCE58\uB294 \uC54C\uC544\uCC44\uACE0\uB3C4 \uBAA8\uB978 \uCC99\uD55C\uB2E4.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uB9C8\uC9C0\uB9C9 \uD55C \uBA85\uC774 \uC9C0\uB098\uAC00\uC790 \uCC9C\uC7A5\uC774 \uD06C\uAC8C \uBB34\uB108\uC9C4\uB2E4. \uD30C\uCE58\uAC00 \uB9C8\uC9C0\uB9C9\uC73C\uB85C \uBAB8\uC744 \uB3CC\uB824 \uB2EC\uB824 \uB098\uC628 \uC9C1\uD6C4 \uD1B5\uB85C \uC785\uAD6C\uAC00 \uBA3C\uC9C0\uB85C \uAC00\uB4DD \uCC2C\uB2E4.", cue: "rumble", nextId: "n10" },
    { id: "n10", speaker: "\uD30C\uCE58", body: "\u2026\uB2E4 \uC9C0\uB098\uAC14\uC8E0, \uBCF4\uC2A4? \uD55C \uBA85\uB3C4 \uC548 \uBE60\uC84C\uC8E0? \uADF8\uB7FC \uB410\uC5B4\uC694. \uBA38\uB9AC\uB294 \uC880 \uC6B8\uB9AC\uC9C0\uB9CC\uC694. \uC548\uC804\uBAA8 \uC4F0\uAE38 \uC798\uD588\uB124\uC694. \uC774\uAC74 \uD22C\uB35C\uB300\uC9C0 \uC54A\uC744\uAC8C\uC694." }
  ]
};
var CHAPTER_1012 = {
  id: "bond.pachi.10",
  startNodeId: "n1",
  titleCard: { title: "\uC548\uC804\uBAA8\uB97C \uBC97\uB294 \uBC24", subtitle: "\uD30C\uCE58 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 4" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC5F0\uAD6C\uC18C\uAC00 \uC7A0\uB4E0 \uBC24\uC758 \uC625\uC0C1 \uACC4\uB2E8. \uD30C\uCE58\uAC00 \uD63C\uC790 \uC549\uC544 \uC0AC\uD0D5\uC744 \uBB3C\uACE0 \uC788\uB2E4. \uC548\uC804\uBAA8\uB294 \uBB34\uB98E \uC704\uC5D0 \uC62C\uB824\uC838 \uC788\uB2E4. \uC5F0\uAD6C\uC6D0\uC774 \uC62C\uB77C\uC624\uC790 \uD30C\uCE58\uAC00 \uAE09\uD788 \uBAA8\uC790\uB97C \uB04C\uC5B4\uB2F9\uACA8 \uC4F0\uB824 \uD55C\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uD30C\uCE58", body: "\uC544, \uBCF4\uC2A4. \uC548 \uC790\uC694? \uC544\uB2C8, \uC548 \uC790\uB3C4 \uB418\uB294\uB370, \uC548\uC804\uBAA8\uB294 \uC9C0\uAE08 \uB9C9 \uBC97\uC740 \uAC70\uB77C\u2026 \uC544, \uC544\uB2C8, \uBA38\uB9AC\uAC00 \uAC00\uB824\uC6CC\uC11C\uC694!", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uC548\uC804\uBAA8\uB97C \uC4F0\uB824\uB358 \uC190\uC774 \uBA48\uCD98\uB2E4. \uD30C\uCE58\uAC00 \uD55C\uC228\uC744 \uC26C\uACE0 \uC548\uC804\uBAA8\uB97C \uB2E4\uC2DC \uBB34\uB98E\uC5D0 \uB0B4\uB824\uB193\uB294\uB2E4. \uBA38\uB9AC \uC717\uBA74\uC5D0\uB294 \uC624\uB79C \uBD80\uB52A\uD798\uC73C\uB85C \uB2E8\uB2E8\uD788 \uAD73\uC740 \uC790\uAD6D\uC774 \uB0A8\uC544 \uC788\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uD30C\uCE58", body: "\u2026\uC774\uAC70 \uC4F0\uAE30 \uC2DC\uC791\uD55C \uAC74 \uACBD\uCCA9\uC744 \uBD80\uC21C \uB0A0\uC774\uC5C8\uC5B4\uC694. \uBCF4\uC2A4\uAC00 \uC50C\uC6CC \uC92C\uC8E0. \uADF8\uB0A0 \uC774\uD6C4\uB85C \uC548 \uBC97\uC5C8\uC5B4\uC694. \uBC97\uC73C\uBA74 \uB610 \uBB58 \uBD80\uC220 \uAC83 \uAC19\uC544\uC11C\uC694.", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uD30C\uCE58\uAC00 \uC548\uC804\uBAA8\uB97C \uC870\uC2EC\uC2A4\uB7FD\uAC8C \uC4F0\uB2E4\uB4EC\uB294\uB2E4. \uD760\uC9D1\uC774 \uC5EC\uB7FF\uC774\uB2E4. \uD558\uB098\uD558\uB098 \uD30C\uCE58\uAC00 \uC9C0\uCF1C \uB0B8 \uC21C\uAC04\uC774\uB2E4.)", choices: [
      { id: "keep", label: "\uACC4\uC18D \uC4F0\uACE0 \uC788\uC5B4\uB3C4 \uB41C\uB2E4\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n6a" },
      { id: "try", label: "\uC624\uB298\uC740 \uBC97\uC740 \uCC44\uB85C \uC788\uC5B4 \uBCF4\uC790\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uD30C\uCE58", body: "\u2026\uADF8\uB807\uC8E0? \uC774\uAC74 \uC800\uD55C\uD14C \uB9DE\uB294 \uBAA8\uC790\uC608\uC694. \uADFC\uB370 \uAC00\uB054 \uBC97\uB294 \uAC74 \uAD1C\uCC2E\uACA0\uB124\uC694. \uBCF4\uC2A4 \uC55E\uC5D0\uC11C\uB9CC\uC694.", nextId: "n7" },
    { id: "n6b", speaker: "\uD30C\uCE58", body: "\uBC97\uC740 \uCC44\uB85C\uC694\u2026? \uC544, \uC54C\uC558\uC5B4\uC694. \uC624\uB298\uC740\uC694. \uBD80\uC218\uBA74 \uBCF4\uC2A4\uAC00 \uACE0\uCCD0 \uC904 \uAC70\uC8E0? \uC544, \uC544\uB2C8, \uC81C\uAC00 \uACE0\uCE60\uAC8C\uC694. \uC81C\uAC00 \uBD80\uC21C \uAC70\uB2C8\uAE4C\uC694.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uD30C\uCE58\uAC00 \uC548\uC804\uBAA8\uB97C \uACC4\uB2E8 \uC704\uC5D0 \uC870\uC2EC\uC2A4\uB7FD\uAC8C \uB0B4\uB824\uB193\uB294\uB2E4. \uBC24\uBC14\uB78C\uC774 \uD30C\uCE58\uC758 \uC9E7\uC740 \uBA38\uB9AC\uCE74\uB77D\uC744 \uD754\uB4E0\uB2E4. \uD3C9\uC18C\uBCF4\uB2E4 \uD6E8\uC52C \uC791\uC544 \uBCF4\uC774\uB294 \uC5B4\uAE68\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "\uD30C\uCE58", body: "\u2026\uC2DC\uC6D0\uD558\uB124\uC694. \uBCC4\uB3C4 \uC798 \uBCF4\uC774\uACE0\uC694. \uBCF4\uC2A4, \uC800 \uC0AC\uC2E4 \uBD80\uC218\uB294 \uAC8C \uC2EB\uC5B4\uC694. \uADFC\uB370 \uC55E\uC5D0 \uC11C\uBA74 \uC5B4\uCA54 \uC218 \uC5C6\uC774 \uBD80\uC218\uAC8C \uB3FC\uC694. \uADF8\uB798\uC11C \uC548\uC804\uBAA8\uAC00 \uC788\uB294 \uAC70\uC608\uC694.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uACC4\uB2E8 \uC544\uB798\uC5D0\uC11C \uC544\uD06C\uC758 \uD6C4\uB4DC \uADF8\uB9BC\uC790\uC640 \uC720\uD2F0\uC758 \uC791\uC740 \uBC1C\uC18C\uB9AC\uAC00 \uC62C\uB77C\uC628\uB2E4. \uD30C\uCE58\uAC00 \uAE09\uD788 \uBAA8\uC790\uB97C \uC9D1\uC73C\uB824\uB2E4 \uB9D0\uACE0 \uC190\uC744 \uAC70\uB454\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uD30C\uCE58", body: "\u2026\uAD1C\uCC2E\uC544, \uADF8\uB0E5 \uC640. \uC624\uB298\uC740 \uC548 \uC4F8 \uAC70\uC57C. \uCCD0\uB2E4\uBCF4\uC9C0 \uB9D0\uACE0. \uBCF4\uC2A4, \uC774\uAC70 \uC0AC\uD0D5 \uD558\uB098 \uB4DC\uC2E4\uB798\uC694? \uB9C8\uC9C0\uB9C9 \uB0A8\uC740 \uCCB4\uB9AC\uB9DB\uC774\uC5D0\uC694. \uC544\uAEF4 \uB480\uC5B4\uC694." }
  ]
};
var PACHI_STORY = {
  relicId: "pachi",
  fossilRecord: "\uBD95\uAD34\uBA74 \uC544\uB798\uC5D0\uC11C \uB450\uAC1C\uACE8 \uC717\uBA74\uB9CC \uC628\uC804\uD55C \uC131\uCCB4 \uD45C\uBCF8\uC774 \uB098\uC654\uB2E4. \uBF08\uAC00 \uC2A4\uBB34 \uACB9 \uB118\uAC8C \uACB9\uCCD0 \uAD73\uC5B4 \uC788\uC5C8\uACE0, \uAC19\uC740 \uC790\uB9AC\uC5D0\uC11C \uBD80\uB7EC\uC9C4 \uBFD4 \uC870\uAC01 \uC5EC\uB7FF\uC774 \uD568\uAED8 \uC218\uC2B5\uB410\uB2E4.",
  diary: '\uBCF5\uC6D0 \uCCAB\uB0A0 \uD30C\uCE58\uB294 \uCF00\uC5B4\uC2E4 \uBB38\uD2C0\uC744 \uBA38\uB9AC\uB85C \uBC1B\uC544 \uACBD\uCCA9\uC744 \uBD80\uC248\uACE0, \uADF8 \uB4A4\uB85C \uC548\uC804\uBAA8\uB97C \uC50C\uC6CC \uB450\uC790 \uBC97\uC9C0 \uC54A\uB294\uB2E4. \uD558\uB8E8 \uC885\uC77C \uCCB4\uB9AC\uB9DB \uC0AC\uD0D5\uC744 \uBB3C\uACE0 \uB2E4\uB2C8\uBA70 \uAECD\uC9C8\uC744 \uC544\uBB34 \uB370\uB098 \uBC84\uB9AC\uACE0, \uC9C0\uC801\uD558\uBA74 \uB208\uC744 \uAD74\uB9AC\uBA70 "\uC54C\uC558\uB2E4\uACE0"\uB77C\uACE0 \uB300\uAFB8\uD55C \uB4A4 \uACB0\uAD6D \uC8FC\uC6CC \uC628\uB2E4. \uCD9C\uACA9 \uC9C0\uC2DC\uC5D0\uB3C4 \uB9E4\uBC88 \uD234\uD234\uAC70\uB9AC\uC9C0\uB9CC \uB0B4\uAC00 \uB9D0\uD55C \uC790\uB9AC\uC5D0\uC11C\uB294 \uD55C \uBC1C\uB3C4 \uBB3C\uB7EC\uC11C\uC9C0 \uC54A\uACE0, \uB4A4\uB530\uB77C\uC624\uB294 \uC778\uC6D0\uC774 \uB2E4 \uC9C0\uB098\uAC08 \uB54C\uAE4C\uC9C0 \uADF8 \uC55E\uC744 \uB9C9\uACE0 \uC11C \uC788\uB294\uB2E4.',
  /** 일지 맨 끝에 회색으로 서는, 파치가 연구원에게 건네는 한마디. 뽑기 대사와 다른 일상의 목소리다. */
  closingLine: "\uBCF4\uC2A4, \uC624\uB298\uC740 \uBB38 \uC548 \uBD80\uC248\uC5B4\uC694. \uACBD\uCCA9\uC774 \uBA3C\uC800 \uD754\uB4E4\uB9B0 \uAC74 \uC788\uB294\uB370\uC694\u2026 \uADF8\uAC74 \uC81C \uD0D3 \uC544\uB2C8\uC5D0\uC694. \uC544\uB9C8\uB3C4\uC694.",
  questions: [
    {
      id: "pachi-helmet",
      prompt: "\uD30C\uCE58\uB294 \uC65C \uC548\uC804\uBAA8\uB97C \uBC97\uC9C0 \uC54A\uC544?",
      choices: [
        {
          id: "habit",
          label: "\uC2B5\uAD00\uC774\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC2B5\uAD00\uC774\uB77C\uAE30\uBCF4\uB2E4\u2026 \uC548 \uC4F0\uBA74 \uBD88\uC548\uD574\uC694, \uBCF4\uC2A4. \uBC97\uC73C\uBA74 \uBA38\uB9AC\uAC00 \uC54C\uC544\uC11C \uC55E\uC11C\uAC00\uAC70\uB4E0\uC694. \uC774\uAC8C \uC788\uC73C\uBA74 \uC81C\uAC00 \uC870\uAE08 \uCC9C\uCC9C\uD788 \uAC00\uC694.",
          note: "\uC2B5\uAD00\uC774\uB0D0\uACE0 \uBB3B\uC790 \uBC97\uC73C\uBA74 \uBD88\uC548\uD558\uB2E4\uACE0 \uD588\uB2E4. \uC4F0\uACE0 \uC788\uC73C\uBA74 \uC870\uAE08 \uCC9C\uCC9C\uD788 \uAC00\uAC8C \uB41C\uB2E4\uACE0 \uB367\uBD99\uC600\uB2E4."
        },
        {
          id: "fit",
          label: "\uC798 \uC5B4\uC6B8\uB9B0\uB2E4\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\uC5B4, \uC815\uB9D0\uC694? \uC774\uC0C1\uD558\uB2E4\uB294 \uC0AC\uB78C\uC774 \uB354 \uB9CE\uC558\uB294\uB370\uC694. \uADF8\uB7FC \uACC4\uC18D \uC368\uB3C4 \uB418\uACA0\uB124\uC694. \uD760\uC9D1\uC774 \uB298\uC5B4\uB3C4 \uC88B\uC544\uD558\uC2DC\uB294 \uAC70\uC8E0?",
          note: "\uC798 \uC5B4\uC6B8\uB9B0\uB2E4\uACE0 \uD558\uC790 \uD760\uC9D1\uC774 \uB298\uC5B4\uB3C4 \uAD1C\uCC2E\uB0D0\uACE0 \uB418\uBB3C\uC5C8\uB2E4. \uD45C\uC815\uC774 \uC870\uAE08 \uD480\uB838\uB2E4."
        },
        {
          id: "gift",
          label: "\uB204\uAC00 \uC50C\uC6CC \uC92C\uB358 \uAC78 \uAE30\uC5B5\uD558\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uAE30\uC5B5\uD558\uC8E0. \uBCF4\uC2A4\uAC00 \uCCAB\uB0A0 \uC50C\uC6CC \uC92C\uC796\uC544\uC694. \uADF8\uAC78 \uC5B4\uB5BB\uAC8C \uC78A\uC5B4\uC694? \uADF8\uB798\uC11C \uBABB \uBC97\uB294 \uAC74\uC9C0\uB3C4 \uBAB0\uB77C\uC694, \uC194\uC9C1\uD788.",
          note: "\uB204\uAC00 \uC50C\uC6CC \uC92C\uB294\uC9C0 \uBB3B\uC790 \uACE7\uBC14\uB85C \uC5F0\uAD6C\uC6D0\uC774\uB77C\uACE0 \uB2F5\uD588\uB2E4. \uADF8\uB798\uC11C \uBABB \uBC97\uB294 \uAC74\uC9C0\uB3C4 \uBAA8\uB978\uB2E4\uACE0 \uC778\uC815\uD588\uB2E4."
        }
      ]
    },
    {
      id: "pachi-candy",
      prompt: "\uD30C\uCE58\uB294 \uC65C \uD558\uB8E8 \uC885\uC77C \uCCB4\uB9AC\uB9DB \uC0AC\uD0D5\uC744 \uBB3C\uACE0 \uC788\uC5B4?",
      choices: [
        {
          id: "mouth",
          label: "\uC785\uC774 \uC2EC\uC2EC\uD574\uC11C\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uB9DE\uC544\uC694. \uC785\uC774 \uBE44\uBA74 \uAD1C\uD788 \uC9DC\uC99D\uC774 \uB098\uC694. \uC0AC\uD0D5\uC774 \uC788\uC73C\uBA74 \uC785\uC774 \uBC14\uC058\uB2C8\uAE4C \uB9D0\uC774 \uB35C \uB098\uAC00\uC694. \uD22C\uB35C\uB300\uB294 \uAC83\uB3C4 \uC904\uACE0\uC694.",
          note: "\uC785\uC774 \uC2EC\uC2EC\uD558\uB0D0\uACE0 \uBB3B\uC790 \uB9DE\uB2E4\uACE0 \uD588\uB2E4. \uC0AC\uD0D5\uC774 \uC788\uC73C\uBA74 \uD22C\uB35C\uB300\uB294 \uB9D0\uC774 \uC904\uC5B4\uB4E0\uB2E4\uACE0 \uC124\uBA85\uD588\uB2E4."
        },
        {
          id: "cherry",
          label: "\uC65C \uD558\uD544 \uCCB4\uB9AC\uB9DB\uC774\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uBE68\uAC1B\uC796\uC544\uC694. \uBD80\uC218\uACE0 \uB098\uBA74 \uC5B4\uB518\uAC00 \uB2E4\uCE5C \uAC83\uCC98\uB7FC \uBE68\uAC1C\uC9C0\uB294\uB370, \uADF8 \uC0C9\uC774 \uC0AC\uD0D5\uC774\uBA74 \uAD1C\uCC2E\uC740 \uC0C9 \uAC19\uC544\uC11C\uC694. \uC774\uC0C1\uD55C\uAC00\uC694?",
          note: "\uC65C \uCCB4\uB9AC\uB9DB\uC774\uB0D0\uACE0 \uBB3B\uC790 \uBE68\uAC04\uC0C9\uC774\uB77C\uC11C\uB77C\uACE0 \uB2F5\uD588\uB2E4. \uC774\uC0C1\uD558\uB0D0\uACE0 \uC870\uC2EC\uC2A4\uB808 \uB418\uBB3C\uC5C8\uB2E4."
        },
        {
          id: "wrapper",
          label: "\uAECD\uC9C8\uC740 \uC880 \uBC84\uB9AC\uC9C0 \uB9D0\uB77C\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\uC544, \uC54C\uC558\uB2E4\uACE0\uC694! \uC9C0\uAE08 \uC8FC\uC6B8\uAC8C\uC694. \uADFC\uB370 \uBCF4\uC2A4\uAE4C\uC9C0 \uADF8\uB7EC\uBA74 \uC9C4\uC9DC \uC794\uC18C\uB9AC \uAC19\uC544\uC11C \uC2EB\uC5B4\uC694. \u2026\uB0B4\uC77C\uC740 \uC8FC\uBA38\uB2C8\uC5D0 \uB123\uC5B4 \uB458\uAC8C\uC694.",
          note: "\uAECD\uC9C8 \uC774\uC57C\uAE30\uB97C \uD558\uC790 \uB208\uC744 \uAD74\uB838\uB2E4. \uB0B4\uC77C\uC740 \uC8FC\uBA38\uB2C8\uC5D0 \uB123\uC5B4 \uB450\uACA0\uB2E4\uACE0 \uC57D\uC18D\uD588\uB2E4."
        }
      ]
    },
    {
      id: "pachi-guard",
      prompt: "\uD30C\uCE58\uB294 \uC65C \uC815\uD574 \uC900 \uC790\uB9AC\uC5D0\uC11C \uD55C \uBC1C\uB3C4 \uC548 \uBB3C\uB7EC\uC11C?",
      choices: [
        {
          id: "order",
          label: "\uBA85\uB839\uC774\uB77C\uC11C\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uBA85\uB839\uC740 \uC544\uB2C8\uC5D0\uC694. \uBCF4\uC2A4\uAC00 \uC815\uD574 \uC92C\uC73C\uB2C8\uAE4C\uC694. \uBCF4\uC2A4\uAC00 \uC0DD\uAC01\uD574\uC11C \uC815\uD55C \uC790\uB9AC\uBA74 \uC81C\uAC00 \uBB3C\uB7EC\uC11C\uB294 \uAC74 \uADF8 \uC0DD\uAC01\uC744 \uBB34\uC2DC\uD558\uB294 \uAC70\uC796\uC544\uC694.",
          note: "\uBA85\uB839\uC774\uB77C\uC11C\uB0D0\uACE0 \uBB3B\uC790 \uC544\uB2C8\uB77C\uACE0 \uD588\uB2E4. \uC5F0\uAD6C\uC6D0\uC774 \uC0DD\uAC01\uD574\uC11C \uC815\uD55C \uC790\uB9AC\uB77C\uC11C \uC9C0\uD0A8\uB2E4\uACE0 \uB9D0\uD588\uB2E4."
        },
        {
          id: "scared",
          label: "\uBB34\uC12D\uC9C0\uB294 \uC54A\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uBB34\uC12D\uC8E0, \uB2F9\uC5F0\uD788. \uADFC\uB370 \uC81C\uAC00 \uBE44\uD0A4\uBA74 \uB4A4\uC5D0 \uC788\uB294 \uC560\uB4E4\uC774 \uB9DE\uC544\uC694. \uADF8\uAC8C \uB354 \uBB34\uC11C\uC6CC\uC694. \uADF8\uB798\uC11C \uC11C \uC788\uB294 \uAC70\uC608\uC694.",
          note: "\uBB34\uC12D\uC9C0 \uC54A\uB0D0\uACE0 \uBB3B\uC790 \uBB34\uC12D\uB2E4\uACE0 \uC194\uC9C1\uD558\uAC8C \uB2F5\uD588\uB2E4. \uB4A4\uC5D0 \uC788\uB294 \uC774\uB4E4\uC774 \uB9DE\uB294 \uAC8C \uB354 \uBB34\uC12D\uB2E4\uACE0 \uD588\uB2E4."
        },
        {
          id: "proud",
          label: "\uC815\uB9D0 \uB4E0\uB4E0\uD558\uB2E4\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\uC544, \uAC11\uC790\uAE30 \uADF8\uB7F0 \uB9D0 \uD558\uC9C0 \uB9C8\uC138\uC694! \uBD80\uB044\uB7FD\uC796\uC544\uC694! \u2026\uADFC\uB370 \uB4E4\uC73C\uB2C8\uAE4C \uAE30\uBD84\uC740 \uC88B\uB124\uC694. \uD55C \uBC88\uB9CC \uB354 \uB9D0\uD574 \uC918\uB3C4 \uB3FC\uC694.",
          note: "\uB4E0\uB4E0\uD558\uB2E4\uACE0 \uD558\uC790 \uBD80\uB044\uB7EC\uC6CC\uD558\uBA70 \uC190\uC744 \uD718\uC800\uC5C8\uB2E4. \uD55C \uBC88\uB9CC \uB354 \uB9D0\uD574 \uC918\uB3C4 \uB41C\uB2E4\uACE0 \uC791\uAC8C \uB367\uBD99\uC600\uB2E4."
        }
      ]
    }
  ],
  bondStories: { 4: CHAPTER_412, 6: CHAPTER_612, 8: CHAPTER_812, 10: CHAPTER_1012 },
  bondLines: [
    // 0 — 낯선 사이. 팔짱을 끼고 한참 노려본다.
    ["\uBCF4\uC2A4\uB77C\uACE0 \uBD80\uB974\uBA74 \uB418\uC8E0? \uADF8\uB7FC \uADF8\uB807\uAC8C \uD560\uAC8C\uC694. \uADFC\uB370 \uC794\uC18C\uB9AC\uB294 \uC801\uB2F9\uD788 \uD574 \uC8FC\uC138\uC694. \uC54C\uC558\uC8E0?", "\uC800 \uBB38 \uBD80\uC21C \uAC70 \uC81C\uAC00 \uD55C \uAC70 \uC544\uB2C8\uC5D0\uC694. \uC544\uB2C8, \uC81C\uAC00 \uD558\uAE34 \uD588\uB294\uB370 \uBB38\uC774 \uBA3C\uC800 \uB098\uC654\uC5B4\uC694.", "\uC0AC\uD0D5 \uB4DC\uC2E4\uB798\uC694? \uCCB4\uB9AC\uB9DB\uBC16\uC5D0 \uC5C6\uC9C0\uB9CC\uC694. \u2026\uC2EB\uC73C\uBA74 \uC81C\uAC00 \uBA39\uC744\uAC8C\uC694."],
    // 1
    ["\uC624\uB298\uC740 \uBB38\uD2C0\uC744 \uD55C \uBC88\uB3C4 \uC548 \uBC1B\uC558\uC5B4\uC694. \uD55C \uBC88\uB3C4\uC694! \uCE6D\uCC2C\uD574 \uC8FC\uC154\uB3C4 \uB3FC\uC694, \uBCF4\uC2A4.", "\uC548\uC804\uBAA8\uAC00 \uC880 \uB0A1\uC558\uC5B4\uC694. \uD558\uC9C0\uB9CC \uBC14\uAFB8\uC9C4 \uC54A\uC744 \uAC70\uC608\uC694. \uC774\uAC8C \uC81C \uAC74\uB370\uC694.", "\uCD9C\uACA9\uC774\uB77C\uACE0\uC694? \uC54C\uC558\uC5B4\uC694, \uC54C\uC558\uB2E4\uACE0\uC694. \uAC00\uBA74 \uB418\uC796\uC544\uC694. \uC55E\uC740 \uC81C\uAC00 \uC124\uAC8C\uC694."],
    // 2
    ["\uAECD\uC9C8\uC740 \uC8FC\uBA38\uB2C8\uC5D0 \uB123\uACE0 \uB2E4\uB140\uC694. \uC5B4\uC81C\uAE4C\uC9C0\uB294\uC694. \uC624\uB298\uC740 \uC5B4\uB514 \uAC14\uB294\uC9C0 \uBAA8\uB974\uACA0\uC5B4\uC694\u2026", "\uBCF4\uC2A4\uAC00 \uAC00\uB77C\uB294 \uB370\uB294 \uAC00\uC694. \uD22C\uB35C\uB300\uB294 \uAC70\uB791 \uC548 \uAC00\uB294 \uAC74 \uB2E4\uB974\uC796\uC544\uC694.", "\uB3C4\uB514\uAC00 \uC81C \uC774\uB984 \uC606\uC5D0 \uAE30\uB85D\uC744 \uACC4\uC18D \uC313\uC544\uC694. \uBD80\uC21C \uAC83\uB9CC\uC694. \uACE0\uCE5C \uAC83\uB3C4 \uC4F0\uB77C\uACE0 \uD588\uC5B4\uC694."],
    // 3
    ["\uBCF4\uC2A4, \uC544\uAE4C \uC2E0\uBC1C \uB048 \uD480\uB9B0 \uAC70 \uBD24\uC8E0? \u2026\uBAA8\uB978 \uCC99\uD574 \uC918\uC11C \uACE0\uB9C8\uC6CC\uC694. \uC9C0\uAE08 \uBB36\uC744 \uAC70\uC608\uC694.", "\uC544\uD06C\uAC00 \uBCF5\uB3C4\uC5D0\uC11C \uAE38\uC744 \uBABB \uCC3E\uACE0 \uC11C \uC788\uAE38\uB798 \uADF8\uB0E5 \uAC00\uB77C\uACE0 \uD588\uC5B4\uC694. \uAC54\uB294 \uB108\uBB34 \uB208\uCE58\uB97C \uBD10\uC694.", "\uC0AC\uD0D5\uC774 \uB5A8\uC5B4\uC84C\uC5B4\uC694. \uBE44\uC0C1\uC6A9\uC73C\uB85C \uD558\uB098 \uC228\uACA8 \uB454 \uAC8C \uC788\uAE34 \uD55C\uB370\u2026 \uC5B4\uB514 \uB480\uB294\uC9C0 \uBAB0\uB77C\uC694."],
    // 4 — 장 4 이후: 부서진 경첩 이후.
    ["\uACBD\uCCA9 \uACE0\uCE58\uB294 \uAC70 \uC0DD\uAC01\uBCF4\uB2E4 \uC7AC\uBC0C\uC5C8\uC5B4\uC694. \uC544\uB2C8, \uC7AC\uBBF8\uC5C6\uC5C8\uC5B4\uC694. \uC544\uB2C8, \uADF8\uB0E5 \uC4F8 \uB9CC\uD588\uC5B4\uC694.", "\uB2E4\uC74C\uC5D0 \uB610 \uBD80\uC218\uBA74 \uC5B4\uCA4C\uB0D0\uACE0 \uD588\uB294\uB370\uC694, \uBD80\uC21C \uB9CC\uD07C \uACE0\uCE58\uBA74 \uB418\uC796\uC544\uC694. \uADF8\uAC8C \uC81C \uBC29\uC2DD\uC774\uC5D0\uC694.", "\uB3C4\uB514\uAC00 \uACE0\uCE5C \uAC83\uB3C4 \uAE30\uB85D\uC5D0 \uC368 \uC92C\uC5B4\uC694. \uD55C \uC904\uBC16\uC5D0 \uC548 \uB418\uC9C0\uB9CC\uC694. \uADF8 \uD55C \uC904\uC774 \uC88B\uC544\uC694."],
    // 5
    ["\uBE44 \uC624\uB294 \uB0A0\uC740 \uC548\uC804\uBAA8 \uC4F0\uAE38 \uC798\uD588\uC5B4\uC694, \uBCF4\uC2A4. \uBB3C \uC548 \uB9DE\uAC70\uB4E0\uC694. \uC758\uC678\uC758 \uC7A5\uC810\uC774\uC5D0\uC694.", "\uCF04\uD1A0\uAC00 \uB180\uB824\uB3C4 \uC2E0\uACBD \uC548 \uC368\uC694. \u2026\uC9C4\uC9DC\uC608\uC694. \uB450 \uBC88 \uB9D0\uD558\uBA74 \uC2E0\uACBD \uC4F0\uB294 \uAC70\uB77C\uACE0\uC694? \uC544\uB2C8\uC5D0\uC694.", "\uBCF4\uC2A4\uAC00 \uC815\uD574 \uC8FC\uB294 \uC790\uB9AC\uAC00 \uB9C8\uC74C\uC5D0 \uB4E4\uC5B4\uC694. \uC5B4\uB514\uB4E0 \uC55E\uC774\uBA74 \uB3FC\uC694. \uC55E\uC774 \uC81C\uC77C \uD3B8\uD574\uC694."],
    // 6 — 장 6 이후: 사탕 껍질을 줍는 날 이후.
    ["\uC544\uAE4C \uC8FC\uC6B4 \uAECD\uC9C8, \uC5F4\uD55C \uAC1C\uC600\uC5B4\uC694. \uC138\uC5B4 \uBD24\uC5B4\uC694. \uBCF4\uC2A4\uD55C\uD14C\uB9CC \uB9D0\uD558\uB294 \uAC70\uC608\uC694.", "\uD654\uB2E8 \uAC00\uC9C0\uB97C \uC548 \uBD80\uC248\uC5B4\uC694. \uCF04\uD1A0\uAC00 \uBC15\uC218 \uCE5C\uB2E4\uACE0 \uD588\uB294\uB370 \uC9C4\uC9DC \uCCE4\uC73C\uBA74 \uC0AC\uD0D5\uC744 \uB358\uC84C\uC744 \uAC70\uC608\uC694.", "\uC190\uC774 \uBC14\uBE60\uC11C \uC78A\uC5B4\uBC84\uB824\uC694. \uADF8\uB798\uC11C \uC8FC\uBA38\uB2C8\uB97C \uD070 \uAC78\uB85C \uBC14\uAFE8\uC5B4\uC694. \uC774\uB7EC\uBA74 \uB418\uC8E0, \uBCF4\uC2A4?"],
    // 7
    ["\uC720\uD2F0\uAC00 \uC9C0\uB098\uAC00\uBA74\uC11C \uC548\uC804\uBAA8\uB97C \uD1A1 \uCCE4\uB294\uB370 \uBAA8\uB974\uB294 \uCC99\uD588\uC5B4\uC694. \uAC54\uB294 \uB4E4\uD0A4\uB294 \uAC78 \uC2EB\uC5B4\uD560 \uAC83 \uAC19\uC544\uC11C\uC694.", "\uC544\uD06C\uB294 \uD6C4\uB4DC\uB97C \uC4F0\uBA74 \uB354 \uBB34\uC11C\uC6CC \uBCF4\uC774\uB294 \uAC78 \uBAB0\uB77C\uC694. \uC800\uB294 \uC54C\uB824 \uC8FC\uACE0 \uC2F6\uC740\uB370 \uC5B4\uB5BB\uAC8C \uB9D0\uD560\uC9C0 \uBAA8\uB974\uACA0\uC5B4\uC694.", "\uC55E\uC5D0 \uC11C\uB294 \uAC74 \uC26C\uC6CC\uC694. \uB4A4\uC5D0\uC11C \uAE30\uB2E4\uB9AC\uB294 \uAC8C \uB354 \uC5B4\uB824\uC6CC\uC694, \uBCF4\uC2A4."],
    // 8 — 장 8 이후: 앞길을 뚫는 자리 이후.
    ["\uB099\uC11D \uB54C \uBA38\uB9AC\uAC00 \uC880 \uC6B8\uB838\uB294\uB370 \uC544\uBB34\uD55C\uD14C\uB3C4 \uB9D0 \uC548 \uD588\uC5B4\uC694. \uB9D0\uD558\uBA74 \uAC71\uC815\uD558\uB2C8\uAE4C\uC694. \uBCF4\uC2A4\uD55C\uD14C\uB9CC \uB9D0\uD574\uC694.", "\uB2E4 \uC9C0\uB098\uAC14\uC8E0? \uD55C \uBA85\uB3C4 \uC548 \uBE60\uC84C\uC8E0? \uC774 \uC9C8\uBB38\uC744 \uD55C \uBC88 \uB354 \uD558\uACE0 \uC2F6\uC5B4\uC11C\uC694. \uAD1C\uCC2E\uC8E0?", "\uC548\uC804\uBAA8\uB97C \uC4F0\uAE38 \uC798\uD588\uB2E4\uACE0 \uC0DD\uAC01\uD55C \uAC74 \uCC98\uC74C\uC774\uC5D0\uC694. \uC774\uB7F0 \uB9D0\uC740 \uBE44\uBC00\uC774\uC5D0\uC694."],
    // 9
    ["\uBC97\uACE0 \uC2F6\uC740 \uB0A0\uC774 \uC0DD\uACBC\uC5B4\uC694. \uADF8\uB7F0 \uB0A0\uC5D4 \uBCF4\uC2A4 \uC55E\uC5D0\uC11C\uB9CC \uBC97\uC744 \uAC70\uC608\uC694. \uC57D\uC18D\uD574\uC694.", "\uC55E\uC5D0 \uC11C\uB294 \uAC8C \uC81C \uC790\uB9AC\uB77C\uBA74 \uB4A4\uB294 \uBCF4\uC2A4\uAC00 \uBD10 \uC8FC\uC2E4 \uAC70\uC8E0? \uC800\uB294 \uB4A4\uB97C \uBABB \uBCF4\uAC70\uB4E0\uC694.", "\uC0AC\uD0D5\uC744 \uC544\uAEF4 \uB450\uB294 \uBC95\uC744 \uBC30\uC6B0\uB294 \uC911\uC774\uC5D0\uC694. \uD558\uB098\uB97C \uC624\uB798 \uBA39\uC73C\uBA74 \uB418\uB354\uB77C\uACE0\uC694. \uC758\uC678\uB85C\uC694."],
    // 10 — 마음을 연 사이. 안전모를 벗는 밤 이후.
    ["\uC548\uC804\uBAA8 \uBC97\uACE0 \uBCC4 \uBD24\uC5B4\uC694. \uBCC4\uC774 \uADF8\uB807\uAC8C \uB9CE\uC740 \uC904 \uBAB0\uB790\uC5B4\uC694. \uB2E4\uC74C\uC5D0\uB3C4 \uAC19\uC774 \uBD10 \uC8FC\uC2E4 \uAC70\uC8E0, \uBCF4\uC2A4?", "\uBCF4\uC2A4 \uC606\uC5D0\uC11C \uAC78\uC73C\uBA74 \uBB38\uD2C0\uC774 \uC548 \uBB34\uC11C\uC6CC\uC694. \uC774\uC0C1\uD558\uC8E0? \uADF8\uB798\uB3C4 \uC548\uC804\uBAA8\uB294 \uC4F8 \uAC70\uC608\uC694.", "\uB9C8\uC9C0\uB9C9 \uCCB4\uB9AC\uB9DB \uC0AC\uD0D5\uC740 \uBCF4\uC2A4 \uAC70\uC600\uC5B4\uC694. \uC774\uAC74 \uD22C\uB35C\uB300\uC9C0 \uC54A\uACE0 \uB9D0\uD558\uB294 \uAC70\uC608\uC694. \uBC1B\uC544 \uC8FC\uC138\uC694."]
  ]
};

