var CHAPTER_417 = {
  id: "bond.tia.4",
  startNodeId: "n1",
  titleCard: { title: "\uBC18\uC9DD\uC774\uB294 \uB3CC \uC90D\uAE30", subtitle: "\uD2F0\uC544 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 1" },
  nodes: [
    { id: "n1", speaker: "", body: "\uD574\uAC00 \uAE30\uC6B4 \uAC15\uAC00. \uC595\uC740 \uBB3C\uC18D\uC5D0\uC11C \uD2F0\uC544\uAC00 \uD5C8\uB9AC\uB97C \uAD7D\uD78C \uCC44 \uBB34\uC5B8\uAC00\uB97C \uAC74\uC838 \uC62C\uB9AC\uACE0 \uC788\uB2E4. \uBCA0\uC77C \uC790\uB77D\uC774 \uBB3C\uC5D0 \uC816\uC5B4 \uBC18\uC9DD\uC778\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uD2F0\uC544", body: "\uC557, \uC5F0\uAD6C\uC6D0\uB2D8! \uC774\uAC83 \uBCF4\uC138\uC694! \uBC18\uC9DD\uBC18\uC9DD\uD574\uC694! \uC624\uB298\uC740 \uC774\uB9CC\uD07C\uC774\uB098 \uC8FC\uC6E0\uC5B4\uC694, \uCCA8\uBC99\uCCA8\uBC99 \uC5F4\uC2EC\uD788 \uD588\uAC70\uB4E0\uC694!", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uD2F0\uC544\uAC00 \uB450 \uC190\uC744 \uD65C\uC9DD \uD3B4 \uBCF4\uC600\uB2E4. \uB465\uAE00\uAC8C \uB2F3\uC740 \uC720\uB9AC \uC870\uAC01\uACFC \uD558\uC580 \uC870\uC57D\uB3CC\uC774 \uC190\uBC14\uB2E5 \uAC00\uB4DD \uC5B9\uD600 \uC788\uB2E4. \uD574\uB97C \uBC1B\uC544 \uC870\uAC01\uB9C8\uB2E4 \uB2E4\uB978 \uC0C9\uC73C\uB85C \uBE5B\uB09C\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uC190\uBC14\uB2E5 \uD55C\uAC00\uC6B4\uB370 \uAC00\uC7A5 \uC791\uC740 \uC870\uAC01 \uD558\uB098\uB9CC \uB530\uB85C \uBAA8\uC544 \uC950\uACE0 \uC788\uB2E4. \uAC00\uC7A5 \uBA3C\uC800 \uC8FC\uC6B4 \uAC83\uC778 \uB4EF\uD558\uB2E4.)", choices: [
      { id: "praise", label: "\uC815\uB9D0 \uC608\uC058\uB2E4\uACE0 \uB9D0\uD574 \uC900\uB2E4", nextId: "n5a" },
      { id: "ask", label: "\uC774\uAC78 \uB2E4 \uC5B4\uB514\uC5D0 \uC4F0\uB294 \uAC70\uB0D0\uACE0 \uBB3B\uB294\uB2E4", nextId: "n5b" }
    ] },
    { id: "n5a", speaker: "\uD2F0\uC544", body: "\uC5D0\uD5E4\uD5E4\u2026 \uC608\uC058\uC8E0? \uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uC608\uC058\uB2E4\uACE0 \uD558\uC2DC\uBA74 \uB354 \uBC18\uC9DD\uC5EC\uC694! \u2026\uC557, \uC5BC\uAD74\uC774 \uB728\uAC70\uC6CC\uC11C \uBCA0\uC77C \uC880 \uC62C\uB9B4\uAC8C\uC694.", nextId: "n6" },
    { id: "n5b", speaker: "\uD2F0\uC544", body: "\uC4F0\uB294 \uAC70\uC694? \uC73C\uC74C\u2026 \uC4F0\uB294 \uAC74 \uC544\uC9C1 \uBAB0\uB77C\uC694! \uADFC\uB370 \uBC18\uC9DD\uC774\uB294 \uAC74 \uB2E4 \uB0B4 \uAC70\uC57C! \uADF8\uB798\uC11C \uBAA8\uC73C\uB294 \uAC70\uC608\uC694. \uC774\uC720\uB294 \uADF8\uB2E4\uC74C\uC5D0 \uCC3E\uC744\uB798\uC694!", nextId: "n6" },
    { id: "n6", speaker: "", body: "\uADF8\uB54C \uAC15\uB451 \uC704\uC5D0\uC11C \uB3C4\uB514\uC640 \uD1A0\uB9AC\uCE74\uAC00 \uC190\uC744 \uD754\uB4E4\uBA70 \uB0B4\uB824\uC654\uB2E4. \uB458\uC758 \uBC1C\uBC11\uC5D0\uC11C \uC790\uAC08\uC774 \uB610\uB974\uB974 \uAD74\uB800\uB2E4.", nextId: "n7" },
    { id: "n7", speaker: "\uD1A0\uB9AC\uCE74", body: "\uD2F0\uC544, \uC624\uB298\uB3C4 \uB9CE\uC774 \uC8FC\uC6E0\uB124. \uC774\uB807\uAC8C \uBAA8\uC73C\uBA74 \uBCF4\uAE09 \uD68C\uC218 \uAC19\uB2E4\uB2C8\uAE4C. \uB300\uB2E8\uD574.", nextId: "n8" },
    { id: "n8", speaker: "\uD2F0\uC544", body: "\uADF8, \uADF8\uCD78? \uBCF4\uAE09\uD488\uC774\uC5D0\uC694! \uC5F0\uAD6C\uC6D0\uB2D8\uD55C\uD14C \uC904 \uBCF4\uAE09\uD488! \uC774 \uC911\uC5D0\uC11C \uD558\uB098\uB9CC \uACE8\uB77C \uAC00\uC138\uC694, \uAC00\uC7A5 \uBC18\uC9DD\uC774\uB294 \uAC78\uB85C\uC694!", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uD2F0\uC544\uAC00 \uBAA8\uC544 \uC954 \uAC00\uC7A5 \uC791\uC740 \uC870\uAC01\uB9CC\uC740 \uC2AC\uCA4D \uC18C\uB9E4 \uC18D\uC73C\uB85C \uC228\uACBC\uB2E4. \uB098\uBA38\uC9C0 \uC870\uAC01\uB4E4\uC740 \uBAA8\uB450 \uC5F0\uAD6C\uC6D0 \uC55E\uC5D0 \uD3BC\uCCD0\uC9C4\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uD2F0\uC544", body: "\uC5F0\uAD6C\uC6D0\uB2D8, \uC774\uAC70 \uBD80\uB7EC\uB728\uB9AC\uC9C0 \uB9D0\uACE0 \uC8FC\uBA38\uB2C8\uC5D0 \uB123\uC5B4 \uB450\uC138\uC694! \uADF8\uB7EC\uBA74 \uC81C\uAC00 \uC774\uB984 \uBD80\uB97C \uB54C \uCA0D\uADF8\uB791\uCA0D\uADF8\uB791 \uB300\uB2F5\uD574 \uC904 \uAC70\uC608\uC694!" }
  ]
};
var CHAPTER_617 = {
  id: "bond.tia.6",
  startNodeId: "n1",
  titleCard: { title: "\uBB3C\uC7A5\uAD6C \uC18C\uB3D9", subtitle: "\uD2F0\uC544 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 2" },
  nodes: [
    { id: "n1", speaker: "", body: "\uD55C\uB0AE\uC758 \uAC15\uAC00. \uC595\uC740 \uBB3C\uAC00\uC5D0\uC11C \uCCA8\uBC99 \uC18C\uB9AC\uAC00 \uC5F0\uB2EC\uC544 \uD130\uC9C4\uB2E4. \uD2F0\uC544\uAC00 \uAF2C\uB9AC\uB0A0\uB85C \uBB3C\uC744 \uAC77\uC5B4\uCC28 \uBB3C\uBCF4\uB77C\uB97C \uC77C\uC73C\uD0A4\uACE0\uB294 \uBC14\uC704 \uB4A4\uB85C \uC3D9 \uC228\uB294\uB2E4.", cue: "impact", nextId: "n2" },
    { id: "n2", speaker: "\uB3C4\uB514", body: "\uC73C\uC544, \uCC28\uAC00\uC6CC! \uD2F0\uC544, \uC774\uAC70 \uC77C\uBD80\uB7EC \uADF8\uB7AC\uC9C0! \uAC00\uB9CC \uC548 \uB458 \uAC70\uC57C!", nextId: "n3" },
    { id: "n3", speaker: "\uD2F0\uC544", body: "\uC5D0\uD5E4\uD5E4! \uBB3C\uC7A5\uAD6C\uB294 \uBA3C\uC800 \uD558\uB294 \uC0AC\uB78C\uC774 \uC774\uAE30\uB294 \uAC70\uC608\uC694! \uBC18\uC9DD\uBC18\uC9DD \uCCA8\uBC99\uCCA8\uBC99! \u2026\uC557, \uC774\uCABD\uC73C\uB85C \uC624\uBA74 \uC548 \uB3FC\uC694!", nextId: "n4" },
    { id: "n4", speaker: "", body: "\uB3C4\uB514\uC640 \uD1A0\uB9AC\uCE74, \uD30C\uB8E8\uC544\uAC00 \uD55C\uAEBC\uBC88\uC5D0 \uBB3C\uC744 \uD280\uAE30\uBA70 \uBC14\uC704 \uCABD\uC73C\uB85C \uBAB0\uB824\uB4E0\uB2E4. \uD2F0\uC544\uB294 \uBCA0\uC77C\uC744 \uD718\uB0A0\uB9AC\uBA70 \uC5F0\uAD6C\uC6D0 \uB4A4\uB85C \uB2EC\uB824\uC640 \uC637\uC790\uB77D\uC744 \uAF2D \uBD99\uC7A1\uB294\uB2E4.", nextId: "n5" },
    { id: "n5", speaker: "\uD2F0\uC544", body: "\uC5F0\uAD6C\uC6D0\uB2D8, \uC81C \uD3B8 \uD574 \uC8FC\uC138\uC694! \uC800 \uD63C\uC790\uB294 \uBABB \uC774\uACA8\uC694! \uC637\uC790\uB77D \uC7A1\uC558\uC73C\uB2C8\uAE4C \uC774\uC81C \uD55C \uD3B8\uC774\uC5D0\uC694!", nextId: "n6" },
    { id: "n6", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uC637\uC790\uB77D\uC744 \uC954 \uC190\uC774 \uAF2D \uC950\uC5B4\uC838 \uC788\uB2E4. \uC5BC\uAD74\uC740 \uB3C4\uB9DD\uCE58\uB294 \uC544\uC774\uC758 \uAC83\uC778\uB370 \uC954 \uC190\uC740 \uB193\uC9C0 \uC54A\uC73C\uB824\uB294 \uC544\uC774\uC758 \uAC83\uC774\uB2E4.)", choices: [
      { id: "ally", label: "\uADF8\uB798, \uAC19\uC740 \uD3B8\uC774\uC57C. \uAC19\uC774 \uBB3C \uD280\uAE30\uC790", nextId: "n7a" },
      { id: "shield", label: "\uD2F0\uC544\uB97C \uB4F1 \uB4A4\uB85C \uC228\uACA8 \uC900\uB2E4", nextId: "n7b" }
    ] },
    { id: "n7a", speaker: "\uD2F0\uC544", body: "\uC815\uB9D0\uC694? \uC640, \uC2E0\uB09C\uB2E4! \uB458\uC774 \uD558\uBA74 \uBC18\uC9DD\uBC18\uC9DD\uC774 \uB450 \uBC30\uC608\uC694! \uD558\uB098, \uB458, \uC14B\uC5D0 \uB358\uC838\uC694! \uD558\uB098, \uB458\u2026!", nextId: "n8" },
    { id: "n7b", speaker: "\uD2F0\uC544", body: "\u2026\uC5F0\uAD6C\uC6D0\uB2D8 \uB4F1 \uB4A4\uAC00 \uC81C\uC77C \uC548\uC804\uD574\uC694. \uC5EC\uAE30\uC11C \uC870\uAE08\uB9CC \uC788\uB2E4\uAC00 \uB098\uAC08\uAC8C\uC694. \uC5D0\uD5E4\uD5E4, \uC9C4\uC9DC \uC870\uAE08\uB9CC\uC694.", nextId: "n8" },
    { id: "n8", speaker: "", body: "\uBB3C\uBCF4\uB77C\uAC00 \uD55C\uAEBC\uBC88\uC5D0 \uC3DF\uC544\uC84C\uB2E4. \uBAA8\uB450\uAC00 \uD760\uBED1 \uC816\uC5C8\uACE0 \uB9C8\uC9C0\uB9C9\uC5D0\uB294 \uC544\uBB34\uB3C4 \uB204\uAC00 \uBA3C\uC800 \uC2DC\uC791\uD588\uB294\uC9C0 \uAE30\uC5B5\uD558\uC9C0 \uBABB\uD588\uB2E4. \uB2E4 \uAC19\uC774 \uD070 \uC18C\uB9AC\uB85C \uC6C3\uC5C8\uB2E4.", nextId: "n9" },
    { id: "n9", speaker: "\uD30C\uB8E8\uC544", body: "\u2026\uD2F0\uC544, \uC624\uB298 \uBB3C\uC7A5\uAD6C \uC88B\uC558\uC5B4. \uB2E4\uC74C\uC5D0\uB3C4 \uB610 \uD558\uC790. \uC774\uBC88\uC5D4 \uB0B4\uAC00 \uBA3C\uC800 \uB358\uC9C8\uAC8C.", nextId: "n10" },
    { id: "n10", speaker: "\uD2F0\uC544", body: "\uC5D0\uD5E4\uD5E4! \uC5F0\uAD6C\uC6D0\uB2D8, \uC624\uB298\uC740 \uC81C\uAC00 \uC774\uAE34 \uAC70\uC8E0? \uC544\uB2C8\uC5D0\uC694? \uADF8\uB798\uB3C4 \uAD1C\uCC2E\uC544\uC694, \uAC19\uC774 \uC816\uC5C8\uC73C\uB2C8\uAE4C \uB2E4 \uAC19\uC774 \uC774\uAE34 \uAC70\uC608\uC694!" }
  ]
};
var CHAPTER_817 = {
  id: "bond.tia.8",
  startNodeId: "n1",
  titleCard: { title: "\uC4F8\uBAA8\uC5C6\uB2E4\uB294 \uB9D0", subtitle: "\uD2F0\uC544 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 3" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC800\uB141 \uBCF4\uAE09 \uC810\uAC80. \uC0C1\uC790 \uC704\uC5D0 \uD2F0\uC544\uAC00 \uBAA8\uC544 \uC628 \uC720\uB9AC \uC870\uAC01\uC774 \uD55C \uC6C0\uD07C \uC3DF\uC544\uC838 \uC788\uB2E4. \uC810\uAC80\uD558\uB358 \uD30C\uB8E8\uC544\uAC00 \uC870\uAC01 \uD558\uB098\uB97C \uB4E4\uC5B4 \uC62C\uB824 \uC9E7\uAC8C \uC911\uC5BC\uAC70\uB9B0\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uD30C\uB8E8\uC544", body: "\u2026\uC774\uAC74, \uC4F8 \uB370\uAC00 \uC5C6\uC5B4 \uBCF4\uC774\uB124. \uBB34\uAC8C\uB9CC \uB098\uAC00\uACE0.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uD30C\uB8E8\uC544\uB294 \uC545\uC758 \uC5C6\uC774 \uB358\uC9C4 \uB9D0\uC774\uC5C8\uB2E4. \uD558\uC9C0\uB9CC \uD2F0\uC544\uC758 \uAF2C\uB9AC\uB0A0\uC774 \uC21C\uC2DD\uAC04\uC5D0 \uCD95 \uB298\uC5B4\uC84C\uB2E4. \uBCA0\uC77C\uC774 \uC5BC\uAD74\uC744 \uBC18 \uB118\uAC8C \uB36E\uB294\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uD2F0\uC544", body: "\u2026\uC544, \uB124. \uB9DE\uC544\uC694. \uC4F8\uBAA8\uC5C6\uC8E0. \uAD1C\uCC2E\uC544\uC694, \uAD1C\uCC2E\uC544\uC694. \uC81C\uAC00 \uAC00\uC838\uAC08\uAC8C\uC694. \uC5F0\uAD6C\uC6D0\uB2D8\uD55C\uD14C\uB294\u2026 \uC548 \uB4DC\uB824\uB3C4 \uB3FC\uC694.", nextId: "n5" },
    { id: "n5", speaker: "", body: "\uD2F0\uC544\uB294 \uC870\uAC01\uB4E4\uC744 \uB450 \uC190\uC73C\uB85C \uC4F8\uC5B4 \uB2F4\uC544 \uB9D0\uC5C6\uC774 \uAC15\uAC00\uB85C \uAC78\uC5B4\uAC04\uB2E4. \uADF8\uB0A0 \uBC24 \uD2F0\uC544\uB294 \uC774\uB984\uC744 \uBD88\uB7EC\uB3C4 \uB300\uB2F5\uD558\uC9C0 \uC54A\uC558\uB2E4.", nextId: "n6" },
    { id: "n6", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uAC15\uAC00 \uBC14\uC704 \uB4A4, \uBCA0\uC77C\uC5D0 \uC5BC\uAD74\uC744 \uBB3B\uC740 \uD2F0\uC544\uAC00 \uC870\uAC01 \uBA87 \uAC1C\uB97C \uB2EC\uBE5B\uC5D0 \uBE44\uCDB0 \uBCF4\uACE0 \uC788\uB2E4. \uB2EC\uBE5B\uC774 \uC870\uAC01\uB9C8\uB2E4 \uB2E4\uB978 \uC0C9\uC73C\uB85C \uBC18\uC0AC\uB41C\uB2E4.)", choices: [
      { id: "sit", label: "\uC544\uBB34 \uB9D0 \uC5C6\uC774 \uC606\uC5D0 \uC549\uC544 \uD568\uAED8 \uB2EC\uBE5B\uC744 \uBCF8\uB2E4", nextId: "n7a" },
      { id: "call", label: "\uD2F0\uC544, \uD558\uACE0 \uC774\uB984\uC744 \uBD88\uB7EC \uBCF8\uB2E4", nextId: "n7b" }
    ] },
    { id: "n7a", speaker: "\uD2F0\uC544", body: "\u2026\uC5F0\uAD6C\uC6D0\uB2D8. \uC774\uAC70 \uC4F8\uBAA8\uC5C6\uC8E0. \uC800\uB3C4 \uC54C\uC544\uC694. \uADFC\uB370 \uC8FC\uC6B8 \uB54C\uB9C8\uB2E4 \uB9C8\uC74C\uC774 \uD658\uD574\uC838\uC11C\u2026 \uADF8\uB9CC\uB450\uB294 \uBC29\uBC95\uC744 \uBAA8\uB974\uACA0\uC5B4\uC694.", nextId: "n8" },
    { id: "n7b", speaker: "\uD2F0\uC544", body: "\u2026\uB124, \uC5F0\uAD6C\uC6D0\uB2D8. \uC774\uB984 \uBD80\uB974\uC2DC\uBA74 \uB300\uB2F5\uC740 \uD558\uB294\uB370\uC694. \uC624\uB298\uC740 \uBC18\uC9DD\uC774\uB294 \uB9D0\uC774 \uC548 \uB098\uC640\uC694. \uBBF8\uC548\uD574\uC694.", nextId: "n8" },
    { id: "n8", speaker: "", body: "\uADF8\uB54C \uBA40\uB9AC \uC232 \uCABD\uC5D0\uC11C \uBD88\uC548\uD55C \uC678\uCE68\uC774 \uB4E4\uB838\uB2E4. \uC5B4\uB460 \uC18D\uC5D0\uC11C \uAE38\uC744 \uC783\uC740 \uB3C4\uB514\uC758 \uBAA9\uC18C\uB9AC\uB2E4. \uB2EC\uBE5B \uC544\uB798 \uD2F0\uC544\uC758 \uC190\uC5D0\uC11C \uC870\uAC01 \uD558\uB098\uAC00 \uBC18\uC9DD \uBE5B\uB0AC\uB2E4.", nextId: "n9" },
    { id: "n9", speaker: "\uD2F0\uC544", body: "\u2026\uB3C4\uB514! \uC5EC\uAE30\uC57C, \uC5EC\uAE30! \uBC18\uC9DD\uC774\uB294 \uCABD\uC73C\uB85C \uC640! \uB2EC\uBE5B\uC774 \uBE44\uCE58\uB294 \uCABD\uC73C\uB85C \uC624\uBA74 \uB3FC!", nextId: "n10" },
    { id: "n10", speaker: "", body: "\uD2F0\uC544\uAC00 \uC720\uB9AC \uC870\uAC01\uC744 \uBA38\uB9AC \uC704\uB85C \uB192\uC774 \uB4E4\uACE0 \uD754\uB4E4\uC5C8\uB2E4. \uC870\uAC01\uB9C8\uB2E4 \uB2EC\uBE5B\uC774 \uD295\uACA8 \uC5B4\uB460 \uC18D\uC5D0 \uD558\uC580 \uC810\uC744 \uADF8\uB9B0\uB2E4. \uD55C\uCC38 \uB4A4 \uC232 \uAC00\uC7A5\uC790\uB9AC\uC5D0\uC11C \uB3C4\uB514\uAC00 \uB2EC\uB824 \uB098\uC654\uB2E4. \uD2F0\uC544\uB294 \uC870\uAC01\uC744 \uAF2D \uC954 \uCC44 \uC6C3\uC9C0\uB3C4 \uC6B8\uC9C0\uB3C4 \uBABB\uD558\uACE0 \uC11C \uC788\uC5C8\uB2E4." }
  ]
};
var CHAPTER_1017 = {
  id: "bond.tia.10",
  startNodeId: "n1",
  titleCard: { title: "\uC4F8\uBAA8 \uC788\uB294 \uBCF4\uBB3C", subtitle: "\uD2F0\uC544 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 4" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC774\uB978 \uC544\uCE68, \uC5F0\uAD6C\uC6D0\uC758 \uBC29 \uCC3D\uAC00. \uCC3D\uD2C0\uC5D0 \uC791\uC740 \uD48D\uACBD \uD558\uB098\uAC00 \uAC78\uB824 \uC788\uB2E4. \uAC15\uAC00\uC5D0\uC11C \uC8FC\uC6CC \uC628 \uC720\uB9AC \uC870\uAC01\uB4E4\uC774 \uAC00\uB294 \uC2E4\uC5D0 \uAFF0\uC5B4\uC838 \uC544\uCE68 \uD587\uC0B4\uC5D0 \uC18C\uB9AC \uC5C6\uC774 \uD754\uB4E4\uB9B0\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uD2F0\uC544", body: "\uC5F0\uAD6C\uC6D0\uB2D8\u2026 \uC544\uCE68\uC774\uC5D0\uC694? \uC800, \uC800 \uC77C\uCC0D \uC654\uC5B4\uC694. \uC544\uB2C8, \uC5B4\uC81C \uBC24\uC0C8 \uB9CC\uB4E4\uC5C8\uC5B4\uC694. \uBCA0\uC77C \uB54C\uBB38\uC5D0 \uB208\uC774 \uC878\uB824\uC11C \uAC00\uBB3C\uAC00\uBB3C\uD55C\uB370\uC694.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uD48D\uACBD\uC740 \uBC14\uB78C\uC774 \uBD88 \uB54C\uB9C8\uB2E4 \uC11C\uB85C \uB2E4\uB978 \uC18C\uB9AC\uB85C \uC9E7\uAC8C \uC6B8\uB9B0\uB2E4. \uC870\uAC01 \uD558\uB098\uD558\uB098\uAC00 \uB2EC\uBE5B \uC544\uB798 \uD2F0\uC544\uAC00 \uBC24\uC0C8 \uACE0\uB978 \uAC83\uC774\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uD2F0\uC544", body: "\uB3C4\uB514\uAC00 \uAE38\uC744 \uCC3E\uB358 \uB0A0\uC774\uC694, \uC81C \uC870\uAC01\uC774 \uC4F8\uBAA8 \uC788\uC5C8\uB2E4\uACE0 \uB2E4\uB4E4 \uB9D0\uD574 \uC92C\uC796\uC544\uC694. \uADF8\uB7F0\uB370 \uC800\uB294 \uC0DD\uAC01\uD588\uC5B4\uC694. \uC4F8\uBAA8\uB294 \uC544\uC9C1 \uC798 \uBAA8\uB974\uACA0\uC9C0\uB9CC, \uBC18\uC9DD\uC774\uB294 \uAC74 \uC5EC\uC804\uD788 \uC88B\uB354\uB77C\uACE0\uC694.", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uD48D\uACBD \uD55C\uAC00\uC6B4\uB370 \uAC00\uC7A5 \uC791\uC740 \uC870\uAC01\uC774 \uB2EC\uB824 \uC788\uB2E4. \uCC98\uC74C\uC5D0 \uC18C\uB9E4 \uC18D\uC73C\uB85C \uC228\uACBC\uB358 \uADF8 \uC870\uAC01\uC774\uB2E4.)", choices: [
      { id: "notice", label: "\uC774 \uAC00\uC7A5 \uC791\uC740 \uC870\uAC01, \uC81C\uC77C \uC544\uB07C\uB358 \uAC70\uC796\uC544", nextId: "n6a" },
      { id: "thanks", label: "\uD48D\uACBD \uC18C\uB9AC\uAC00 \uCC38 \uC88B\uB2E4\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uD2F0\uC544", body: "\u2026\uB4E4\uCF30\uB2E4! \uB9DE\uC544\uC694, \uC81C\uC77C \uCC98\uC74C \uC8FC\uC6B4 \uAC70\uC608\uC694. \uC774\uAC74 \uC815\uB9D0 \uC81C \uAC74\uB370\uC694, \uC5F0\uAD6C\uC6D0\uB2D8\uD55C\uD14C\uB294 \uB4DC\uB824\uB3C4 \uB3FC\uC694.", nextId: "n7" },
    { id: "n6b", speaker: "\uD2F0\uC544", body: "\uC815\uB9D0\uC694? \uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uC88B\uB2E4\uACE0 \uD558\uC2DC\uBA74 \uC18C\uB9AC\uAC00 \uB354 \uC608\uBED0\uC838\uC694! \uADF8, \uADFC\uB370 \uC774 \uC18C\uB9AC\uB294 \uC0AC\uC2E4 \uAC00\uC6B4\uB370 \uC791\uC740 \uC870\uAC01\uC774 \uB0B4\uB294 \uAC70\uC608\uC694. \uC81C\uC77C \uC544\uB07C\uB294 \uC870\uAC01\uC774\uAC70\uB4E0\uC694.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uD2F0\uC544\uAC00 \uBCA0\uC77C\uC744 \uCC9C\uCC9C\uD788 \uAC77\uC5B4 \uC62C\uB838\uB2E4. \uCC98\uC74C\uC73C\uB85C \uC5BC\uAD74\uC774 \uC628\uC804\uD788 \uB4DC\uB7EC\uB0AC\uB2E4. \uC218\uC90D\uC740 \uB208\uC774 \uC5F0\uAD6C\uC6D0\uC758 \uC5BC\uAD74\uC744 \uACE7\uAC8C \uBC14\uB77C\uBCF8\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "\uD2F0\uC544", body: "\uC5F0\uAD6C\uC6D0\uB2D8, \uC774\uAC74 \uC55E\uC73C\uB85C\uB3C4 \uC4F8\uBAA8\uC5C6\uB294 \uBCF4\uBB3C\uC77C \uC218 \uC788\uC5B4\uC694. \uADF8\uB798\uB3C4 \uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uC774\uB984 \uBD88\uB7EC \uC8FC\uC2E4 \uB54C\uB9C8\uB2E4 \uCA0D\uADF8\uB791 \uC18C\uB9AC\uAC00 \uB098\uBA74, \uADF8\uAC8C \uC81C \uC4F8\uBAA8\uC608\uC694.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uBC14\uB78C\uC774 \uBD88\uC5B4 \uD48D\uACBD\uC774 \uD55C\uAEBC\uBC88\uC5D0 \uC6B8\uB838\uB2E4. \uB9D1\uACE0 \uAC00\uB294 \uC18C\uB9AC\uAC00 \uBC29 \uC548\uC5D0 \uD37C\uC9C4\uB2E4. \uBB38\uD2C8\uC73C\uB85C \uB3C4\uB514\uC640 \uD1A0\uB9AC\uCE74, \uD30C\uB8E8\uC544\uAC00 \uC0B4\uC9DD \uC5BC\uAD74\uC744 \uB0B4\uBC00\uACE0 \uC6C3\uACE0 \uC788\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uD2F0\uC544", body: "\uC5F0\uAD6C\uC6D0\uB2D8, \uB2E4\uC74C\uC5D0 \uAC15\uAC00 \uAC08 \uB54C\uB294 \uAC19\uC774 \uAC00\uC694. \uAC19\uC774 \uC8FC\uC6B0\uBA74 \uC4F8\uBAA8\uC5C6\uB294 \uAC83\uB3C4 \uC774\uB984\uC774 \uC0DD\uAE30\uAC70\uB4E0\uC694! \uC624\uB298\uC740 \uC774 \uD48D\uACBD\uC5D0 '\uC5F0\uAD6C\uC6D0\uB2D8 \uAC70'\uB77C\uACE0 \uC774\uB984 \uBD99\uC77C\uAC8C\uC694!" }
  ]
};
var TIA_STORY = {
  relicId: "tia",
  fossilRecord: "\uD751\uC0C9 \uC810\uD310\uC554\uC758 \uC595\uC740 \uC218\uB85C \uB2E8\uBA74\uC5D0\uC11C \uC720\uCCB4 \uD55C \uB9C8\uB9AC\uAC00 \uD1B5\uC9F8\uB85C \uB20C\uB9B0 \uCC44 \uB4DC\uB7EC\uB0AC\uB2E4. \uD53C\uBD80 \uC724\uACFD\uC120\uAE4C\uC9C0 \uB0A8\uC544 \uB4F1\uC9C0\uB290\uB7EC\uBBF8\uC640 \uAF2C\uB9AC\uB0A0\uC758 \uD615\uD0DC\uB97C \uADF8\uB300\uB85C \uBCF5\uC6D0\uD588\uB2E4.",
  diary: "\uBCF5\uC6D0 \uD6C4 \uD2F0\uC544\uB294 \uBB3C\uAC00\uB9CC \uBCF4\uC774\uBA74 \uBA3C\uC800 \uB6F0\uC5B4\uB4E4\uC5B4 \uBB3C\uC0B4\uC744 \uD280\uAE30\uACE0 \uB3C4\uB9DD\uCE58\uB294 \uC7A5\uB09C\uC744 \uBC18\uBCF5\uD55C\uB2E4. \uADF8\uB7EC\uB2E4 \uC5F0\uAD6C\uC6D0\uC774 \uB2E4\uAC00\uC624\uBA74 \uBCA0\uC77C \uC790\uB77D\uC73C\uB85C \uC5BC\uAD74 \uC808\uBC18\uC744 \uAC00\uB9B0 \uCC44 \uB4B7\uAC78\uC74C\uC9C8 \uCE58\uBA74\uC11C\uB3C4, \uC774\uB984\uC744 \uBD80\uB974\uBA74 \uACE7\uBC14\uB85C \uACC1\uC73C\uB85C \uB2EC\uB824\uC640 \uC637\uC790\uB77D\uC744 \uBD99\uC7A1\uACE0 \uB530\uB77C\uB2E4\uB2CC\uB2E4. \uAC15\uAC00\uC5D0\uC11C \uBCF4\uAE09 \uD68C\uC218\uB77C\uBA70 \uBC18\uC9DD\uC774\uB294 \uB3CC\uACFC \uC720\uB9AC \uC870\uAC01\uC744 \uD55C \uC6C0\uD07C\uC529 \uC8FC\uC6CC \uC624\uB294\uB370, \uAC00\uC7A5 \uCC98\uC74C \uC8FC\uC6B4 \uC791\uC740 \uC870\uAC01\uB9CC\uC740 \uB298 \uC18C\uB9E4 \uC18D\uC5D0 \uB530\uB85C \uAC04\uC9C1\uD55C\uB2E4. \uC4F8\uBAA8\uAC00 \uC5C6\uB2E4\uB294 \uB9D0\uC744 \uB4E4\uC740 \uB0A0\uC5D0\uB294 \uAF2C\uB9AC\uB0A0\uC744 \uCD95 \uB298\uC5B4\uB728\uB9AC\uACE0 \uD55C\uCC38 \uB9D0\uC774 \uC5C6\uC5C8\uB2E4.",
  /** 일지 맨 끝에 회색으로 서는, 티아가 연구원에게 건네는 한마디. 뽑기 대사와 다른 일상의 목소리다. */
  closingLine: "\uC5F0\uAD6C\uC6D0\uB2D8! \uC624\uB298\uB3C4 \uBC18\uC9DD\uC774\uB294 \uAC70 \uC8FC\uC6CC \uC654\uC5B4\uC694! \uC774\uB984 \uBD80\uB974\uC2DC\uBA74 \uCA0D\uADF8\uB791 \uB300\uB2F5\uD560\uAC8C\uC694!",
  questions: [
    {
      id: "tia-glass",
      prompt: "\uD2F0\uC544\uAC00 \uBAA8\uC544 \uC628 \uBC18\uC9DD\uC774\uB294 \uC870\uAC01\uB4E4\uC740 \uC5B4\uB514\uC11C \uC8FC\uC6B4 \uAC70\uC57C?",
      choices: [
        {
          id: "river",
          label: "\uAC15\uAC00\uC5D0\uC11C \uC8FC\uC6E0\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uB9DE\uC544\uC694, \uCCA8\uBC99\uCCA8\uBC99 \uAC78\uC5B4 \uB2E4\uB2C8\uB2E4 \uBCF4\uBA74 \uBC1C\uC5D0 \uAC78\uB824\uC694! \uBB3C\uC774 \uB2E6\uC544 \uC918\uC11C \uADF8\uB7F0\uC9C0 \uB2E4 \uB3D9\uAE00\uB3D9\uAE00\uD574\uC694, \uC608\uC058\uC8E0?",
          note: "\uAC15\uAC00\uC758 \uC870\uAC01\uB4E4\uC740 \uBB3C\uC0B4\uC5D0 \uB2F3\uC544 \uBAA8\uC11C\uB9AC\uAC00 \uBAA8\uB450 \uB465\uAE00\uC5C8\uB2E4. \uD558\uB098\uD558\uB098 \uC5B4\uB514\uC11C \uC8FC\uC6E0\uB294\uC9C0 \uAE30\uC5B5\uD558\uACE0 \uC788\uC5C8\uB2E4."
        },
        {
          id: "count",
          label: "\uBAA8\uB450 \uBA87 \uAC1C\uB098 \uBAA8\uC558\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC73C\uC74C, \uC138\uC5B4 \uBCF8 \uC801 \uC5C6\uC5B4\uC694! \uC138\uB2E4 \uBCF4\uBA74 \uD558\uB098\uB77C\uB3C4 \uBE7C\uBA39\uC744\uAE4C \uBD10 \uBB34\uC11C\uC6CC\uC694. \uADF8\uB0E5 \uB9CE\uC774\uC694! \uC544\uC8FC \uB9CE\uC774\uC694!",
          note: "\uAC1C\uC218\uB97C \uBB3B\uC790 \uC190\uAC00\uB77D\uC744 \uBA87 \uBC88 \uC811\uB2E4\uAC00 \uD3EC\uAE30\uD588\uB2E4. \uC138\uB294 \uB300\uC2E0 \uB2E4\uC2DC \uD55C \uC6C0\uD07C \uC950\uC5EC \uC8FC\uC5C8\uB2E4."
        },
        {
          id: "smallest",
          label: "\uC18C\uB9E4 \uC18D\uC5D0 \uC228\uAE34 \uAC00\uC7A5 \uC791\uC740 \uC870\uAC01\uC744 \uC9DA\uC5B4 \uBCF8\uB2E4",
          reply: "\uC544, \uC548 \uB3FC\uC694! \uADF8\uAC74 \uC81C\uC77C \uCC98\uC74C \uC8FC\uC6B4 \uAC70\uB77C\u2026 \uC544\uC9C1 \uC774\uC57C\uAE30\uD560 \uB54C\uAC00 \uC544\uB2C8\uC5D0\uC694. \uB300\uC2E0 \uB098\uC911\uC5D0 \uC54C\uB824 \uB4DC\uB9B4\uAC8C\uC694, \uC57D\uC18D!",
          note: "\uC18C\uB9E4 \uC18D\uC758 \uC791\uC740 \uC870\uAC01\uC744 \uC9DA\uC790 \uAE09\uD788 \uC18C\uB9E4\uB97C \uAC10\uC30C\uB2E4. \uB098\uC911\uC5D0 \uC54C\uB824 \uC8FC\uACA0\uB2E4\uB294 \uC57D\uC18D\uB9CC \uB0A8\uACBC\uB2E4."
        }
      ]
    },
    {
      id: "tia-veil",
      prompt: "\uD2F0\uC544\uB294 \uC65C \uCE6D\uCC2C\uC744 \uB4E4\uC73C\uBA74 \uBCA0\uC77C\uB85C \uC5BC\uAD74\uC744 \uAC00\uB824?",
      choices: [
        {
          id: "shy",
          label: "\uBD80\uB044\uB7EC\uC6CC\uC11C\uB0D0\uACE0 \uC2AC\uCA4D \uBB3B\uB294\uB2E4",
          reply: "\uBD80, \uBD80\uB044\uB7EC\uC6B4 \uAC8C \uC544\uB2C8\uACE0\uC694! \uC5BC\uAD74\uC774 \uB108\uBB34 \uBC18\uC9DD\uC5EC\uC11C \uB208\uC774 \uBD80\uC2E4\uAE4C \uBD10 \uAC00\uB9AC\uB294 \uAC70\uC608\uC694! \u2026\uB77C\uACE0 \uD558\uBA74 \uBBFF\uC5B4 \uC8FC\uC138\uC694?",
          note: "\uCE6D\uCC2C\uD558\uC790 \uBCA0\uC77C\uC774 \uCF54\uB05D\uAE4C\uC9C0 \uC62C\uB77C\uC654\uB2E4. \uAF2C\uB9AC\uB0A0\uB9CC \uAE30\uBD84 \uC88B\uAC8C \uD754\uB4E4\uB9AC\uACE0 \uC788\uC5C8\uB2E4."
        },
        {
          id: "peek",
          label: "\uBCA0\uC77C \uC0AC\uC774\uB85C \uBCF4\uC774\uB294 \uB208\uC774 \uC6C3\uACE0 \uC788\uB2E4\uACE0 \uB9D0\uD574 \uC900\uB2E4",
          reply: "\uC557, \uB4E4\uCF30\uB2E4! \uC5D0\uD5E4\uD5E4\u2026 \uC0AC\uC2E4 \uC6C3\uACE0 \uC788\uC5C8\uC5B4\uC694. \uC228\uB294 \uCC99 \uD558\uB294 \uAC70\uC608\uC694, \uBC18\uCBE4\uC740\uC694.",
          note: "\uC6C3\uACE0 \uC788\uB2E4\uACE0 \uD558\uC790 \uBCA0\uC77C \uC18D\uC5D0\uC11C \uC791\uC740 \uC6C3\uC74C\uC18C\uB9AC\uAC00 \uD130\uC84C\uB2E4. \uADF8\uB7EC\uACE0\uB3C4 \uD55C\uCC38 \uBCA0\uC77C\uC744 \uB0B4\uB9AC\uC9C0 \uC54A\uC558\uB2E4."
        }
      ]
    },
    {
      id: "tia-name",
      prompt: "\uC774\uB984\uC744 \uBD80\uB974\uBA74 \uC65C \uADF8\uB807\uAC8C \uBC14\uB85C \uB2EC\uB824\uC640?",
      choices: [
        {
          id: "habit",
          label: "\uC774\uB984\uB9CC \uBD88\uB7EC\uB3C4 \uB2EC\uB824\uC624\uB294 \uAC8C \uC2E0\uAE30\uD558\uB2E4\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\uC774\uB984\uC744 \uBD88\uB7EC \uC8FC\uC2DC\uBA74 \uC81C\uAC00 \uC5EC\uAE30 \uC788\uB2E4\uB294 \uAC78 \uC544\uB294 \uAC70\uC796\uC544\uC694? \uADF8\uB798\uC11C \uB300\uB2F5\uD558\uACE0 \uC2F6\uC5B4\uC838\uC694. \uCA0D\uADF8\uB791 \uD558\uACE0\uC694!",
          note: "\uC774\uB984\uC744 \uBD80\uB974\uB294 \uC18C\uB9AC\uAC00 \uB2FF\uAE30 \uC804\uC5D0 \uC774\uBBF8 \uB2EC\uB824\uC624\uACE0 \uC788\uC5C8\uB2E4. \uC774\uC720\uB97C \uBB3B\uC790 \uB300\uB2F5\uC774 \uB418\uACE0 \uC2F6\uC5B4\uC11C\uB77C\uACE0 \uD588\uB2E4."
        },
        {
          id: "call",
          label: "\uC77C\uBD80\uB7EC \uC774\uB984\uC744 \uC5EC\uB7EC \uBC88 \uBD88\uB7EC \uBCF8\uB2E4",
          reply: "\uD558, \uD558\uD558! \uB610 \uBD88\uB7EC\uC694? \uC5F0\uAD6C\uC6D0\uB2D8\uC740 \uC9D3\uAD82\uC5B4\uC694! \uADF8\uB798\uB3C4 \uD55C \uBC88 \uB354 \uBD88\uB7EC \uC8FC\uC138\uC694, \uC774\uBC88\uC5D4 \uB354 \uBE68\uB9AC \uC62C\uAC8C\uC694!",
          note: "\uC774\uB984\uC744 \uBA87 \uBC88\uC774\uACE0 \uBD80\uB974\uC790 \uC62C \uB54C\uB9C8\uB2E4 \uC870\uAE08\uC529 \uB354 \uBE68\uB9AC \uB2EC\uB824\uC654\uB2E4. \uB9C8\uC9C0\uB9C9\uC5D0\uB294 \uC228\uC774 \uCC28\uC11C \uC6C3\uACE0 \uC788\uC5C8\uB2E4."
        },
        {
          id: "stay",
          label: "\uC637\uC790\uB77D\uC744 \uBD99\uC7A1\uACE0 \uB530\uB77C\uB2E4\uB2C8\uB294 \uAC74 \uC65C\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC637\uC790\uB77D\uC744 \uC7A1\uACE0 \uC788\uC73C\uBA74 \uB530\uB77C\uAC00\uAE30 \uC26C\uC6CC\uC694. \uC7A1\uACE0 \uC788\uB294 \uAC8C \uC81C\uC77C \uD3B8\uD574\uC694. \uB193\uC73C\uB77C\uACE0 \uD558\uC2DC\uBA74 \uB193\uC744\uAC8C\uC694\u2026?",
          note: "\uC637\uC790\uB77D\uC744 \uC7A1\uB294 \uC774\uC720\uB97C \uBB3B\uC790 \uC190\uC774 \uD55C \uBC88 \uD480\uB838\uB2E4\uAC00 \uB2E4\uC2DC \uC950\uC5C8\uB2E4. \uB193\uC73C\uB77C\uACE0\uB294 \uD558\uC9C0 \uC54A\uC558\uB2E4."
        }
      ]
    }
  ],
  bondStories: { 4: CHAPTER_417, 6: CHAPTER_617, 8: CHAPTER_817, 10: CHAPTER_1017 },
  bondLines: [
    // 0 — 낯선 사이. 물가로 뛰어들었다가 베일 뒤로 숨는다.
    ["\uC557, \uCC98\uC74C \uBD59\uACA0\uC5B4\uC694! \uD2F0\uC544\uC608\uC694! \u2026\uC544, \uC778\uC0AC\uD558\uB2E4 \uBCA0\uC77C\uC774 \uD758\uB7EC\uB0B4\uB838\uC5B4\uC694. \uC7A0\uAE50\uB9CC\uC694!", "\uC5F0\uAD6C\uC6D0\uB2D8\uC774\uB77C\uACE0 \uBD88\uB7EC\uB3C4 \uB418\uC8E0? \uD5E4\uD5E4, \uC785\uC5D0 \uC3D9 \uB4E4\uC5B4\uC640\uC694!", "\uAC15\uAC00\uC5D0 \uC788\uC744\uAC8C\uC694! \uBC18\uC9DD\uC774\uB294 \uAC8C \uC788\uC73C\uBA74 \uAC19\uC774 \uC8FC\uC6CC\uC694, \uCCA8\uBC99\uCCA8\uBC99\uC694!"],
    // 1
    ["\uC624\uB298\uC740 \uBB3C\uC774 \uB530\uB73B\uD574\uC694! \uCCA8\uBC99\uCCA8\uBC99! \uC5F0\uAD6C\uC6D0\uB2D8\uB3C4 \uBC1C\uB9CC \uB2F4\uAC00 \uBCF4\uC138\uC694, \uD55C \uBC88\uB9CC\uC694!", "\uBCA0\uC77C\uC774 \uC790\uAFB8 \uBB3C\uC5D0 \uC816\uC5B4\uC11C \uBB34\uAC70\uC6CC\uC694. \uADF8\uB798\uB3C4 \uBC97\uAE30\uB294 \uC2EB\uC5B4\uC694\u2026 \uC544\uB2C8, \uC544\uC9C1\uC694!", "\uC5F0\uAD6C\uC6D0\uB2D8 \uC2E0\uBC1C\uC740 \uBC18\uC9DD\uC774\uC9C0 \uC54A\uC544\uC694! \uAD1C\uCC2E\uC544\uC694, \uC81C\uAC00 \uC870\uC57D\uB3CC \uD558\uB098 \uB2EC\uC544 \uB4DC\uB9B4\uAC8C\uC694!"],
    // 2
    ["\uBC18\uC9DD\uBC18\uC9DD \uCCA8\uBC99\uCCA8\uBC99! \uC774\uAC74 \uC81C \uC8FC\uBB38\uC774\uC5D0\uC694! \uC678\uC6B0\uBA74 \uBB3C\uC774 \uB354 \uC2E0\uB098\uAC8C \uD280\uC5B4\uC694!", "\uB3C4\uB514\uAC00 \uB530\uB77C \uD558\uB294\uB370 \uC790\uAFB8 \uD2C0\uB824\uC694. \uADF8\uB798\uC11C \uC54C\uB824 \uC92C\uC5B4\uC694, \uBC18\uC9DD\uC740 \uBA3C\uC800 \uD558\uACE0 \uCCA8\uBC99\uC740 \uB098\uC911\uC5D0\uC694!", "\uC5F0\uAD6C\uC6D0\uB2D8 \uC774\uB984 \uBD80\uB974\uBA74\uC11C \uAC78\uC73C\uBA74 \uBC1C\uAC78\uC74C\uC774 \uAC00\uBCBC\uC6CC\uC838\uC694. \uC2E0\uAE30\uD558\uC8E0?"],
    // 3
    ["\uBB3C\uC7A5\uAD6C\uB294 \uAF2C\uB9AC\uB0A0\uB85C \uD558\uB294 \uAC8C \uC81C\uC77C \uC798 \uD280\uC5B4\uC694! \uC774\uAC74 \uBE44\uBC00 \uAE30\uC220\uC778\uB370 \uC5F0\uAD6C\uC6D0\uB2D8\uD55C\uD14C\uB9CC \uC54C\uB824 \uB4DC\uB824\uC694!", "\uC624\uB298\uC740 \uD30C\uB8E8\uC544\uAC00 \uCC98\uC74C\uC73C\uB85C \uBA3C\uC800 \uBB3C\uC744 \uD280\uACBC\uC5B4\uC694. \uC640, \uAE5C\uC9DD \uB180\uB790\uC9C0\uB9CC \uAE30\uBEE4\uC5B4\uC694!", "\uC624\uB298 \uBB3C\uC774 \uC5C4\uCCAD \uB9D1\uC558\uC5B4\uC694! \uBC14\uB2E5 \uB3CC\uAE4C\uC9C0 \uB2E4 \uBCF4\uC5EC\uC11C \uD55C\uCC38 \uB4E4\uC5EC\uB2E4\uBD24\uC5B4\uC694!"],
    // 4 — 장 4 이후: 가장 작은 조각이 소매 속에 있다.
    ["\uC624\uB298 \uC8FC\uC6B4 \uAC83 \uC911\uC5D0\uC11C \uC81C\uC77C \uBC18\uC9DD\uC774\uB294 \uAC78 \uC5F0\uAD6C\uC6D0\uB2D8 \uC8FC\uBA38\uB2C8\uC5D0 \uB123\uC5B4 \uB480\uC5B4\uC694! \uCA0D\uADF8\uB791 \uC18C\uB9AC \uB098\uBA74 \uC800\uC608\uC694!", "\uC18C\uB9E4 \uC18D\uC758 \uC870\uAC01\uC740 \uC544\uC9C1 \uBE44\uBC00\uC774\uC5D0\uC694. \uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uC878\uB77C\uB3C4 \uC548 \uC54C\uB824 \uB4DC\uB9B4 \uAC70\uC608\uC694\u2026 \uC544\uB2C8, \uC870\uAE08\uB9CC \uC878\uB77C \uBCF4\uC138\uC694?", "\uC5F0\uAD6C\uC6D0\uB2D8 \uC8FC\uBA38\uB2C8 \uBB34\uAC70\uC6CC\uC84C\uC8E0? \uC81C\uAC00 \uD55C \uAC1C \uB354 \uB123\uC5C8\uAC70\uB4E0\uC694! \uD5E4\uD5E4."],
    // 5
    ["\uBB3C\uC7A5\uAD6C\uB294 \uD63C\uC790 \uD560 \uB54C\uBCF4\uB2E4 \uAC19\uC774 \uD560 \uB54C \uC18C\uB9AC\uAC00 \uB450 \uBC30\uC608\uC694! \uAC19\uC774 \uD558\uBA74 \uBC18\uC9DD\uB3C4 \uB450 \uBC30\uACE0\uC694!", "\uC5F0\uAD6C\uC6D0\uB2D8 \uC637\uC790\uB77D, \uC624\uB298\uB3C4 \uC7A1\uC544\uB3C4 \uB418\uC8E0? \uB193\uC73C\uB77C\uACE0 \uD558\uC2DC\uBA74 \uB193\uC744\uAC8C\uC694\u2026 \uD5E4\uD5E4.", "\uC218\uC90D\uC744 \uB54C\uB294 \uBCA0\uC77C\uB85C \uAC00\uB9AC\uBA74 \uB3FC\uC694! \uADFC\uB370 \uC5F0\uAD6C\uC6D0\uB2D8\uC740 \uBCA0\uC77C \uC5C6\uC774\uB3C4 \uB208\uC744 \uB9C8\uC8FC \uBD10\uC11C \uC2E0\uAE30\uD574\uC694."],
    // 6 — 장 6 이후: 물장구 소동 이후.
    ["\uC9C0\uB09C\uBC88 \uBB3C\uC7A5\uAD6C\uB294 \uCD5C\uACE0\uC600\uC5B4\uC694! \uB2E4 \uAC19\uC774 \uC816\uC5C8\uC73C\uB2C8\uAE4C \uB2E4 \uAC19\uC774 \uC774\uAE34 \uAC70\uB798\uC694!", "\uB204\uAC00 \uC81C \uD3B8\uC774 \uB418\uC5B4 \uC8FC\uBA74 \uB9C8\uC74C\uC774 \uB193\uC5EC\uC694. \uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uC81C \uD3B8\uC774\uB77C \uC624\uB298\uC740 \uD558\uB098\uB3C4 \uC548 \uB5A8\uB824\uC694!", "\uC624\uB298\uC740 \uD558\uB298\uC774 \uB192\uC544\uC11C \uAD6C\uB984\uB3C4 \uBC18\uC9DD\uC5EC\uC694! \uC5F0\uAD6C\uC6D0\uB2D8, \uC704 \uBCF4\uC138\uC694!"],
    // 7
    ["\uC624\uB298 \uC8FC\uC6B4 \uC870\uAC01\uC740 \uC870\uAE08 \uC587\uC544\uC694. \uD587\uBE5B\uC5D0 \uBE44\uCD94\uBA74 \uBB34\uC9C0\uAC1C\uAC00 \uB098\uC640\uC694! \uBCF4\uC2E4\uB798\uC694?", "\uC624\uB298 \uC8FC\uC6B4 \uAC74 \uBAA8\uC591\uC774 \uC880 \uC774\uC0C1\uD574\uC694. \uADFC\uB370 \uADF8\uB798\uC11C \uB354 \uC88B\uC544\uC694! \uC774\uC0C1\uD55C \uAC8C \uC81C\uC77C \uC624\uB798 \uAE30\uC5B5\uB098\uAC70\uB4E0\uC694.", "\uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uC606\uC5D0 \uACC4\uC2DC\uBA74 \uC870\uAC01\uB4E4\uC774 \uB354 \uBC18\uC9DD\uC5EC\uC694. \uC774\uAC74 \uC815\uB9D0\uC774\uC5D0\uC694!"],
    // 8 — 장 8 이후: 쓸모없다는 말을 이겨 낸 뒤.
    ["\uB2EC\uBC24\uC5D0 \uC870\uAC01\uC744 \uD754\uB4E4\uBA74 \uB2EC\uBE5B\uC774 \uBC14\uB2E5\uC5D0\uC11C \uCDA4\uCDB0\uC694! \uAC19\uC774 \uBCF4\uB7EC \uAC00\uC694, \uC5F0\uAD6C\uC6D0\uB2D8!", "\uC4F8\uBAA8\uC5C6\uB2E4\uACE0 \uD574\uB3C4 \uAD1C\uCC2E\uC544\uC694. \u2026\uC544\uC9C1 \uC870\uAE08 \uC544\uD504\uC9C0\uB9CC\uC694.", "\uD30C\uB8E8\uC544\uAC00 \uC0AC\uACFC\uD588\uC5B4\uC694. \uC800\uB3C4 \uC0AC\uACFC\uD588\uC5B4\uC694. \uC11C\uB85C \uC0AC\uACFC\uD558\uB2C8\uAE4C \uB9C8\uC74C\uC774 \uBC18\uC9DD\uBC18\uC9DD\uD574\uC84C\uC5B4\uC694!"],
    // 9
    ["\uD48D\uACBD\uC740 \uBC14\uB78C\uC774 \uBD88\uBA74 \uCA0D\uADF8\uB791 \uC18C\uB9AC\uAC00 \uB098\uC694. \uADF8 \uC18C\uB9AC\uAC00 \uC81C \uC774\uB984 \uAC19\uC544\uC11C \uC88B\uC544\uC694.", "\uAC00\uC7A5 \uC791\uC740 \uC870\uAC01\uC744 \uD48D\uACBD\uC5D0 \uAC78\uC5B4 \uB480\uC5B4\uC694. \uAC00\uC6B4\uB370\uC5D0\uC11C \uB300\uD45C\uB85C \uC6B8\uC5B4\uC694, \uD5E4\uD5E4.", "\uC5F0\uAD6C\uC6D0\uB2D8, \uD48D\uACBD \uC18C\uB9AC \uB4E4\uC73C\uBA74\uC11C \uB0AE\uC7A0 \uC790 \uBCF8 \uC801 \uC788\uC5B4\uC694? \uBB3C\uC18C\uB9AC\uB791 \uBE44\uC2B7\uD55C\uB370 \uB354 \uD3EC\uADFC\uD574\uC694!"],
    // 10 — 마음을 연 사이. 베일을 걷고 눈을 마주친다.
    ["\uC5F0\uAD6C\uC6D0\uB2D8, \uC774\uB984 \uBD88\uB7EC \uC8FC\uC138\uC694! \uC624\uB298\uC740 \uBCA0\uC77C\uC744 \uC62C\uB9AC\uACE0 \uB300\uB2F5\uD560\uAC8C\uC694. \uCA0D\uADF8\uB791 \uD558\uACE0\uC694!", "\uC624\uB298\uC740 \uC81C \uBCF4\uBB3C\uC744 \uC5F0\uAD6C\uC6D0\uB2D8\uAED8 \uB4DC\uB838\uC5B4\uC694. \uD48D\uACBD \uC18C\uB9AC, \uB4E4\uB9AC\uC138\uC694?", "\uB2E4\uC74C\uC5D4 \uAC15\uAC00\uC5D0 \uAC19\uC774 \uAC00\uC694. \uAC19\uC774 \uC8FC\uC6B0\uBA74 \uC4F8\uBAA8\uC5C6\uB294 \uAC83\uB3C4 \uC774\uB984\uC774 \uC0DD\uAE30\uAC70\uB4E0\uC694, \uD5E4\uD5E4!"]
  ]
};

