var CHAPTER_418 = {
  id: "bond.yuti.4",
  startNodeId: "n1",
  titleCard: { title: "\uC606\uC790\uB9AC\uC5D0\uC11C \uB098\uD0C0\uB09C \uB0A0", subtitle: "\uC720\uD2F0 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 1" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC544\uCE68 \uD68C\uC758\uAC00 \uD55C\uCC3D\uC778 \uD68C\uC758\uC2E4. \uBAA8\uB450\uAC00 \uC815\uBA74 \uD654\uBA74\uC744 \uBCF4\uACE0 \uC788\uB2E4. \uC5F0\uAD6C\uC6D0\uC758 \uC624\uB978\uCABD \uC758\uC790\uAC00 \uC5B4\uB290\uC0C8 \uD558\uB098 \uCC44\uC6CC\uC838 \uC788\uB2E4. \uC544\uBB34\uB3C4 \uC5B8\uC81C \uC549\uC558\uB294\uC9C0 \uBAA8\uB978\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uC720\uD2F0", body: "\u2026\u2026\uBCF4\uC2A4, \uC800 \uBA3C\uC800 \uC640 \uC788\uC5C8\uC5B4\uC694. \uC544\uAE4C\uBD80\uD130\uC694. \uC544, \uC544\uB2C8, \uBC29\uAE08\uC774\uC694. \uC798 \uBAA8\uB974\uACA0\uC5B4\uC694\u2026", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uC720\uD2F0\uAC00 \uBC14\uB78C\uC5D0 \uB118\uC5B4\uAC00\uB358 \uC5F0\uAD6C\uC6D0\uC758 \uB178\uD2B8 \uBAA8\uC11C\uB9AC\uB97C \uB9D0\uC5C6\uC774 \uB20C\uB7EC \uB193\uACE0\uB294 \uC2DC\uC120\uC744 \uCC3D\uBC16\uC73C\uB85C \uB3CC\uB9B0\uB2E4. \uC790\uAE30\uAC00 \uD55C \uC77C\uC774 \uC544\uB2CC \uCC99\uC774\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uD384\uB7ED\uC774\uB358 \uD398\uC774\uC9C0\uAC00 \uAC00\uB9CC\uD788 \uB20C\uB824 \uC788\uB2E4. \uB204\uB978 \uC190\uC740 \uC774\uBBF8 \uC18C\uB9E4 \uC18D\uC774\uB2E4.)", choices: [
      { id: "thanks", label: "\uACE0\uB9D9\uB2E4\uACE0 \uC791\uAC8C \uC18D\uC0AD\uC778\uB2E4", nextId: "n5a" },
      { id: "pretend", label: "\uBABB \uBCF8 \uCC99 \uB178\uD2B8\uB97C \uB36E\uC5B4 \uB454\uB2E4", nextId: "n5b" }
    ] },
    { id: "n5a", speaker: "\uC720\uD2F0", body: "\u2026\u2026\uC81C\uAC00 \uD55C \uAC70 \uC544\uB2CC\uB370\uC694. \uADFC\uB370 \uBCF4\uC168\uC73C\uBA74 \uB410\uC5B4\uC694. \uADF8, \uBCF4\uC2A4\u2026", nextId: "n6" },
    { id: "n5b", speaker: "\uC720\uD2F0", body: "\u2026\u2026\u2026\u2026\uC544. \uB36E\uC73C\uC168\uB124\uC694. \uAD1C\uCC2E\uC544\uC694. \uC544\uB2C8, \uC81C\uAC00 \uD55C \uAC70 \uC544\uB2C8\uC5D0\uC694. \uC6D0\uB798 \uADF8\uB7AC\uB358 \uAC78 \uAC70\uC608\uC694, \uC544\uB9C8\u2026", nextId: "n6" },
    { id: "n6", speaker: "", body: "\uD68C\uC758\uAC00 \uB05D\uB098\uACE0 \uC0AC\uB78C\uB4E4\uC774 \uC77C\uC5B4\uC11C\uC790 \uC720\uD2F0\uB294 \uC18C\uB9AC \uC5C6\uC774 \uC758\uC790\uC5D0\uC11C \uBE60\uC838\uB098\uAC00 \uBCBD \uCABD\uC744 \uB530\uB77C \uAC78\uC5B4\uAC04\uB2E4. \uC815\uBA74 \uD1B5\uB85C\uB294 \uD55C \uBC88\uB3C4 \uC4F0\uC9C0 \uC54A\uB294\uB2E4.", nextId: "n7" },
    { id: "n7", speaker: "\uD30C\uCE58", body: "\uC57C, \uC720\uD2F0. \uC65C \uB9E8\uB0A0 \uBCBD\uC73C\uB85C \uB2E4\uB140? \uAC00\uC6B4\uB370\uB85C \uAC78\uC5B4. \uBB50\uAC00 \uBB38\uC81C\uC57C?", nextId: "n8" },
    { id: "n8", speaker: "\uC720\uD2F0", body: "\uAC00\uC6B4\uB370\uB294\u2026 \uB208\uC774 \uB9CE\uC544\uC11C\uC694. \uBCBD\uC774 \uD3B8\uD574\uC694. \uC800\uB294 \uC606\uC5D0\uC11C \uBCF4\uB294 \uAC8C \uC88B\uAC70\uB4E0\uC694\u2026", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uD30C\uCE58\uAC00 \uC785\uC5D0 \uBB38 \uC0AC\uD0D5\uC744 \uAD74\uB9AC\uB2E4\uAC00 \uC5B4\uAE68\uB97C \uC73C\uC4F1\uD55C\uB2E4. \uB354 \uBB3B\uC9C0\uB294 \uC54A\uB294\uB2E4. \uC720\uD2F0\uC758 \uADF8\uB9BC\uC790\uAC00 \uBB38 \uC55E\uC5D0\uC11C \uD55C \uBC88 \uBA48\uCDC4\uB2E4\uAC00 \uC0AC\uB77C\uC9C4\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uC720\uD2F0", body: "\uBCF4\uC2A4\u2026 \uC815\uBA74\uC740 \uC544\uC9C1 \uC81C \uC790\uB9AC\uAC00 \uC544\uB2CC \uAC83 \uAC19\uC544\uC694. \uB2E4\uC74C\uC5D0 \uD55C \uBC88 \uB354 \uC774\uC57C\uAE30\uD574\uB3C4 \uB3FC\uC694? \uC9C0\uAE08\uC740 \uBAA9\uC774 \uC870\uAE08 \uB9D0\uB77C\uC11C\uC694\u2026" }
  ]
};
var CHAPTER_618 = {
  id: "bond.yuti.6",
  startNodeId: "n1",
  titleCard: { title: "\uB204\uAC00 \uD588\uB294\uC9C0 \uBAB0\uB77C\uB3C4 \uB418\uB294 \uC77C", subtitle: "\uC720\uD2F0 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 2" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC5F0\uAD6C\uC18C \uC911\uC815\uC758 \uC624\uD6C4. \uB3C4\uB514\uAC00 \uB091\uB091\uB300\uBA70 \uC62E\uAE30\uB358 \uC790\uB8CC \uC0C1\uC790\uC758 \uBC18\uB300\uD3B8\uC774 \uAC11\uC790\uAE30 \uAC00\uBCBC\uC6CC\uC9C4\uB2E4. \uB3CC\uC544\uBCF4\uB2C8 \uC544\uBB34\uB3C4 \uC5C6\uACE0, \uC0C1\uC790\uB294 \uBC8C\uC368 \uBCA4\uCE58 \uC606\uC5D0 \uB0B4\uB824\uC838 \uC788\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uB3C4\uB514", body: "\uC5B4? \uBC29\uAE08 \uB204\uAC00 \uAC19\uC774 \uB4E4\uC5C8\uC9C0? \uC774\uAC8C \uD63C\uC790 \uB730 \uB9AC\uAC00 \uC5C6\uB294\uB370\u2026 \uC774\uBC88\uC774 \uB450 \uBC88\uC9F8\uC57C!", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uBCA4\uCE58 \uB4A4 \uB098\uBB34 \uADF8\uB298\uC5D0\uC11C \uC720\uD2F0\uAC00 \uBC1C\uB05D\uC744 \uBAA8\uC73C\uACE0 \uC11C \uC788\uB2E4. \uB208\uC740 \uBA40\uB9AC \uD558\uB298\uC744 \uD5A5\uD574 \uC788\uC9C0\uB9CC \uADC0\uB294 \uB3C4\uB514 \uCABD\uC73C\uB85C \uAE30\uC6B8\uC5B4 \uC788\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uC720\uD2F0\uC758 \uC5B4\uAE68\uAC00 \uC544\uC8FC \uC870\uAE08 \uC62C\uB77C\uAC00 \uC788\uB2E4. \uAC74\uB128 \uCABD\uC774 \uB4E3\uACE0 \uC788\uB2E4.)", nextId: "n5" },
    { id: "n5", speaker: "\uB3C4\uB514", body: "\uACE0\uB9C8\uC6CC, \uB204\uAC00 \uB3C4\uC654\uB294\uC9C0 \uBAA8\uB974\uC9C0\uB9CC! \uAC10\uC0AC \uAE30\uB85D\uC740 \uB0A8\uACA8\uC57C\uC9C0! \uC544, \uC5F0\uAD6C\uC6D0\uB2D8\uB3C4 \uBCF4\uC168\uC5B4\uC694?", nextId: "n6" },
    { id: "n6", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uC720\uD2F0\uB97C \uB3CC\uC544\uBCF8\uB2E4. \uB208\uC774 \uB9C8\uC8FC\uCE58\uAE30 \uC9C1\uC804 \uC720\uD2F0\uAC00 \uB098\uBB34 \uB4A4\uB85C \uD55C \uBC1C \uC228\uB294\uB2E4.)", choices: [
      { id: "tell", label: "\uB204\uAC00 \uB3C4\uC654\uB294\uC9C0 \uB3C4\uB514\uC5D0\uAC8C \uB9D0\uD574 \uC8FC\uACE0 \uC2F6\uB2E4\uACE0 \uC18D\uC0AD\uC778\uB2E4", nextId: "n7a" },
      { id: "keep", label: "\uBE44\uBC00\uB85C \uD574 \uB450\uACA0\uB2E4\uACE0 \uC18D\uC0AD\uC778\uB2E4", nextId: "n7b" }
    ] },
    { id: "n7a", speaker: "\uC720\uD2F0", body: "\u2026\uC548 \uB3FC\uC694, \uBCF4\uC2A4. \uC54C\uB824\uC9C0\uBA74 \uB2E4\uC74C\uBD80\uD130 \uBABB \uB3C4\uC640\uC694. \uACE0\uB9D9\uB2E4\uB294 \uB9D0\uC740 \uC5B4\uB5BB\uAC8C \uBC1B\uC544\uC57C \uD560\uC9C0 \uBAA8\uB974\uACA0\uC5B4\uC11C\uC694\u2026", nextId: "n8" },
    { id: "n7b", speaker: "\uC720\uD2F0", body: "\u2026\u2026\uACE0\uB9C8\uC6CC\uC694, \uBCF4\uC2A4. \uC800, \uBE44\uBC00 \uC9C0\uD0A4\uB294 \uAC74 \uC798\uD558\uB294\uB370 \uBE44\uBC00\uC744 \uB4E4\uD0A4\uB294 \uAC74 \uBABB\uD574\uC694. \uADF8\uB798\uC11C \uB3C4\uC640\uC8FC\uC2DC\uB294 \uAC8C \uC815\uB9D0 \uACE0\uB9C8\uC6CC\uC694.", nextId: "n8" },
    { id: "n8", speaker: "", body: "\uB3C4\uB514\uAC00 \uC0C1\uC790\uB97C \uC548\uACE0 \uBB50\uB77C\uACE0 \uC911\uC5BC\uAC70\uB9AC\uBA70 \uAC04\uB2E4. \uC720\uD2F0\uAC00 \uB098\uBB34 \uADF8\uB298\uC5D0\uC11C \uB098\uC640 \uC5F0\uAD6C\uC6D0 \uC606 \uBCA4\uCE58 \uB05D\uC5D0 \uC549\uB294\uB2E4. \uC5B4\uAE68 \uD3ED \uD558\uB098\uB9CC\uD07C \uB5A8\uC5B4\uC838\uC11C.", nextId: "n9" },
    { id: "n9", speaker: "\uC720\uD2F0", body: "\u2026\uB3C4\uB514, \uAD1C\uCC2E\uC544 \uBCF4\uC600\uC8E0? \uC800\uB294 \uADF8\uAC78 \uBCF4\uB294 \uAC8C \uC88B\uC544\uC694. \uC81C\uAC00 \uC788\uC5C8\uB2E4\uB294 \uAC74 \uC548 \uC54C\uB824\uB3C4 \uB418\uACE0\uC694.", nextId: "n10" },
    { id: "n10", speaker: "\uC720\uD2F0", body: "\uBCF4\uC2A4\uB294 \uC65C \uC544\uC138\uC694? \uC81C\uAC00 \uD55C \uAC70. \uC544, \uBAA8\uB974\uB294 \uCC99\uD558\uC154\uB3C4 \uB3FC\uC694. \uC544\uB294 \uC0AC\uB78C\uC774 \uD55C \uBA85\uCBE4\uC740 \uC788\uC5B4\uB3C4 \uAD1C\uCC2E\uC744 \uAC83 \uAC19\uC544\uC11C\uC694\u2026" }
  ]
};
var CHAPTER_818 = {
  id: "bond.yuti.8",
  startNodeId: "n1",
  titleCard: { title: "\uC120\uBC30\uB4E4 \uD749\uB0B4", subtitle: "\uC720\uD2F0 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 3" },
  nodes: [
    { id: "n1", speaker: "", body: "\uD6C8\uB828\uC7A5 \uB4A4\uD3B8\uC758 \uBE48\uD130. \uC720\uD2F0\uAC00 \uAC70\uC6B8 \uC55E\uC5D0 \uC11C\uC11C \uC5B4\uAE68\uB97C \uCB49 \uD3B4\uACE0 \uD131\uC744 \uC62C\uB824 \uBCF4\uACE0 \uC788\uB2E4. \uB204\uAC00 \uC624\uBA74 \uACE7 \uD480 \uC218 \uC788\uAC8C \uD55C \uBC1C\uC774 \uB4A4\uC5D0 \uC788\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uC720\uD2F0", body: "\uBCF4\uC2A4. \uC800, \uC774\uB807\uAC8C\u2026 \uC73C\uC74C\u2026 \uC774\uB807\uAC8C \uB9D0\uD558\uBA74 \uB418\uC8E0? \u300C\uBCF4\uC2A4, \uC624\uB298 \uC784\uBB34 \uB9E1\uACA8 \uC8FC\uC138\uC694\u300D. \uC548 \uC5B4\uC6B8\uB9AC\uC8E0\u2026", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uAC70\uC6B8 \uC18D \uC720\uD2F0\uC758 \uBAA9\uC18C\uB9AC\uB294 \uD06C\uC9C0\uB9CC \uB208\uC740 \uAC70\uC6B8 \uC18D \uC790\uC2E0\uC744 \uD53C\uD558\uACE0 \uC788\uB2E4. \uC5F0\uAD6C\uC6D0\uC774 \uBB38\uD131\uC5D0 \uC11C \uC788\uB2E4\uB294 \uAC78 \uC54C\uC544\uCC44\uC790 \uC5B4\uAE68\uAC00 \uC21C\uC2DD\uAC04\uC5D0 \uCC98\uC9C4\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uD654\uB824\uD55C \uC120\uBC30\uB4E4\uC758 \uBAB8\uC9D3\uC744 \uB530\uB77C \uD558\uB2E4\uAC00 \uB4E4\uD0A8 \uC5BC\uAD74\uC774\uB2E4.)", choices: [
      { id: "again", label: "\uD55C \uBC88 \uB354 \uD574 \uBCF4\uB77C\uACE0 \uBD80\uD0C1\uD55C\uB2E4", nextId: "n5a" },
      { id: "own", label: "\uC6D0\uB798 \uC720\uD2F0 \uBAA9\uC18C\uB9AC\uAC00 \uB354 \uC88B\uB2E4\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n5b" }
    ] },
    { id: "n5a", speaker: "\uC720\uD2F0", body: "\uB2E4\uC2DC\uC694\u2026? \uC544, \uC54C\uACA0\uC5B4\uC694. \u300C\uBCF4\uC2A4, \uC624\uB298 \uC784\uBB34\u2026 \uB9E1\uACA8 \uC8FC\uC138\uC694\u300D. \u2026\uB05D\uC774 \uD750\uB824\uC838\uC694. \uD070 \uC18C\uB9AC\uB294 \uC5B4\uB824\uC6CC\uC694.", nextId: "n6" },
    { id: "n5b", speaker: "\uC720\uD2F0", body: "\uC81C \uBAA9\uC18C\uB9AC\uC694\u2026? \uC791\uC740\uB370\uC694. \uC55E\uC5D0 \uC11C\uB294 \uBD84\uB4E4\uC740 \uBAA9\uC18C\uB9AC\uAC00 \uD06C\uACE0 \uD658\uD574\uC11C\u2026 \uC800\uB3C4 \uADF8\uB807\uAC8C \uB418\uACE0 \uC2F6\uC5C8\uC5B4\uC694.", nextId: "n6" },
    { id: "n6", speaker: "", body: "\uBE48\uD130 \uAC00\uC7A5\uC790\uB9AC\uB85C \uC544\uD06C\uAC00 \uD6C4\uB4DC\uB97C \uC4F4 \uCC44 \uC870\uC2EC\uC2A4\uB7FD\uAC8C \uAC78\uC5B4 \uB4E4\uC5B4\uC628\uB2E4. \uC720\uD2F0\uAC00 \uBC18\uC0AC\uC801\uC73C\uB85C \uC5B4\uAE68\uB97C \uD3C8\uB2E4\uAC00, \uC544\uD06C\uC758 \uAC81\uBA39\uC740 \uB208\uC744 \uBCF4\uACE0 \uB2E4\uC2DC \uCC9C\uCC9C\uD788 \uB0B4\uB9B0\uB2E4.", nextId: "n7" },
    { id: "n7", speaker: "\uC544\uD06C", body: "\uC544, \uC720\uD2F0\u2026 \uC5F0\uC2B5\uD558\uB294 \uAC70\uC600\uC5B4? \uB098\uB3C4 \uAC00\uB054 \uAC70\uC6B8 \uC55E\uC5D0\uC11C \uC778\uC0AC \uC5F0\uC2B5\uD574. \uC548 \uC5B4\uC6B8\uB9AC\uB294 \uAC74 \uB611\uAC19\uC544.", nextId: "n8" },
    { id: "n8", speaker: "\uC720\uD2F0", body: "\u2026\uC544\uD06C\uB3C4 \uC5F0\uC2B5\uD574\uC694? \uC544, \uD574. \uAC19\uC774 \uD574 \uBCFC\uB798. \uC11C\uB85C \uBCF4\uBA74\uC11C\uB294 \uBABB \uD558\uB2C8\uAE4C, \uB4F1 \uB3CC\uB9AC\uACE0.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uB458\uC774 \uB4F1\uC744 \uB9DE\uB300\uACE0 \uC11C\uC11C \uC791\uC740 \uBAA9\uC18C\uB9AC\uB85C \uAC19\uC740 \uC778\uC0AC\uB97C \uBC88\uAC08\uC544 \uC5F0\uC2B5\uD55C\uB2E4. \uC5F0\uAD6C\uC6D0\uC740 \uBCBD \uCABD\uC73C\uB85C \uBB3C\uB7EC\uB098 \uB4E3\uC9C0 \uC54A\uB294 \uCC99\uD55C\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uC720\uD2F0", body: "\uBCF4\uC2A4. \uC120\uBC30\uB4E4 \uD749\uB0B4\uB294 \uC544\uC9C1 \uBABB \uD574\uC694. \uADF8\uCE58\uB9CC \uC800\uB9CC\uC758 \uBAA9\uC18C\uB9AC\uB85C \u300C\uBCF4\uC2A4\u300D\uB77C\uACE0 \uBD80\uB974\uB294 \uAC74 \uC774\uC81C \uD574 \uBCFC\uAC8C\uC694\u2026 \uC544, \uBC29\uAE08 \uD55C \uBC88 \uD588\uB124\uC694." }
  ]
};
var CHAPTER_1018 = {
  id: "bond.yuti.10",
  startNodeId: "n1",
  titleCard: { title: "\uC815\uBA74\uC5D0 \uC11C \uBCF4\uB294 \uBC24", subtitle: "\uC720\uD2F0 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 4" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC870\uC6A9\uD55C \uBC24\uC758 \uC5F0\uAD6C\uC18C \uC625\uC0C1. \uBCC4\uC774 \uAC00\uB4DD\uD558\uB2E4. \uC5F0\uAD6C\uC6D0\uC774 \uB09C\uAC04 \uC55E\uC5D0 \uC11C \uC788\uB294\uB370 \uB4A4\uC5D0\uC11C \uC544\uC8FC \uC791\uC740 \uBC1C\uC18C\uB9AC\uAC00 \uB09C\uB2E4. \uC774\uBC88\uC5D0\uB294 \uC606\uC774 \uC544\uB2C8\uB77C \uC815\uBA74 \uBC29\uD5A5\uC774\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uC720\uD2F0", body: "\uBCF4\uC2A4. \uC800 \uC5EC\uAE30 \uC788\uC5B4\uC694. \uB4A4\uAC00 \uC544\uB2C8\uB77C, \uC55E\uC73C\uB85C \uB3CC\uC544\uC11C \uC654\uC5B4\uC694. \uAD1C\uCC2E\uC8E0? \uB208\uC774 \uB9C8\uC8FC\uCCD0\uB3C4\uC694.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uC720\uD2F0\uAC00 \uC5F0\uAD6C\uC6D0 \uC55E\uC5D0 \uC120\uB2E4. \uC2DC\uC120\uC774 \uD754\uB4E4\uB9AC\uB2E4\uAC00 \uAC04\uC2E0\uD788 \uC5F0\uAD6C\uC6D0\uC758 \uB208\uB192\uC774\uC5D0 \uB2FF\uB294\uB2E4. \uB450 \uC190\uC744 \uC55E\uC5D0 \uBAA8\uC544 \uC954 \uCC44 \uC228\uC744 \uACE0\uB978\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC720\uD2F0", body: "\uC774\uBC88\uC5D0\uB294 \uC2AC\uCA4D \uC9C0\uB098\uAC00\uC9C0 \uC54A\uC744\uAC8C\uC694. \uC9C1\uC811 \uB9D0\uC500\uB4DC\uB9B4\uAC8C\uC694. \uADF8\uB3D9\uC548 \uC606\uC5D0\uC11C \uB3C4\uC6B4 \uAC70, \uC800 \uB9DE\uC544\uC694\u2026", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uBAA8\uC740 \uC190\uC774 \uB5A8\uB9B0\uB2E4. \uB5A8\uB9AC\uB294\uB370\uB3C4 \uB208\uC744 \uD53C\uD558\uC9C0 \uC54A\uB294\uB2E4.)", choices: [
      { id: "take", label: "\uACE0\uB9D9\uB2E4\uACE0 \uB300\uB2F5\uD55C\uB2E4", nextId: "n6a" },
      { id: "wait", label: "\uC720\uD2F0\uC758 \uB9D0\uC744 \uB05D\uAE4C\uC9C0 \uAE30\uB2E4\uB9B0\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uC720\uD2F0", body: "\u2026\uB4E4\uC73C\uC168\uB2E4. \uB4E4\uC73C\uC168\uC5B4\uC694, \uBCF4\uC2A4. \uD56D\uC0C1 \uB9D0\uC5C6\uC774 \uD558\uACE0 \uB3CC\uC544\uC130\uB294\uB370, \uC624\uB298\uC740 \uB05D\uAE4C\uC9C0 \uB9D0\uD574 \uBC84\uB838\uB124\uC694.", nextId: "n7" },
    { id: "n6b", speaker: "\uC720\uD2F0", body: "\uD558\uACE0 \uC2F6\uC740 \uB9D0\uC774 \uC788\uC5C8\uB294\uB370\u2026 \uB9C9\uC0C1 \uC11C\uB2C8\uAE4C \uB2E4 \uC78A\uC5B4\uBC84\uB838\uC5B4\uC694. \uADF8\uB0E5 \uC774\uAC70 \uD558\uB098\uC694. \uACE0\uB9C8\uC6E0\uC5B4\uC694, \uBCF4\uC2A4.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uBC14\uB78C\uC774 \uBD88\uC5B4 \uC720\uD2F0\uC758 \uBA38\uB9AC\uCE7C\uC774 \uD769\uB0A0\uB9B0\uB2E4. \uC720\uD2F0\uB294 \uC2DC\uC120\uC744 \uD53C\uD558\uC9C0 \uC54A\uACE0, \uBCC4\uC774 \uB9CE\uC740 \uD558\uB298\uC744 \uC5F0\uAD6C\uC6D0\uACFC \uD568\uAED8 \uC62C\uB824\uB2E4\uBCF8\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "\uC720\uD2F0", body: "\uC815\uBA74\uC5D0 \uC11C \uBCF4\uB2C8\uAE4C\uC694, \uC0DD\uAC01\uBCF4\uB2E4 \uBB34\uC12D\uC9C0 \uC54A\uC544\uC694. \uBCF4\uC2A4\uAC00 \uC11C \uC788\uB294 \uCABD\uC774\uB77C\uC11C \uADF8\uB7F0\uAC00 \uBD10\uC694. \uB2E4\uB978 \uC0AC\uB78C \uC55E\uC740 \uC544\uC9C1 \uBAA8\uB974\uACA0\uC9C0\uB9CC\uC694.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uACC4\uB2E8 \uC544\uB798\uC5D0\uC11C \uBC1C\uC18C\uB9AC\uAC00 \uB4E4\uB9B0\uB2E4. \uD30C\uCE58\uC640 \uC544\uD06C\uAC00 \uAC04\uC2DD \uBD09\uC9C0\uB97C \uB4E4\uACE0 \uC62C\uB77C\uC624\uACE0 \uC788\uB2E4. \uC720\uD2F0\uAC00 \uBC18 \uAC78\uC74C \uB4A4\uB85C \uBB3C\uB7EC\uC11C\uB824\uB2E4\uAC00 \uBA48\uCD94\uACE0 \uC81C\uC790\uB9AC\uC5D0 \uC120\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uC720\uD2F0", body: "\uBCF4\uC2A4. \uC624\uB298\uC740 \uC228\uC9C0 \uC54A\uC744\uAC8C\uC694. \uC606\uC5D0\uC11C\uB3C4 \uC815\uBA74\uC5D0\uC11C\uB3C4 \uC11C \uBCFC\uAC8C\uC694. \uC5B4\uB290 \uCABD\uC774\uB4E0 \uC81C\uAC00 \uC788\uB294 \uACF3\uC774\uC5D0\uC694\u2026 \uB9DE\uC8E0?" }
  ]
};
var YUTI_STORY = {
  relicId: "yuti",
  fossilRecord: "\uD654\uC0B0\uC7AC\uAC00 \uAD73\uC740 \uC751\uD68C\uC554\uD310 \uC704\uC5D0 \uBAB8\uC744 \uB36E\uC740 \uAE43\uD138\uC758 \uC778\uC0C1\uC774 \uBF08\uC640 \uD568\uAED8 \uB0A8\uC544 \uC788\uC5C8\uB2E4. \uAC19\uC740 \uCE35\uC758 \uB2E4\uB978 \uAC1C\uCCB4\uBCF4\uB2E4 \uD6E8\uC52C \uD070 \uBAB8\uC9D1\uC774 \uD55C \uC7A5\uC758 \uD310\uC5D0 \uC811\uD600 \uB4E4\uC5B4\uAC04 \uCC44 \uB098\uC654\uACE0, \uBCF5\uC6D0 \uC5F0\uAD6C\uB294 \uADF8 \uAE43\uD138\uC774 \uC5B4\uB514\uAE4C\uC9C0 \uBAB8\uC744 \uAC10\uC30C\uB294\uC9C0\uB97C \uC7AC\uB294 \uC77C\uBD80\uD130 \uC2DC\uC791\uD588\uB2E4.",
  diary: "\uBCF5\uC6D0 \uD6C4 \uC720\uD2F0\uB294 \uD070 \uC18C\uB9AC\uB97C \uB0B4\uC9C0 \uC54A\uACE0\uB3C4 \uBCF5\uB3C4 \uB05D\uC5D0\uC11C \uB05D\uAE4C\uC9C0 \uC0AC\uB78C\uB4E4 \uC0AC\uC774\uB97C \uBE60\uC838\uB098\uAC04\uB2E4. \uBAA8\uB450\uAC00 \uC815\uBA74\uC744 \uBCF4\uACE0 \uC788\uC744 \uB54C \uC5B4\uB290\uC0C8 \uC606\uC790\uB9AC\uC5D0 \uC640 \uC788\uB2E4\uAC00, \uB208\uC774 \uB9C8\uC8FC\uCE58\uBA74 \uC790\uAE30\uAC00 \uD55C \uC77C\uC774 \uC544\uB2CC \uCC99 \uC2DC\uC120\uC744 \uB3CC\uB9AC\uB294 \uBC84\uB987\uC774 \uAD00\uCC30\uB410\uB2E4. \uD654\uB824\uD55C \uC120\uBC30\uB4E4\uC744 \uD749\uB0B4 \uB0B4 \uD638\uCE6D\uC744 \uC4F0\uBA74\uC11C\uB3C4 \uC5B4\uC0C9\uD55C\uC9C0 \uB9E4\uBC88 \uB9D0\uB05D\uC744 \uD750\uB9B0\uB2E4.",
  /** 일지 맨 끝에 회색으로 서는, 유티가 연구원에게 건네는 한마디. 뽑기 대사와 다른 일상의 목소리다. */
  closingLine: "\u2026\u2026\uBCF4\uC2A4, \uBC29\uAE08 \uC9C0\uB098\uAC04 \uAC70 \uC800\uC608\uC694. \uC778\uC0AC\uD558\uB824\uACE0 \uD588\uB294\uB370\u2026 \uC9C0\uB098\uAC00 \uBC84\uB838\uC5B4\uC694. \uB2E4\uC74C\uC5D4 \uAF2D\uC774\uC694.",
  questions: [
    {
      id: "yuti-feather",
      prompt: "\uC720\uD2F0\uB294 \uB3C4\uC640\uC8FC\uACE0 \uB098\uBA74 \uC65C \uC790\uB9AC\uB97C \uB5A0?",
      choices: [
        {
          id: "gift",
          label: "\uACE0\uB9D9\uB2E4\uACE0 \uD558\uBA74 \uBD88\uD3B8\uD558\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uBD88\uD3B8\uD558\uB2E4\uAE30\uBCF4\uB2E4\u2026 \uC5B4\uB5BB\uAC8C \uB300\uB2F5\uD574\uC57C \uD560\uC9C0 \uBAB0\uB77C\uC11C\uC694. \u300C\uCC9C\uB9CC\uC5D0\uC694\u300D \uD558\uACE0 \uB098\uBA74 \uADF8\uB2E4\uC74C\uC5D0 \uD560 \uB9D0\uC774 \uC5C6\uC5B4\uC694, \uBCF4\uC2A4.",
          note: "\uACE0\uB9D9\uB2E4\uB294 \uB9D0\uC774 \uBD88\uD3B8\uD558\uB0D0\uACE0 \uBB3B\uC790 \uC5B4\uB5BB\uAC8C \uB300\uB2F5\uD560\uC9C0 \uBAB0\uB77C\uC11C\uB77C\uACE0 \uD588\uB2E4. \uADF8\uB2E4\uC74C\uC5D0 \uD560 \uB9D0\uC774 \uC5C6\uB2E4\uACE0 \uB367\uBD99\uC600\uB2E4."
        },
        {
          id: "hurt",
          label: "\uB3C4\uC6B4 \uC0AC\uB78C\uC774 \uB204\uAD70\uC9C0 \uC548 \uBC1D\uD600\uB3C4 \uB418\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC54C\uB824\uC9C0\uBA74 \uB2E4\uC74C\uC5D0 \uB3C4\uC640\uB4DC\uB9AC\uAE30\uAC00 \uC5B4\uC0C9\uD574\uC9C8 \uAC83 \uAC19\uC544\uC11C\uC694. \uBAA8\uB974\uB294 \uCC44\uB85C \uB450\uB294 \uAC8C \uC800\uB294 \uB354 \uD3B8\uD574\uC694.",
          note: "\uC548 \uBC1D\uD600\uB3C4 \uB418\uB0D0\uACE0 \uBB3B\uC790 \uC54C\uB824\uC9C0\uBA74 \uB2E4\uC74C\uC5D0 \uC5B4\uC0C9\uD574\uC9C8 \uAC83 \uAC19\uB2E4\uACE0 \uB2F5\uD588\uB2E4."
        },
        {
          id: "why",
          label: "\uD3B8\uD55C \uB300\uB85C \uD558\uB77C\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\u2026\u2026\uB124. \uADF8\uB807\uAC8C \uB9D0\uD574 \uC8FC\uC2DC\uB2C8\uAE4C \uC870\uAE08 \uD3B8\uD574\uC694, \uBCF4\uC2A4. \uADF8\uB798\uB3C4 \uAC00\uB054\uC740 \uB4E4\uCF1C\uB3C4 \uAD1C\uCC2E\uC744 \uAC83 \uAC19\uC544\uC694.",
          note: "\uD3B8\uD55C \uB300\uB85C \uD558\uB77C\uACE0 \uD558\uC790 \uC870\uAE08 \uD3B8\uD574\uC84C\uB2E4\uACE0 \uD588\uB2E4. \uAC00\uB054\uC740 \uB4E4\uCF1C\uB3C4 \uAD1C\uCC2E\uC744 \uAC83 \uAC19\uB2E4\uACE0 \uB367\uBD99\uC600\uB2E4."
        }
      ]
    },
    {
      id: "yuti-side",
      prompt: "\uC720\uD2F0\uB294 \uC65C \uD56D\uC0C1 \uC606\uC774\uB098 \uB4A4\uC5D0\uC11C \uB098\uD0C0\uB098?",
      choices: [
        {
          id: "front",
          label: "\uC815\uBA74\uC740 \uBB34\uC12D\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uBB34\uC12D\uB2E4\uAE30\uBCF4\uB2E4\u2026 \uB208\uC774 \uD55C\uAEBC\uBC88\uC5D0 \uC624\uB294 \uAC8C \uC5B4\uB824\uC6CC\uC694. \uC606\uC5D0\uC11C \uAC00\uBA74 \uD55C \uBA85\uC529\uB9CC \uB9CC\uB098\uB294 \uAC83 \uAC19\uAC70\uB4E0\uC694.",
          note: "\uC815\uBA74\uC774 \uBB34\uC12D\uB0D0\uACE0 \uBB3B\uC790 \uB208\uC774 \uD55C\uAEBC\uBC88\uC5D0 \uC624\uB294 \uAC8C \uC5B4\uB835\uB2E4\uACE0 \uD588\uB2E4. \uC606\uC5D0\uC11C\uB294 \uD55C \uBA85\uC529 \uB9CC\uB098\uB294 \uAC83 \uAC19\uB2E4\uACE0 \uD588\uB2E4."
        },
        {
          id: "quiet",
          label: "\uC870\uC6A9\uD788 \uB2E4\uB2C8\uB294 \uAC8C \uD3B8\uD558\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uD3B8\uD574\uC694. \uC18C\uB9AC\uAC00 \uB098\uC9C0 \uC54A\uC73C\uBA74 \uB204\uAC00 \uB180\uB77C\uC9C0\uB3C4 \uC54A\uACE0\uC694. \uADF8\uB798\uC11C \uBC1C\uAC78\uC74C\uB3C4 \uC77C\uBD80\uB7EC \uAC00\uBCCD\uAC8C \uAC77\uB294 \uC5F0\uC2B5\uC744 \uD588\uC5B4\uC694.",
          note: "\uC870\uC6A9\uD788 \uB2E4\uB2C8\uB294 \uAC8C \uD3B8\uD558\uB0D0\uACE0 \uBB3B\uC790 \uBC1C\uAC78\uC74C \uC5F0\uC2B5\uAE4C\uC9C0 \uD588\uB2E4\uACE0 \uD138\uC5B4\uB1A8\uB2E4."
        },
        {
          id: "try",
          label: "\uC815\uBA74\uC5D0\uB3C4 \uD55C\uBC88 \uC11C \uBCF4\uBA74 \uC88B\uACA0\uB2E4\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\uC815\uBA74\uC774\uC694\u2026? \uBCF4\uC2A4 \uC55E\uC774\uB77C\uBA74\u2026 \uC5B8\uC820\uAC00\uB294\uC694. \uC624\uB298\uC740 \uC544\uB2C8\uACE0\uC694. \uC544, \uC624\uB298 \uB9D0\uACE0 \uC5B8\uC820\uAC00 \uAF2D\uC774\uC694.",
          note: "\uC815\uBA74\uC5D0 \uC11C \uBCF4\uB77C\uACE0 \uD558\uC790 \uC624\uB298\uC740 \uC544\uB2C8\uB77C\uACE0 \uD588\uB2E4. \uC5B8\uC820\uAC00\uB294 \uAF2D\uC774\uB77C\uACE0 \uB450 \uBC88 \uB9D0\uD588\uB2E4."
        }
      ]
    },
    {
      id: "yuti-title",
      prompt: "\uC720\uD2F0\uB294 \uC65C \u300C\uBCF4\uC2A4\u300D\uB77C\uACE0 \uBD80\uB97C \uB54C \uB9D0\uB05D\uC744 \uD750\uB824?",
      choices: [
        {
          id: "awkward",
          label: "\uD638\uCE6D\uC774 \uC5B4\uC0C9\uD558\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC5B4\uC0C9\uD574\uC694\u2026 \uC120\uBC30\uB4E4\uC774 \uC4F0\uC2DC\uB294 \uAC78 \uB530\uB77C \uD55C \uAC70\uB77C\uC11C\uC694. \uADFC\uB370 \uC774\uC81C\uB294 \uC81C \uC785\uC5D0 \uC870\uAE08 \uBD99\uC740 \uAC83 \uAC19\uAE30\uB3C4 \uD574\uC694.",
          note: "\uD638\uCE6D\uC774 \uC5B4\uC0C9\uD558\uB0D0\uACE0 \uBB3B\uC790 \uB530\uB77C \uD55C \uB9D0\uC774\uB77C\uACE0 \uC778\uC815\uD588\uB2E4. \uC870\uAE08\uC740 \uC785\uC5D0 \uBD99\uC5C8\uB2E4\uACE0\uB3C4 \uD588\uB2E4."
        },
        {
          id: "change",
          label: "\uB2E4\uB978 \uD638\uCE6D\uC744 \uC368\uB3C4 \uB41C\uB2E4\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\uB2E4\uB978 \uD638\uCE6D\uC774\uC694\u2026? \uC544\uB2C8\uC5D0\uC694, \uC774\uB300\uB85C\uAC00 \uC88B\uC544\uC694. \uC5B4\uC0C9\uD55C \uCC44\uB85C \uBD80\uB974\uB294 \uAC8C \uC81C \uBC29\uC2DD \uAC19\uC544\uC11C\uC694. \uADF8\uB798\uB3C4 \uB9D0\uD574 \uC8FC\uC154\uC11C \uACE0\uB9C8\uC6CC\uC694.",
          note: "\uB2E4\uB978 \uD638\uCE6D\uC744 \uC368\uB3C4 \uB41C\uB2E4\uACE0 \uD558\uC790 \uC774\uB300\uB85C\uAC00 \uC88B\uB2E4\uACE0 \uD588\uB2E4. \uC5B4\uC0C9\uD55C \uCC44\uB85C \uBD80\uB974\uB294 \uAC8C \uC790\uAE30 \uBC29\uC2DD\uC774\uB77C\uACE0 \uB9D0\uD588\uB2E4."
        },
        {
          id: "like",
          label: "\uADF8 \uD638\uCE6D\uC774 \uB9C8\uC74C\uC5D0 \uB4E0\uB2E4\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\uC815\uB9D0\uC694\u2026? \uADF8\uB7FC \uACC4\uC18D \uC4F8\uAC8C\uC694. \uB9D0\uB05D\uC740 \uD750\uB824\uC838\uB3C4\uC694. \uBCF4\uC2A4\uB77C\uB294 \uB9D0\uC774 \uB9C8\uC2A4\uD130\uBCF4\uB2E4 \uC870\uAE08 \uAC00\uBCBC\uC6CC\uC11C \uC88B\uC544\uC694.",
          note: "\uB9C8\uC74C\uC5D0 \uB4E0\uB2E4\uACE0 \uD558\uC790 \uACC4\uC18D \uC4F0\uACA0\uB2E4\uACE0 \uD588\uB2E4. \uB9D0\uB05D\uC774 \uD750\uB824\uC838\uB3C4 \uAD1C\uCC2E\uB2E4\uACE0 \uB367\uBD99\uC600\uB2E4."
        }
      ]
    }
  ],
  bondStories: { 4: CHAPTER_418, 6: CHAPTER_618, 8: CHAPTER_818, 10: CHAPTER_1018 },
  bondLines: [
    // 0 — 낯선 사이. 한 걸음 옆에서 바라본다.
    ["\u2026\u2026\uC544. \uCC98\uC74C \uBD59\uACA0\uC5B4\uC694. \uC720\uD2F0\uC608\uC694. \uC544\uAE4C\uBD80\uD130 \uC606\uC5D0 \uC788\uC5C8\uB294\uB370\u2026 \uBABB \uBCF4\uC168\uC8E0? \uAD1C\uCC2E\uC544\uC694, \uBCF4\uC2A4.", "\uBCF4\uC2A4\uB77C\uACE0 \uBD88\uB7EC\uB3C4 \uB418\uB098\uC694? \uB9D0\uB05D\uC774 \uD750\uB824\uC838\uB3C4 \uC774\uD574\uD574 \uC8FC\uC138\uC694. \uC785\uC5D0 \uC544\uC9C1 \uC548 \uBD99\uC5B4\uC11C\uC694.", "\uC800\uB294 \uC815\uBA74\uBCF4\uB2E4 \uC606\uC790\uB9AC\uAC00 \uD3B8\uD574\uC694. \uAC70\uAE30 \uC788\uC5B4\uB3C4 \uB418\uC8E0\u2026?"],
    // 1
    ["\uC624\uB298\uC740 \uBCF5\uB3C4\uC5D0\uC11C \uC5F4 \uAC78\uC74C\uCBE4 \uC55E\uAE4C\uC9C0 \uAC14\uB2E4\uAC00 \uB418\uB3CC\uC544\uC654\uC5B4\uC694. \u2026\uC544, \uC544\uB2C8\uC5D0\uC694. \uC544\uBB34\uAC83\uB3C4 \uC544\uB2C8\uC5D0\uC694.", "\uBCF5\uB3C4\uC5D0\uC11C \uC544\uBB34\uD55C\uD14C\uB3C4 \uC548 \uB4E4\uD0A4\uACE0 \uB05D\uAE4C\uC9C0 \uAC14\uC5B4\uC694. \uC774\uB7F0 \uAC74 \uC798\uD574\uC694, \uBCF4\uC2A4. \uC798\uD558\uB294 \uAC8C \uC774\uAC83\uBFD0\uC774\uAE34 \uD558\uC9C0\uB9CC\uC694.", "\uC815\uBA74\uC5D0 \uC11C\uB294 \uC77C\uC774 \uC788\uC73C\uBA74 \uBBF8\uB9AC \uB9D0\uD574 \uC8FC\uC138\uC694. \uB9C8\uC74C\uC758 \uC900\uBE44\uAC00 \uD544\uC694\uD574\uC11C\uC694."],
    // 2
    ["\uD68C\uC758 \uB54C \uBCF4\uC2A4 \uC624\uB978\uCABD \uC790\uB9AC\uAC00 \uBE44\uC5B4 \uC788\uC5B4\uC11C \uC549\uC558\uC5B4\uC694. \uD5C8\uB77D \uC548 \uBC1B\uC558\uC9C0\uB9CC\u2026 \uC549\uC544\uB3C4 \uB418\uB294 \uC790\uB9AC\uC778 \uAC83 \uAC19\uC544\uC11C\uC694.", "\uC624\uB298 \uBE44\uAC00 \uC640\uC11C \uBCF5\uB3C4\uAC00 \uC870\uC6A9\uD588\uC5B4\uC694. \uC774\uB7F0 \uB0A0 \uAC77\uB294 \uAC70 \uC88B\uC544\uD574\uC694, \uBCF4\uC2A4.", "\uBCF4\uC2A4\uB294 \uCC28 \uB9C8\uC2E4 \uB54C \uC124\uD0D5 \uB123\uC73C\uC138\uC694? \u2026\uC544, \uADF8\uB0E5 \uAD81\uAE08\uD574\uC11C\uC694. \uB300\uB2F5 \uC548 \uD558\uC154\uB3C4 \uB3FC\uC694."],
    // 3
    ["\uD30C\uCE58\uAC00 \uAC00\uC6B4\uB370\uB85C \uAC78\uC73C\uB77C\uACE0 \uD588\uC5B4\uC694. \uAC00\uC6B4\uB370\uB294 \uC544\uC9C1 \uC548 \uB3FC\uC694. \uADF8\uB798\uB3C4 \uD55C \uBC88\uCBE4\uC740 \uAC00 \uBCF4\uACE0 \uC2F6\uC5B4\uC694.", "\uB3C4\uB514\uAC00 \uC0C1\uC790 \uC62E\uAE30\uB294 \uAC78 \uAC19\uC774 \uB4E4\uC5C8\uC5B4\uC694. \uACE0\uB9D9\uB2E4\uACE0 \uD558\uB354\uB77C\uACE0\uC694. \uB204\uAD70\uC9C0\uB294 \uBAA8\uB974\uACE0\uC694. \uAE30\uBEE4\uC5B4\uC694, \uBCF4\uC2A4.", "\uC791\uC740 \uC18C\uB9AC\uB294 \uC798 \uB4E4\uB824\uC694. \uADF8\uB798\uC11C \uBCF4\uC2A4 \uBC1C\uC18C\uB9AC\uB3C4 \uBA40\uB9AC\uC11C\uBD80\uD130 \uC54C\uC544\uC694."],
    // 4 — 장 4 이후: 옆자리에서 나타난 날 이후.
    ["\uD68C\uC758 \uB54C \uC606\uC790\uB9AC\uC5D0 \uC549\uC740 \uAC70, \uAE30\uC5B5\uD558\uC138\uC694? \uC544\uB2C8, \uBAA8\uB974\uB294 \uCC99\uD574 \uC8FC\uC138\uC694. \uADFC\uB370 \uAE30\uC5B5\uD558\uACE0 \uACC4\uC2DC\uBA74 \uAE30\uBED0\uC694\u2026", "\uBCBD\uC73C\uB85C \uB2E4\uB2C8\uB294 \uAC78 \uD30C\uCE58\uD55C\uD14C \uB4E4\uCF30\uC5B4\uC694. \uC774\uC720\uB97C \uB9D0\uD588\uB294\uB370 \uBE44\uC6C3\uC9C0 \uC54A\uC558\uC5B4\uC694. \uACE0\uB9C8\uC6E0\uC5B4\uC694.", "\uC815\uBA74\uC740 \uC544\uC9C1 \uC81C \uC790\uB9AC\uAC00 \uC544\uB2CC \uAC83 \uAC19\uC544\uC694. \uADF8\uCE58\uB9CC \uC790\uB9AC\uB97C \uB9CC\uB4E4\uC5B4 \uAC00\uB294 \uC911\uC774\uC5D0\uC694, \uBCF4\uC2A4."],
    // 5
    ["\uC624\uB298\uC740 \uC0AC\uB78C\uB4E4 \uC0AC\uC774\uB85C \uAC78\uC5B4\uAC00\uB294\uB370 \uD55C \uBA85\uC774 \uC800\uB97C \uC54C\uC544\uBD24\uC5B4\uC694. \uB180\uB790\uC9C0\uB9CC \uB3C4\uB9DD\uCE58\uC9C0 \uC54A\uC558\uC5B4\uC694.", "\uC0AC\uB78C\uB4E4 \uC0AC\uC774\uB97C \uAC78\uC73C\uBA74 \uC544\uC9C1 \uC228\uC774 \uCC28\uC694. \uADF8\uB798\uB3C4 \uC5B4\uC81C\uBCF4\uB2E4\uB294 \uD55C \uCE78 \uB354 \uAC14\uC5B4\uC694.", "\uB204\uAC00 \uC81C \uC774\uB984\uC744 \uBD88\uB7EC \uC8FC\uBA74 \uADC0\uAC00 \uBA3C\uC800 \uBC18\uC751\uD574\uC694. \uBAB8\uC740 \uCC9C\uCC9C\uD788 \uB530\uB77C\uAC00\uACE0\uC694."],
    // 6 — 장 6 이후: 건넨 걸 모른 척하는 법 이후.
    ["\uB3C4\uB514\uAC00 \uC0C1\uC790 \uC598\uAE30\uB97C \uD558\uB294 \uAC78 \uB098\uBB34 \uB4A4\uC5D0\uC11C \uB4E4\uC5C8\uC5B4\uC694. \uAE30\uBED0 \uBCF4\uC774\uB294 \uAC8C \uC81C\uC77C \uC88B\uC740 \uB300\uB2F5\uC774\uC5D0\uC694.", "\uC544\uB294 \uC0AC\uB78C\uC774 \uD55C \uBA85\uCBE4\uC740 \uC788\uC5B4\uB3C4 \uAD1C\uCC2E\uACA0\uB2E4\uACE0 \uC0DD\uAC01\uD588\uC5B4\uC694, \uBCF4\uC2A4. \uADF8\uAC8C \uBCF4\uC2A4\uB77C\uC11C \uB2E4\uD589\uC774\uC5D0\uC694.", "\uB204\uAC00 \uD588\uB294\uC9C0 \uBAB0\uB77C\uB3C4 \uB418\uB294 \uAC74 \uC815\uB9D0 \uD3B8\uD574\uC694. \uC81C\uAC00 \uD3B8\uD55C \uBC29\uC2DD\uC73C\uB85C \uB3D5\uB294 \uAC70\uB77C\uC11C\uC694."],
    // 7
    ["\uAC70\uC6B8 \uC55E\uC5D0\uC11C \uC778\uC0AC\uB97C \uC5F0\uC2B5\uD588\uC5B4\uC694. \uB204\uAC00 \uBCF4\uBA74 \uBD80\uB044\uB7EC\uC6B4\uB370 \uBCF4\uC2A4\uB294 \uAD1C\uCC2E\uC544\uC694. \uC774\uC0C1\uD558\uC8E0\u2026", "\uBCF5\uB3C4\uC5D0\uC11C \uB204\uAC00 \uC6C3\uACE0 \uC788\uAE38\uB798 \uD55C\uCC38 \uC11C\uC11C \uB4E4\uC5C8\uC5B4\uC694. \uB4E3\uAE30\uB9CC \uD588\uB294\uB370 \uAE30\uBD84\uC774 \uC88B\uC544\uC84C\uC5B4\uC694.", "\uB9D0\uB05D\uC774 \uD750\uB824\uC838\uB3C4 \uAD1C\uCC2E\uB2E4\uACE0 \uD574 \uC8FC\uC168\uC5B4\uC694. \uADF8 \uB9D0\uC774 \uC624\uB298 \uD558\uB8E8 \uC885\uC77C \uB530\uB77C\uB2E4\uB154\uC5B4\uC694."],
    // 8 — 장 8 이후: 선배들 흉내 이후.
    ["\uC544\uD06C\uB791 \uB4F1 \uB3CC\uB9AC\uACE0 \uC778\uC0AC \uC5F0\uC2B5\uC744 \uD588\uC5B4\uC694. \uC11C\uB85C \uBABB \uBCF4\uB2C8\uAE4C \uB5A8\uB9AC\uB294 \uAC8C \uB35C\uD588\uC5B4\uC694. \uB458\uC774 \uD558\uBA74 \uC88B\uB354\uB77C\uACE0\uC694.", "\uC800\uB9CC\uC758 \uBAA9\uC18C\uB9AC\uB85C \u300C\uBCF4\uC2A4\u300D\uB77C\uACE0 \uBD80\uB974\uB294 \uAC70, \uC774\uC81C \uC870\uAE08\uC740 \uD3B8\uD574\uC84C\uC5B4\uC694. \uC815\uB9D0 \uC870\uAE08\uC774\uC694.", "\uC624\uB298\uC740 \uCC98\uC74C\uC73C\uB85C \uBA3C\uC800 \uC190\uC744 \uD754\uB4E4\uC5B4 \uBD24\uC5B4\uC694. \uC0C1\uB300\uAC00 \uBABB \uBD24\uC9C0\uB9CC\uC694\u2026 \uAD1C\uCC2E\uC544\uC694."],
    // 9
    ["\uC624\uB298\uC740 \uC815\uBA74 \uD1B5\uB85C\uB85C \uBC18\uCBE4 \uAC78\uC5B4 \uBD24\uC5B4\uC694. \uBC18\uCBE4\uC774\uC694. \uB098\uBA38\uC9C0 \uBC18\uC740 \uBCBD\uC744 \uB530\uB77C\uC11C\uC694.", "\uBCF4\uC2A4\uAC00 \uC55E\uC5D0 \uC11C \uC788\uC73C\uBA74 \uC2DC\uC120\uC774 \uD55C \uACF3\uC73C\uB85C \uBAA8\uC5EC\uC11C \uB35C \uBB34\uC11C\uC6CC\uC694. \uADF8\uAC78 \uC54C\uACE0 \uB098\uB2C8\uAE4C \uC880 \uD3B8\uD574\uC694.", "\uC624\uB298 \uC544\uCE68\uC5D4 \uCC3D\uAC00 \uC790\uB9AC\uAC00 \uBE44\uC5B4 \uC788\uC5C8\uC5B4\uC694. \uBCF4\uC2A4, \uAC19\uC774 \uC549\uC744\uB798\uC694?"],
    // 10 — 마음을 연 사이. 정면에 서 보는 밤 이후.
    ["\uC815\uBA74\uC5D0\uC11C \uB9D0\uC500\uB4DC\uB838\uC744 \uB54C \uC190\uC774 \uB5A8\uB838\uC5B4\uC694. \uADF8\uB798\uB3C4 \uB05D\uAE4C\uC9C0 \uD588\uC5B4\uC694. \uADF8\uAC8C \uC81C \uCCAB \uBC88\uC9F8 \uC6A9\uAE30\uC600\uC5B4\uC694, \uBCF4\uC2A4.", "\uBCF4\uC2A4, \uC624\uB298\uC740 \uC81C\uAC00 \uBA3C\uC800 \uB9D0 \uAC78\uC5B4\uB3C4 \uB420\uAE4C\uC694? \u2026\uC544, \uC774\uBBF8 \uAC78\uC5C8\uB124\uC694.", "\uBCF4\uC2A4, \uC9C0\uB098\uAC00\uB2E4 \uB9C8\uC8FC\uCE58\uBA74 \uC774\uC81C \uC778\uC0AC\uAC00 \uBA3C\uC800 \uB098\uC640\uC694. \uC800\uB3C4 \uC880 \uB180\uB790\uC5B4\uC694."]
  ]
};

