var CHAPTER_423 = {
  id: "bond.luka.4",
  startNodeId: "n1",
  titleCard: { title: "\uC18C\uD30C \uB2E4\uC74C\uC73C\uB85C", subtitle: "\uB8E8\uCE74 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 1" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC624\uD6C4\uC758 \uC5F0\uAD6C\uC18C \uD734\uAC8C\uC2E4. \uC18C\uD30C \uD558\uB098\uB97C \uD1B5\uC9F8\uB85C \uCC28\uC9C0\uD55C \uB8E8\uCE74\uAC00 \uD6C4\uB4DC\uB97C \uB4A4\uC9D1\uC5B4\uC4F4 \uCC44 \uAE38\uAC8C \uB204\uC6CC \uC788\uB2E4. \uC5F0\uAD6C\uC6D0\uC774 \uC11C\uB958\uB97C \uD55C \uC544\uB984 \uC548\uACE0 \uC9C0\uB098\uAC00\uC790 \uD6C4\uB4DC \uC18D\uC5D0\uC11C \uB208\uC774 \uBC18\uCBE4 \uB5A0\uC9C4\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uB8E8\uCE74", body: "\uC5B4, \uC5F0\uAD6C\uC6D0\uB2D8. \uBC14\uBE60 \uBCF4\uC774\uB124. \uB2EC\uB9AC\uB294 \uAC74 \uC790\uC2E0 \uC788\uC5B4. \uC18C\uD30C \uB2E4\uC74C\uC73C\uB85C. \uADF8\uB7EC\uB2C8\uAE4C \uBB50 \uAE09\uD55C \uC2EC\uBD80\uB984 \uC788\uC73C\uBA74 \uB9D0\uD574.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uB8E8\uCE74\uAC00 \uAF2C\uB9AC\uB85C \uC18C\uD30C \uAC00\uC7A5\uC790\uB9AC\uB97C \uD1A1\uD1A1 \uB450\uB4DC\uB9B0\uB2E4. \uD55C\uCABD \uC790\uB9AC\uB97C \uBE44\uC6CC \uB450\uACA0\uB2E4\uB294 \uC2E0\uD638\uB2E4. \uADF8 \uC606\uC5D0 \uB3C4\uB514\uAC00 \uC774\uBBF8 \uC9C0\uCCD0\uC11C \uC4F0\uB7EC\uC838 \uC788\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uB3C4\uB514", body: "\uB8E8\uCE74\uAC00 \uC2EC\uBD80\uB984\uC774\uB77C\uACE0 \uD558\uBA74 \uC2EC\uBD80\uB984\uC774 \uC21C\uC2DD\uAC04\uC5D0 \uB05D\uB098. \uADFC\uB370 \uB05D\uB098\uACE0 \uB098\uBA74 \uC18C\uD30C \uC55E\uC5D0\uC11C \uC548 \uB098\uC640.", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uC11C\uB958\uB97C \uAD00\uC81C\uC2E4\uAE4C\uC9C0 \uC804\uD574\uC57C \uD558\uB294 \uCC38\uC774\uB2E4. \uB8E8\uCE74\uAC00 \uD6C4\uB4DC \uC18D\uC5D0\uC11C \uC2AC\uCA4D \uC62C\uB824\uB2E4\uBCF8\uB2E4.)", choices: [
      { id: "ask", label: "\uC11C\uB958 \uC804\uB2EC\uC744 \uBD80\uD0C1\uD55C\uB2E4", nextId: "n6a" },
      { id: "sit", label: "\uC7A0\uAE50 \uC18C\uD30C \uC606\uC790\uB9AC\uC5D0 \uC549\uC544 \uC270\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uB8E8\uCE74", body: "\uC88B\uC544, \uB9E1\uACA8. \uC774\uC2ED \uCD08\uBA74 \uB3FC. \uB2E4\uB140\uC640\uC11C \uC18C\uD30C\uB294 \uADF8\uB300\uB85C \uC788\uB294 \uAC70\uC9C0?", nextId: "n7" },
    { id: "n6b", speaker: "\uB8E8\uCE74", body: "\uC624, \uC549\uC558\uB2E4. \uC5F0\uAD6C\uC6D0\uB2D8 \uC880 \uBCF4\uB294 \uB208\uC774 \uC788\uB124. \uC26C\uB294 \uAC83\uB3C4 \uC77C\uC774\uC57C. \uC81C\uC77C \uC911\uC694\uD55C \uC77C\uC774\uC9C0.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uB8E8\uCE74\uAC00 \uC790\uB9AC\uC5D0\uC11C \uC77C\uC5B4\uB098\uB294 \uC21C\uAC04 \uD6C4\uB4DC\uAC00 \uD719 \uC816\uD600\uC9C4\uB2E4. \uB2E4\uC74C \uC21C\uAC04 \uBCF5\uB3C4 \uB05D\uC5D0\uC11C \uBC14\uB78C \uC18C\uB9AC\uB9CC \uB0A8\uAE30\uACE0 \uC0AC\uB77C\uC9C4\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "", body: "\uC815\uB9D0\uB85C \uC774\uC2ED \uCD08 \uB4A4, \uB8E8\uCE74\uAC00 \uAC19\uC740 \uC18D\uB3C4\uB85C \uB3CC\uC544\uC640 \uC18C\uD30C\uC5D0 \uD138\uC369 \uC4F0\uB7EC\uC9C4\uB2E4. \uC228\uC18C\uB9AC\uB3C4 \uAC70\uC758 \uD750\uD2B8\uB7EC\uC9C0\uC9C0 \uC54A\uC558\uB2E4.", nextId: "n9" },
    { id: "n9", speaker: "\uB8E8\uCE74", body: "\uB2E4\uB140\uC654\uC5B4. \uC774\uC81C \uC274 \uCC28\uB840\uC57C. \uB2EC\uB9AC\uB294 \uAC74 \uC9E7\uAC8C, \uC26C\uB294 \uAC74 \uAE38\uAC8C. \uADF8\uAC8C \uB0B4 \uBC29\uC2DD\uC774\uC57C.", nextId: "n10" },
    { id: "n10", speaker: "\uB8E8\uCE74", body: "\uC5F0\uAD6C\uC6D0\uB2D8\uB3C4 \uC774\uB807\uAC8C \uD574 \uBD10. \uB6F0\uB294 \uB9CC\uD07C \uB215\uB294 \uAC70\uC57C. \uC0AC\uC2E4 \uB215\uB294 \uCABD\uC774 \uBE44\uC728\uC774 \uB354 \uB192\uC544\uB3C4 \uB3FC." }
  ]
};
var CHAPTER_623 = {
  id: "bond.luka.6",
  startNodeId: "n1",
  titleCard: { title: "\uCE58\uC988\uCF00\uC774\uD06C \uD55C \uC785 \uB354", subtitle: "\uB8E8\uCE74 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 2" },
  nodes: [
    { id: "n1", speaker: "", body: "\uAC04\uC2DD \uC2DC\uAC04\uC758 \uD734\uAC8C\uC2E4. \uD0C1\uC790 \uC704\uC5D0 \uCE58\uC988\uCF00\uC774\uD06C \uD55C \uD310\uC774 \uB193\uC5EC \uC788\uB2E4. \uB8E8\uCE74\uAC00 \uD3EC\uD06C\uB97C \uB4E0 \uCC44 \uB208\uC744 \uAC00\uB298\uAC8C \uB728\uACE0 \uCF00\uC774\uD06C\uB97C \uB178\uB824\uBCF8\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uB8E8\uCE74", body: "\u2026\uD55C \uC870\uAC01 \uBA39\uC73C\uBA74 \uB2EC\uB9AC\uAE30\uAC00 \uB454\uD574\uC9C8\uAE4C? \uADF8\uCE58? \uC544\uB2C8, \uC544\uB2C8\uC57C. \uD55C \uC870\uAC01\uCBE4\uC740 \uAD1C\uCC2E\uC544. \uC5B4\uCC28\uD53C \uB0B4\uC77C \uB6F0\uBA74 \uB418\uB2C8\uAE4C.", nextId: "n3" },
    { id: "n3", speaker: "\uB3C4\uB514", body: "\uB8E8\uCE74, \uBC8C\uC368 \uC138 \uBC88\uC9F8 \uC870\uAC01\uC774\uC57C. \uB2EC\uB9AC\uAE30 \uAC71\uC815\uC740 \uC5B4\uB514 \uAC14\uC5B4?", nextId: "n4" },
    { id: "n4", speaker: "", body: "\uB8E8\uCE74\uC758 \uD3EC\uD06C\uAC00 \uD5C8\uACF5\uC5D0\uC11C \uBA48\uCD98\uB2E4. \uAF2C\uB9AC\uAC00 \uC18C\uD30C \uB05D\uC5D0\uC11C \uCC9C\uCC9C\uD788 \uD754\uB4E4\uB9B0\uB2E4. \uC774\uBBF8 \uC785\uC740 \uBC18\uCBE4 \uBC8C\uC5B4\uC838 \uC788\uB2E4.", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uB8E8\uCE74\uAC00 \uACC1\uB208\uC9C8\uB85C \uC5F0\uAD6C\uC6D0\uC744 \uBCF8\uB2E4. \uD310\uB2E8\uC744 \uAD6C\uD558\uB294 \uB208\uC774\uB2E4.)", choices: [
      { id: "allow", label: "\uD55C \uC785 \uB354 \uBA39\uACE0 \uB0B4\uC77C \uB2EC\uB9AC\uBA74 \uB41C\uB2E4\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n6a" },
      { id: "bet", label: "\uBA39\uC740 \uB9CC\uD07C \uAC19\uC774 \uB2EC\uB9AC\uC790\uACE0 \uC81C\uC548\uD55C\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uB8E8\uCE74", body: "\uC5ED\uC2DC \uC5F0\uAD6C\uC6D0\uB2D8\uC740 \uC774\uD574\uAC00 \uBE68\uB77C. \uB0B4\uC77C \uB6F0\uBA74 \uB418\uB294 \uAC70\uC9C0. \uC57D\uC18D\uD55C \uAC70\uC57C. \uAE30\uC5B5\uD574 \uB46C.", nextId: "n7" },
    { id: "n6b", speaker: "\uB8E8\uCE74", body: "\uAC19\uC774? \uC88B\uC544, \uB0B4\uAE30\uD558\uC790. \uC5F0\uAD6C\uC18C \uD55C \uBC14\uD034. \uB0B4\uAC00 \uC774\uAE30\uBA74 \uD55C \uC870\uAC01 \uB354, \uC9C0\uBA74\u2026 \uD55C \uC870\uAC01 \uB35C \uBA39\uC744\uAC8C.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uB2E4\uC74C \uB0A0 \uC544\uCE68. \uBCF5\uB3C4 \uB05D\uC5D0 \uC120 \uB8E8\uCE74\uAC00 \uBAB8\uC744 \uD47C\uB2E4. \uCF00\uC774\uD06C \uB54C\uBB38\uC778\uC9C0 \uAC78\uC74C\uC774 \uD3C9\uC18C\uBCF4\uB2E4 \uAC00\uBCCD\uC9C0 \uC54A\uB2E4. \uD558\uC9C0\uB9CC \uB208\uC740 \uBC18\uC9DD\uC778\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "", body: "\uCD9C\uBC1C \uC2E0\uD638\uC640 \uD568\uAED8 \uB8E8\uCE74\uAC00 \uD280\uC5B4 \uB098\uAC04\uB2E4. \uD6C4\uB4DC\uAC00 \uBC14\uB78C\uC5D0 \uD384\uB7ED\uC774\uACE0 \uD55C \uBC14\uD034\uAC00 \uB208 \uAE5C\uC9DD\uD560 \uC0AC\uC774\uC5D0 \uB05D\uB09C\uB2E4. \uC228\uC18C\uB9AC \uD558\uB098 \uAC70\uCE60\uC5B4\uC9C0\uC9C0 \uC54A\uC558\uB2E4.", nextId: "n9" },
    { id: "n9", speaker: "\uB8E8\uCE74", body: "\uBD10, \uD558\uB098\uB3C4 \uC548 \uB454\uD574\uC84C\uC9C0? \uCF00\uC774\uD06C\uB294 \uB2EC\uB9AC\uAE30\uC758 \uC5F0\uB8CC\uC57C. \uC774\uAC74 \uACFC\uD559\uC774\uC57C, \uC5F0\uAD6C\uC6D0\uB2D8.", nextId: "n10" },
    { id: "n10", speaker: "\uB8E8\uCE74", body: "\u2026\uADFC\uB370 \uD55C \uC870\uAC01 \uB354 \uBA39\uC73C\uBA74 \uB0B4\uC77C\uC740 \uC9C4\uC9DC \uD798\uB4E4\uC9C0\uB3C4 \uBAB0\uB77C. \uADF8\uB7EC\uB2C8\uAE4C \uC624\uB298\uC740 \uD55C \uC870\uAC01\uB9CC \uB354. \uC57D\uC18D\uC774\uC57C." }
  ]
};
var CHAPTER_823 = {
  id: "bond.luka.8",
  startNodeId: "n1",
  titleCard: { title: "\uC9E7\uAC8C \uB2EC\uB9AC\uB294 \uC0AC\uB78C", subtitle: "\uB8E8\uCE74 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 3" },
  nodes: [
    { id: "n1", speaker: "", body: "\uD6C8\uB828\uC7A5\uC758 \uAE34 \uD2B8\uB799. \uB3C4\uB514\uAC00 \uC7A5\uAC70\uB9AC \uB2EC\uB9AC\uAE30\uC5D0 \uB3C4\uC804\uD558\uB2E4\uAC00 \uBC18 \uBC14\uD034\uCBE4\uC5D0\uC11C \uC8FC\uC800\uC549\uC558\uB2E4. \uB8E8\uCE74\uAC00 \uD6C4\uB4DC\uB97C \uBC97\uC5B4 \uB4E4\uACE0 \uCC9C\uCC9C\uD788 \uB2E4\uAC00\uC628\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uB3C4\uB514", body: "\uB354\uB294 \uBABB \uB6F0\uACA0\uC5B4. \uB8E8\uCE74\uB294 \uC548 \uD798\uB4E4\uC5B4? \uAC19\uC774 \uC644\uC8FC\uD558\uC790\uACE0 \uD588\uC796\uC544.", nextId: "n3" },
    { id: "n3", speaker: "\uB8E8\uCE74", body: "\uB098 \uC7A5\uAC70\uB9AC\uB294 \uBABB \uD574. \uC194\uC9C1\uD788 \uB9D0\uD558\uBA74 \uBC18 \uBC14\uD034\uAC00 \uD55C\uACC4\uC57C. \uADF8\uB798\uB3C4 \uAD1C\uCC2E\uC544. \uBABB\uD558\uB294 \uAC74 \uBABB\uD558\uB294 \uB300\uB85C \uBC29\uBC95\uC774 \uC788\uC5B4.", nextId: "n4" },
    { id: "n4", speaker: "", body: "\uB8E8\uCE74\uAC00 \uB3C4\uB514 \uC55E\uC5D0 \uB4F1\uC744 \uB3CC\uB824 \uCB48\uADF8\uB9AC\uACE0 \uC549\uB294\uB2E4. \uAF2C\uB9AC\uAC00 \uB545\uC744 \uAC00\uBCCD\uAC8C \uC4F8\uACE0 \uC9C0\uB098\uAC04\uB2E4.", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uB8E8\uCE74\uAC00 \uC5B4\uAE68 \uB108\uBA38\uB85C \uB208\uC9D3\uD55C\uB2E4. \uB3C4\uB514\uB97C \uC5C5\uC5B4\uB3C4 \uB418\uACA0\uB290\uB0D0\uACE0 \uBB3B\uB294 \uB208\uBE5B\uC774\uB2E4.)", choices: [
      { id: "help", label: "\uB3C4\uB514\uB97C \uC77C\uC73C\uCF1C \uC5C5\uD600 \uC8FC\uAC8C \uB3D5\uB294\uB2E4", nextId: "n6a" },
      { id: "count", label: "\uD2B8\uB799\uC744 \uAC19\uC774 \uC138\uC5B4 \uC8FC\uACA0\uB2E4\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uB8E8\uCE74", body: "\uACE0\uB9C8\uC6CC. \uC774\uB807\uAC8C \uD558\uBA74 \uB3FC. \uC9E7\uAC8C \uB2EC\uB9AC\uACE0 \uC228 \uACE0\uB974\uACE0, \uB610 \uC9E7\uAC8C \uB2EC\uB9AC\uACE0. \uB05D\uAE4C\uC9C0 \uAC00\uB294 \uBC29\uBC95\uC740 \uD558\uB098\uAC00 \uC544\uB2C8\uAC70\uB4E0.", nextId: "n7" },
    { id: "n6b", speaker: "\uB8E8\uCE74", body: "\uC138\uC5B4 \uC918. \uC5F4 \uAC78\uC74C\uC529 \uB04A\uC5B4\uC11C \uAC08 \uAC70\uC57C. \uB0B4\uAC00 \uBABB \uD558\uB294 \uAC74 \uC5F0\uAD6C\uC6D0\uB2D8 \uC22B\uC790\uAC00 \uB300\uC2E0\uD574 \uC8FC\uB294 \uAC70\uC9C0.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uB8E8\uCE74\uAC00 \uB3C4\uB514\uB97C \uC5C5\uACE0 \uC5F4 \uAC78\uC74C\uC744 \uB2EC\uB9B0\uB2E4. \uBA48\uCDB0\uC11C \uC228\uC744 \uACE0\uB974\uACE0 \uB2E4\uC2DC \uC5F4 \uAC78\uC74C. \uD2B8\uB799\uC774 \uC870\uAE08\uC529 \uC904\uC5B4\uB4E0\uB2E4. \uB540\uBC29\uC6B8\uC774 \uD6C4\uB4DC \uC704\uB85C \uB5A8\uC5B4\uC9C4\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "\uB3C4\uB514", body: "\uB8E8\uCE74, \uC9C0\uAE08 \uC5C4\uCCAD \uBE68\uB77C. \uC548 \uBB34\uAC81\uC9C0? \uB0B4\uAC00 \uB0B4\uB824\uAC08\uAE4C?", nextId: "n9" },
    { id: "n9", speaker: "\uB8E8\uCE74", body: "\uC548 \uBB34\uAC70\uC6CC. \uAC71\uC815 \uB9C8. \uC624\uD788\uB824 \uB204\uAC00 \uB4F1\uC5D0 \uC788\uC73C\uBA74 \uB354 \uC798 \uB2EC\uB824. \uC774\uC720\uB294 \uB098\uB3C4 \uBAA8\uB974\uACA0\uC9C0\uB9CC.", nextId: "n10" },
    { id: "n10", speaker: "\uB8E8\uCE74", body: "\uACB0\uC2B9\uC120 \uB3C4\uCC29. \uC5F0\uAD6C\uC6D0\uB2D8, \uBD24\uC9C0? \uB098 \uC624\uB298 \uD55C \uBC14\uD034 \uC644\uC8FC\uD588\uC5B4. \uC5F4 \uAC78\uC74C \uACF1\uD558\uAE30 \uB9C8\uD754 \uBC88\uC774\uC57C. \uC22B\uC790\uB294 \uD2C0\uB9AC\uC9C0 \uC54A\uC544." }
  ]
};
var CHAPTER_1023 = {
  id: "bond.luka.10",
  startNodeId: "n1",
  titleCard: { title: "\uACB0\uC2B9\uC120\uC5D0 \uC11C \uC788\uB294 \uC0AC\uB78C", subtitle: "\uB8E8\uCE74 \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 4" },
  nodes: [
    { id: "n1", speaker: "", body: "\uD574 \uC9C8 \uB158\uC758 \uC625\uC678 \uD2B8\uB799. \uC624\uB298\uC740 \uC5F0\uAD6C\uC6D0\uC774 \uACB0\uC2B9\uC120 \uCABD\uC5D0 \uC11C \uC788\uACE0, \uB8E8\uCE74\uB294 \uBC18\uB300\uD3B8 \uCD9C\uBC1C\uC120\uC5D0\uC11C \uBAB8\uC744 \uD480\uACE0 \uC788\uB2E4. \uD6C4\uB4DC\uB294 \uBC97\uC5B4\uC11C \uC5F0\uAD6C\uC6D0 \uC5B4\uAE68\uC5D0 \uAC78\uCCD0 \uB454 \uCC44\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uB8E8\uCE74", body: "\uC5F0\uAD6C\uC6D0\uB2D8, \uC624\uB298\uC740 \uB2E8\uAC70\uB9AC\uC57C. \uADF8\uAC83\uB3C4 \uC81C\uC77C \uAE34 \uB2E8\uAC70\uB9AC. \uC800\uCABD \uB05D\uAE4C\uC9C0 \uC26C\uC9C0 \uC54A\uACE0 \uB2EC\uB9B4 \uAC70\uC57C!", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uD2B8\uB799 \uBC18\uB300\uD3B8\uC5D0\uC11C \uB8E8\uCE74\uAC00 \uC190\uC744 \uD754\uB4E0\uB2E4. \uAC70\uB9AC\uAC00 \uBA40\uC5B4\uC11C \uC5BC\uAD74\uC774 \uC791\uAC8C \uBCF4\uC778\uB2E4. \uD558\uC9C0\uB9CC \uAF2C\uB9AC\uAC00 \uB192\uC774 \uCE58\uCF1C\uB4E4\uB9B0 \uAC83\uC740 \uB610\uB837\uC774 \uBCF4\uC778\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uD6C4\uB4DC\uC5D0\uC11C\uB294 \uC18C\uD30C\uC758 \uB530\uB73B\uD55C \uB0C4\uC0C8\uAC00 \uB09C\uB2E4. \uB8E8\uCE74\uAC00 \uB9E4\uC77C \uC26C\uB358 \uC790\uB9AC\uC5D0\uC11C \uB098\uB294 \uB0C4\uC0C8\uB2E4.)", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uCD9C\uBC1C \uC2E0\uD638\uB97C \uB0B4\uB9B4 \uC2DC\uAC04\uC774\uB2E4. \uB8E8\uCE74\uAC00 \uD5C8\uB9AC\uB97C \uB0AE\uCD94\uACE0 \uC228\uC744 \uBAA8\uC740\uB2E4.)", choices: [
      { id: "arms", label: "\uB450 \uD314\uC744 \uD65C\uC9DD \uBC8C\uB824 \uB9DE\uC774\uD560 \uC900\uBE44\uB97C \uD55C\uB2E4", nextId: "n6a" },
      { id: "shout", label: "\uBAA9\uCCAD\uAECF \uC774\uB984\uC744 \uBD80\uB978\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uB8E8\uCE74", body: "(\uBA40\uB9AC\uC11C) \uC624! \uD314 \uBC8C\uB838\uB124? \uADF8\uB7FC \uC548 \uBA48\uCD9C \uC218\uAC00 \uC5C6\uC796\uC544! \uAC08\uAC8C! \uBC1B\uC544 \uC918!", nextId: "n7" },
    { id: "n6b", speaker: "\uB8E8\uCE74", body: "(\uBA40\uB9AC\uC11C) \uB4E4\uB824! \uC774\uB984 \uBD88\uB7EC \uC8FC\uB294 \uAC70 \uB4E4\uB824! \uADF8\uCABD\uC73C\uB85C \uAC08\uAC8C, \uAE30\uB2E4\uB824!", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uBC14\uB78C\uC774 \uBA3C\uC800 \uB2FF\uB294\uB2E4. \uADF8\uB2E4\uC74C \uBC1C\uC18C\uB9AC. \uB8E8\uCE74\uAC00 \uD2B8\uB799\uC744 \uAC00\uB85C\uC9C8\uB7EC \uC628\uB2E4. \uD3C9\uC18C \uC2ED \uCD08\uBA74 \uB05D\uB098\uB294 \uAC70\uB9AC\uAC00 \uC624\uB298\uC740 \uC774\uC0C1\uD558\uAC8C \uAE38\uACE0 \uB610\uB837\uD558\uAC8C \uB290\uAEF4\uC9C4\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "", body: "\uACB0\uC2B9\uC120 \uC55E\uC5D0\uC11C \uB8E8\uCE74\uAC00 \uC18D\uB3C4\uB97C \uC904\uC774\uC9C0 \uC54A\uC740 \uCC44 \uC5F0\uAD6C\uC6D0 \uD488\uC73C\uB85C \uB6F0\uC5B4\uB4E0\uB2E4. \uB458\uC774 \uD568\uAED8 \uC794\uB514 \uC704\uB85C \uAD74\uB7EC \uB118\uC5B4\uC9C4\uB2E4. \uB8E8\uCE74\uB294 \uC228\uC744 \uD5D0\uB5A1\uC774\uBA70 \uC6C3\uACE0 \uC788\uB2E4.", nextId: "n9" },
    { id: "n9", speaker: "\uB8E8\uCE74", body: "\uD558\uD558, \uC774\uB807\uAC8C \uB2EC\uB9B0 \uAC74 \uCC98\uC74C\uC774\uC57C. \uD3C9\uC18C\uC5D4 \uC9D1\uC73C\uB85C \uB2EC\uB824\uAC00\uB294\uB370, \uC624\uB298\uC740 \uC0AC\uB78C\uD55C\uD14C \uB2EC\uB824\uAC14\uC5B4. \uC9D1\uC774 \uC0AC\uB78C\uC77C \uC218\uB3C4 \uC788\uAD6C\uB098.", nextId: "n10" },
    { id: "n10", speaker: "\uB8E8\uCE74", body: "\uC5F0\uAD6C\uC6D0\uB2D8, \uB098 \uC774\uC81C \uC18C\uD30C \uB2E4\uC74C\uC73C\uB85C\uAC00 \uC544\uB2C8\uB77C\u2026 \uC5F0\uAD6C\uC6D0\uB2D8 \uB2E4\uC74C\uC73C\uB85C \uB2EC\uB9B4\uAC8C. \uC274 \uB550 \uC18C\uD30C\uB3C4 \uAC19\uC774 \uC4F0\uC790. \uB458\uC774 \uC549\uC544\uB3C4 \uB418\uB294 \uD06C\uAE30\uC796\uC544." }
  ]
};
var LUKA_STORY = {
  relicId: "luka",
  fossilRecord: "\uC0AC\uAD6C\uAC00 \uBB34\uB108\uC9C4 \uC790\uB9AC\uC5D0\uC11C \uAF2C\uB9AC\uAE4C\uC9C0 \uC774\uC5B4\uC9C4 \uAD00\uC808 \uACE8\uACA9\uC774 \uBAA8\uC2B5\uC744 \uB4DC\uB7EC\uB0C8\uB2E4. \uBC1C\uAC00\uB77D\uBF08\uC758 \uC815\uB82C\uC740 \uC9E7\uACE0 \uBE60\uB978 \uC9C8\uC8FC\uC5D0 \uD2B9\uD654\uB3FC \uC788\uC5C8\uB2E4.",
  diary: "\uBCF5\uC6D0 \uD6C4 \uB8E8\uCE74\uB294 \uC9D1\uACFC \uD734\uC2DD\uC744 \uBB34\uC5C7\uBCF4\uB2E4 \uC88B\uC544\uD558\uB294 \uB2E8\uAC70\uB9AC \uB2EC\uB9AC\uAE30 \uC120\uC218\uB85C \uAD00\uCC30\uB41C\uB2E4. \uB2E8\uAC70\uB9AC \uC120\uC218\uB2F5\uAC8C \uD558\uCCB4 \uADFC\uC721\uB7C9\uC774 \uD0C4\uD0C4\uD55C \uB8E8\uCE74\uB294 \uB2E4\uB978 \uC721\uC2DD \uACC4\uC5F4 \uB810\uB9AD\uB4E4\uACFC\uB3C4 \uB300\uCCB4\uB85C \uC6D0\uB9CC\uD558\uAC8C \uC9C0\uB0B8\uB2E4. \uC5F0\uAD6C\uC18C \uC18C\uD30C\uC5D0 \uAE38\uAC8C \uB204\uC6CC \uC26C\uB2E4\uAC00\uB3C4 \uB0B4\uAC00 \uC9C0\uB098\uAC00\uBA74 \uB298 \uBA3C\uC800 \uB9D0\uC744 \uAC78\uC5B4 \uC624\uB294 \uAC83\uC774 \uC2B5\uAD00\uC774\uB2E4. \uC88B\uC544\uD558\uB294 \uCE58\uC988\uCF00\uC774\uD06C\uB97C \uBA39\uC73C\uBA74\uC11C\uB3C4 \uC0B4\uC774 \uCC0C\uBA74 \uB2EC\uB9AC\uAE30\uAC00 \uB454\uD574\uC9C0\uC9C0 \uC54A\uACA0\uB0D0\uBA70 \uAC00\uBCCD\uAC8C \uAC71\uC815\uD558\uC9C0\uB9CC, \uC774\uB0B4 \uD55C \uC785 \uB354 \uBA39\uACE0\uB294 \uB2E4\uC74C \uC9C8\uC8FC\uB85C \uCDA9\uBD84\uD788 \uC6C0\uC9C1\uC774\uBA74 \uB41C\uB2E4\uBA70 \uC6C3\uB294\uB2E4.",
  /** 일지 맨 끝에 회색으로 서는, 루카가 연구원에게 건네는 한마디. 뽑기 대사와 다른 일상의 목소리다. */
  closingLine: "\uC5F0\uAD6C\uC6D0\uB2D8, \uC2EC\uBD80\uB984 \uC788\uC5B4? \uC774\uC2ED \uCD08\uBA74 \uB3FC. \uB2E4\uB140\uC640\uC11C \uC18C\uD30C\uC5D0\uC11C \uAC19\uC774 \uC26C\uC790.",
  questions: [
    {
      id: "luka-sofa",
      prompt: "\uB8E8\uCE74\uB294 \uC65C \uADF8\uB807\uAC8C \uC18C\uD30C\uB97C \uC88B\uC544\uD574?",
      choices: [
        {
          id: "home",
          label: "\uC18C\uD30C\uAC00 \uC9D1 \uAC19\uC544\uC11C\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uB9DE\uC544. \uC18C\uD30C\uC5D0 \uB204\uC6B0\uBA74 \uC9D1\uC5D0 \uC628 \uAC83 \uAC19\uC544. \uB2EC\uB9AC\uACE0 \uB3CC\uC544\uC62C \uACF3\uC774 \uC788\uB2E4\uB294 \uB290\uB08C\uC774\uC57C. \uADF8\uAC8C \uC81C\uC77C \uC911\uC694\uD574.",
          note: "\uC18C\uD30C\uAC00 \uC9D1 \uAC19\uC73C\uB0D0\uACE0 \uBB3B\uC790 \uB208\uC744 \uAC10\uACE0 \uACE0\uAC1C\uB97C \uB044\uB355\uC600\uB2E4. \uB2EC\uB9AC\uACE0 \uB3CC\uC544\uC62C \uACF3\uC774 \uC788\uB2E4\uB294 \uB290\uB08C\uC774 \uC88B\uB2E4\uACE0 \uD55C\uB2E4."
        },
        {
          id: "lazy",
          label: "\uAC8C\uC73C\uB974\uB2E4\uACE0 \uB180\uB824 \uBCF8\uB2E4",
          reply: "\uAC8C\uC73C\uB978 \uAC8C \uC544\uB2C8\uC57C. \uCDA9\uC804 \uC911\uC774\uC57C. \uC9E7\uAC8C \uB2EC\uB9AC\uB824\uBA74 \uAE38\uAC8C \uC26C\uC5B4\uC57C \uD558\uAC70\uB4E0. \uC5F0\uAD6C\uC6D0\uB2D8\uB3C4 \uD574 \uBCF4\uBA74 \uC54C\uC544.",
          note: "\uAC8C\uC73C\uB974\uB2E4\uACE0 \uB180\uB9AC\uC790 \uD6C4\uB4DC\uB97C \uBA38\uB9AC\uC5D0 \uB36E\uC5B4\uC37C\uB2E4. \uC26C\uB294 \uAC83\uC740 \uCDA9\uC804\uC774\uB77C\uACE0 \uC8FC\uC7A5\uD588\uB2E4."
        },
        {
          id: "hood",
          label: "\uD6C4\uB4DC\uB294 \uC65C \uB298 \uC4F0\uACE0 \uC788\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uBA38\uB9AC\uB97C \uB36E\uC73C\uBA74 \uC18C\uB9AC\uAC00 \uC791\uC544\uC838. \uADF8\uB7FC \uC548\uC2EC\uC774 \uB3FC. \uC274 \uB550 \uC138\uC0C1\uC774 \uC870\uAE08 \uBA40\uC5B4\uC9C0\uB294 \uAC8C \uC88B\uC544.",
          note: "\uD6C4\uB4DC\uB97C \uBB3B\uC790 \uAC00\uC7A5\uC790\uB9AC\uB97C \uAF2D \uC950\uC5C8\uB2E4. \uC274 \uB54C\uB294 \uC138\uC0C1\uC774 \uC870\uAE08 \uBA40\uC5B4\uC9C0\uB294 \uB290\uB08C\uC774 \uC88B\uB2E4\uACE0 \uD55C\uB2E4."
        }
      ]
    },
    {
      id: "luka-run",
      prompt: "\uB2EC\uB9AC\uB294 \uAC74 \uC5B4\uB5A4 \uAE30\uBD84\uC774\uC57C?",
      choices: [
        {
          id: "wind",
          label: "\uBC14\uB78C\uC774 \uAE30\uBD84 \uC88B\uC73C\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC751, \uBC14\uB78C\uC774 \uBA3C\uC800 \uC9C0\uB098\uAC00\uACE0 \uB0B4\uAC00 \uB530\uB77C\uAC00\uB294 \uB290\uB08C\uC774\uC57C. \uC21C\uAC04\uC774\uC9C0\uB9CC \uADF8 \uC21C\uAC04\uC774 \uC81C\uC77C \uC88B\uC544.",
          note: "\uBC14\uB78C\uC774 \uC88B\uC73C\uB0D0\uACE0 \uBB3B\uC790 \uAF2C\uB9AC\uAC00 \uD06C\uAC8C \uD754\uB4E4\uB838\uB2E4. \uBC14\uB78C\uC774 \uBA3C\uC800 \uC9C0\uB098\uAC00\uACE0 \uC790\uC2E0\uC774 \uB530\uB77C\uAC00\uB294 \uB290\uB08C\uC774\uB77C\uACE0 \uD55C\uB2E4."
        },
        {
          id: "short",
          label: "\uC65C \uAE34 \uAC70\uB9AC\uB294 \uC548 \uB6F0\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uBABB \uB6F0\uC5B4. \uBC18 \uBC14\uD034\uAC00 \uD55C\uACC4\uC57C. \uB300\uC2E0 \uC9E7\uAC8C \uC5EC\uB7EC \uBC88 \uB6F0\uBA74 \uB3FC. \uBABB \uD558\uB294 \uAC74 \uBD80\uB044\uB7EC\uC6B4 \uAC8C \uC544\uB2C8\uC57C.",
          note: "\uAE34 \uAC70\uB9AC\uB97C \uC548 \uB6F0\uB294 \uC774\uC720\uB97C \uBB3B\uC790 \uB2F4\uB2F4\uD558\uAC8C \uB2F5\uD588\uB2E4. \uBABB \uD558\uB294 \uAC83\uC744 \uBD80\uB044\uB7EC\uC6CC\uD558\uC9C0 \uC54A\uB294\uB2E4."
        }
      ]
    },
    {
      id: "luka-cake",
      prompt: "\uCE58\uC988\uCF00\uC774\uD06C\uB97C \uBA39\uC73C\uBA74\uC11C \uC65C \uB9E4\uBC88 \uAC71\uC815\uD574?",
      choices: [
        {
          id: "weight",
          label: "\uB2EC\uB9AC\uAE30\uAC00 \uB454\uD574\uC9C8\uAE4C \uBD10 \uADF8\uB7EC\uB294 \uAC70\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC751, \uADFC\uB370 \uAC71\uC815\uB9CC \uD558\uACE0 \uBA39\uC5B4. \uAC71\uC815\uC740 \uC785\uC5D0 \uB123\uAE30 \uC804\uAE4C\uC9C0\uB9CC \uD558\uB294 \uAC70\uC57C. \uC77C\uB2E8 \uC785\uC5D0 \uB123\uC73C\uBA74 \uB05D\uC774\uC57C.",
          note: "\uB2EC\uB9AC\uAE30\uAC00 \uB454\uD574\uC9C8\uAE4C \uBD10 \uAC71\uC815\uD558\uB290\uB0D0\uACE0 \uBB3B\uC790 \uC6C3\uC5C8\uB2E4. \uAC71\uC815\uC740 \uC785\uC5D0 \uB123\uAE30 \uC804\uAE4C\uC9C0\uB9CC \uD55C\uB2E4\uACE0 \uD55C\uB2E4."
        },
        {
          id: "share",
          label: "\uD55C \uC870\uAC01 \uB098\uB220 \uBA39\uC790\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\uB098\uB220 \uBA39\uC73C\uBA74 \uAC71\uC815\uB3C4 \uBC18\uC774\uC57C. \uC88B\uC544, \uB098\uB220 \uBA39\uC790. \uC5F0\uAD6C\uC6D0\uB2D8\uC774\uB791\uC774\uBA74 \uD55C \uC870\uAC01\uC774 \uB450 \uC870\uAC01 \uB9DB\uC774\uC57C.",
          note: "\uB098\uB220 \uBA39\uC790\uACE0 \uD558\uC790 \uB208\uC774 \uBC18\uC9DD\uC600\uB2E4. \uB098\uB204\uBA74 \uAC71\uC815\uB3C4 \uBC18\uC774 \uB41C\uB2E4\uACE0 \uD588\uB2E4."
        },
        {
          id: "run",
          label: "\uBA39\uC740 \uB9CC\uD07C \uAC19\uC774 \uB2EC\uB9AC\uC790\uACE0 \uD55C\uB2E4",
          reply: "\uAC19\uC774 \uB2EC\uB9AC\uB294 \uAC70 \uC88B\uC544. \uADFC\uB370 \uB098 \uB108\uBB34 \uBE68\uB77C\uC11C \uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uBABB \uB530\uB77C\uC62C\uAC78. \uAD1C\uCC2E\uC544, \uACB0\uC2B9\uC120\uC5D0\uC11C \uAE30\uB2E4\uB9B4\uAC8C.",
          note: "\uAC19\uC774 \uB2EC\uB9AC\uC790\uACE0 \uD558\uC790 \uC5B4\uAE68\uB97C \uC73C\uC4F1\uC600\uB2E4. \uB108\uBB34 \uBE68\uB77C\uC11C \uACB0\uC2B9\uC120\uC5D0\uC11C \uAE30\uB2E4\uB9AC\uACA0\uB2E4\uACE0 \uD588\uB2E4."
        }
      ]
    }
  ],
  bondStories: { 4: CHAPTER_423, 6: CHAPTER_623, 8: CHAPTER_823, 10: CHAPTER_1023 },
  bondLines: [
    // 0 — 낯선 사이.
    ["\uCC98\uC74C \uBCF4\uB124. \uB8E8\uCE74\uC57C. \uB2EC\uB9AC\uB294 \uAC74 \uC790\uC2E0 \uC788\uC5B4. \uC18C\uD30C \uB2E4\uC74C\uC73C\uB85C.", "\uC5F0\uAD6C\uC6D0\uB2D8\uC774\uB77C\uACE0 \uBD80\uB974\uBA74 \uB3FC? \uD3B8\uD558\uAC8C \uBD88\uB7EC. \uB098\uB294 \uB300\uCDA9 \uB300\uB2F5\uD574\uB3C4 \uC774\uD574\uD574 \uC918.", "\uC2EC\uBD80\uB984 \uD544\uC694\uD558\uBA74 \uB9D0\uD574. \uC774\uC2ED \uCD08\uBA74 \uB05D\uB098. \uB300\uC2E0 \uB05D\uB098\uACE0 \uC26C\uAC8C \uD574 \uC918."],
    // 1
    ["\uC624\uB298\uC740 \uC18C\uD30C\uAC00 \uB530\uB73B\uD574. \uC77C\uC5B4\uB098\uAE30 \uC2EB\uC740 \uB0A0\uC774\uC57C. \uD558\uC9C0\uB9CC \uBD80\uB974\uBA74 \uAC08\uAC8C.", "\uCE58\uC988\uCF00\uC774\uD06C \uC788\uC5B4? \uAC71\uC815\uBD80\uD130 \uD558\uACE0 \uBA39\uC744\uAC8C. \uC21C\uC11C\uAC00 \uC911\uC694\uD558\uAC70\uB4E0.", "\uD6C4\uB4DC \uC4F0\uBA74 \uC878\uB824. \uADFC\uB370 \uC878\uB824\uB3C4 \uB2EC\uB9B4 \uB550 \uAE68. \uC2E0\uAE30\uD558\uC9C0?"],
    // 2
    ["\uC26C\uB294 \uAC83\uB3C4 \uC77C\uC774\uC57C. \uC774\uAC78 \uC774\uD574\uD574 \uC8FC\uB294 \uC0AC\uB78C\uC774 \uC801\uC5B4. \uC5F0\uAD6C\uC6D0\uB2D8\uC740 \uC774\uD574\uD574 \uC918\uC11C \uC88B\uC544.", "\uC624\uB298 \uBCF5\uB3C4 \uC138 \uBC14\uD034 \uB6F0\uC5C8\uC5B4. \uC774\uC2ED \uCD08\uC529. \uC774 \uC815\uB3C4\uBA74 \uC624\uB298 \uD560 \uC77C\uC740 \uB2E4 \uD55C \uAC70\uC57C.", "\uB3C4\uB514\uAC00 \uB0B4 \uB4A4\uB97C \uCAD3\uC544\uC624\uB294\uB370 \uD55C \uBC88\uB3C4 \uBABB \uC7A1\uC558\uC5B4. \uADFC\uB370 \uACC4\uC18D \uCAD3\uC544\uC640. \uB300\uB2E8\uD574."],
    // 3
    ["\uC544\uCE68\uC5D0 \uBCF5\uB3C4 \uB05D\uAE4C\uC9C0 \uB2EC\uB838\uB294\uB370 \uCCAD\uC18C\uD558\uB358 \uC0AC\uB78C\uC774 \uAE5C\uC9DD \uB180\uB77C\uB354\uB77C. \uBBF8\uC548, \uC778\uC0AC\uB294 \uD558\uACE0 \uC9C0\uB098\uAC14\uC5B4.", "\uC5F0\uAD6C\uC6D0\uB2D8 \uC624\uB298 \uD45C\uC815 \uC880 \uD53C\uACE4\uD574 \uBCF4\uC5EC. \uC2ED \uBD84\uB9CC \uC549\uC558\uB2E4 \uAC00. \uC2DC\uAC04\uC740 \uB0B4\uAC00 \uBD10 \uC904\uAC8C.", "\uC18C\uD30C \uD55C\uCABD\uC740 \uBE44\uC6CC \uB480\uC5B4. \uB204\uAC00 \uC62C\uC9C0\uB294 \uBAA8\uB974\uACA0\uC9C0\uB9CC \uC900\uBE44\uB294 \uD574 \uB450\uB294 \uAC70\uC9C0."],
    // 4 — 장 4 이후: 소파 다음으로.
    ["\uC774\uC2ED \uCD08 \uC2EC\uBD80\uB984, \uC7AC\uBC0C\uC5C8\uC5B4. \uB2E4\uC74C\uC5D0\uB3C4 \uC2DC\uCF1C \uC918. \uB300\uC2E0 \uB05D\uB098\uBA74 \uAC19\uC774 \uC549\uC790.", "\uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uC18C\uD30C\uC5D0 \uC549\uC558\uC744 \uB54C \uC880 \uB180\uB790\uC5B4. \uADF8 \uC790\uB9AC\uB294 \uB3C4\uB514 \uB9D0\uACE0\uB294 \uC548 \uC549\uC558\uAC70\uB4E0.", "\uB2EC\uB9AC\uB294 \uAC74 \uC9E7\uAC8C, \uC26C\uB294 \uAC74 \uAE38\uAC8C. \uC5F0\uAD6C\uC6D0\uB2D8\uB3C4 \uC774 \uBC29\uC2DD \uC5B4\uC6B8\uB9B4 \uAC83 \uAC19\uC544."],
    // 5
    ["\uC624\uB298 \uCF00\uC774\uD06C\uB294 \uC138 \uBC88 \uAC71\uC815\uD558\uACE0 \uB450 \uBC88 \uBA39\uC5C8\uC5B4. \uC774 \uC815\uB3C4\uBA74 \uADE0\uD615 \uC7A1\uD78C \uB0A0\uC774\uC57C.", "\uC544\uCE68 \uACF5\uAE30\uAC00 \uB2EC\uB9AC\uAE30\uC5D0 \uB531\uC774\uC57C. \uC774\uB7F0 \uB0A0\uC740 \uC18C\uD30C \uB300\uC2E0 \uD2B8\uB799\uC5D0 \uC788\uC5B4\uB3C4 \uB3FC.", "\uD6C4\uB4DC\uB97C \uBC97\uC73C\uBA74 \uADC0\uAC00 \uC2DC\uB824. \uADF8\uB798\uC11C \uC880\uCC98\uB7FC \uC548 \uBC97\uC5B4."],
    // 6 — 장 6 이후: 치즈케이크 한 입 더.
    ["\uCF00\uC774\uD06C \uB9C8\uC9C0\uB9C9 \uC870\uAC01\uC740 \uC5F0\uAD6C\uC6D0\uB2D8 \uBAAB\uC73C\uB85C \uB0A8\uACA8 \uB480\uC5B4. \uB0B4\uAC00 \uCC38\uC740 \uAC70\uB2C8\uAE4C \uAF2D \uBA39\uC5B4.", "\uB2EC\uB9AC\uAE30 \uC804\uC5D4 \uCF00\uC774\uD06C \uD55C \uC870\uAC01\uC774\uBA74 \uCDA9\uBD84\uD574. \uB450 \uC870\uAC01\uC774\uBA74 \uB2EC\uB9AC\uB2E4 \uB9D0\uACE0 \uC878\uB824.", "\uAC71\uC815\uD558\uBA74\uC11C \uBA39\uB294 \uCF00\uC774\uD06C\uAC00 \uC81C\uC77C \uB9DB\uC788\uC5B4. \uC774\uC720\uB294 \uBAB0\uB77C."],
    // 7
    ["\uC624\uB298\uC740 \uD55C \uBC88\uB3C4 \uC548 \uB2EC\uB838\uC5B4. \uD558\uB8E8\uCBE4\uC740 \uADF8\uB798\uB3C4 \uB3FC. \uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uB9D0\uD574 \uC92C\uC796\uC544.", "\uC18C\uD30C\uC5D0\uC11C \uC62C\uB824\uB2E4\uBCF4\uB294 \uCC9C\uC7A5 \uBB34\uB2AC\uAC00 \uC88B\uC544. \uAC19\uC774 \uC138\uC5B4 \uBCFC\uB798?", "\uB204\uAC00 \uC7A5\uAC70\uB9AC \uC5F0\uC2B5\uD55C\uB2E4\uACE0 \uD558\uBA74 \uC751\uC6D0\uC740 \uD06C\uAC8C \uD574 \uC918. \uAC19\uC774\uB294 \uBABB \uB6F0\uC5B4\uB3C4 \uBAA9\uC18C\uB9AC\uB294 \uB05D\uAE4C\uC9C0 \uAC00\uAC70\uB4E0."],
    // 8 — 장 8 이후: 짧게 달리는 사람.
    ["\uB3C4\uB514 \uC5C5\uACE0 \uB2EC\uB9B0 \uB0A0 \uC5B4\uAE68\uAC00 \uBED0\uADFC\uD588\uB294\uB370 \uAE30\uBD84\uC740 \uC88B\uC558\uC5B4. \uC774\uC0C1\uD558\uC9C0.", "\uBABB \uB6F0\uB294 \uAC70\uB9AC\uB294 \uADF8\uB0E5 \uAC78\uC73C\uBA74 \uB3FC. \uC5F4 \uAC78\uC74C\uC774\uBA74 \uCDA9\uBD84\uD55C \uB0A0\uB3C4 \uC788\uC5B4.", "\uC22B\uC790 \uC138\uB294 \uAC70 \uC740\uADFC \uC7AC\uBC0C\uB354\uB77C. \uD558\uB098, \uB458, \uC14B\u2026 \uC5B4, \uC5B4\uB514\uAE4C\uC9C0 \uC14C\uB354\uB77C."],
    // 9
    ["\uACB0\uC2B9\uC120\uC5D0 \uB204\uAC00 \uC11C \uC788\uC73C\uBA74 \uB2EC\uB9B4 \uC774\uC720\uAC00 \uC0DD\uACA8. \uC694\uC998 \uADF8 \uC0DD\uAC01\uC744 \uC790\uC8FC \uD574.", "\uC9D1\uC774 \uC5B4\uB514\uB0D0\uACE0 \uBB3C\uC73C\uBA74 \uC18C\uD30C\uB77C\uACE0 \uD588\uB294\uB370, \uC694\uC998\uC740 \uC870\uAE08 \uD5F7\uAC08\uB824.", "\uD6C4\uB4DC \uC8FC\uBA38\uB2C8\uC5D0\uC11C \uC5F0\uAD6C\uC6D0\uB2D8\uC774 \uB123\uC5B4 \uB454 \uAC04\uC2DD\uC774 \uB098\uC654\uC5B4. \uBE44\uBC00\uB85C \uD574 \uC904\uAC8C."],
    // 10 — 마음을 연 사이. 결승선에서 안긴 사이.
    ["\uC0AC\uB78C\uD55C\uD14C \uB2EC\uB824\uAC00\uB294 \uAC74 \uCC98\uC74C\uC774\uC5C8\uC5B4. \uD3C9\uC18C\uBCF4\uB2E4 \uC624\uB798 \uAC78\uB9B0 \uAC83 \uAC19\uC740\uB370 \uBE68\uB790\uC5B4.", "\uC774\uC81C \uC18C\uD30C\uB294 \uB458\uC774 \uC4F0\uB294 \uAC70\uC57C. \uD55C\uCABD\uC774 \uBE44\uC5B4 \uC788\uC73C\uBA74 \uD5C8\uC804\uD574\uC11C \uBABB \uC790\uACA0\uC5B4.", "\uC5F0\uAD6C\uC6D0\uB2D8 \uB2E4\uC74C\uC73C\uB85C \uB2EC\uB9B4\uAC8C. \uADF8\uB2E4\uC74C\uC774 \uC18C\uD30C\uC57C. \uC21C\uC11C\uB294 \uC774\uC81C \uC774\uAC70\uC57C."]
  ]
};

