var CHAPTER_426 = {
  id: "bond.shute.4",
  startNodeId: "n1",
  titleCard: { title: "\uD654\uBA74 \uC5EC\uB35F \uC7A5", subtitle: "\uC288\uD14C \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 1" },
  nodes: [
    { id: "n1", speaker: "", body: "\uBC24\uC758 \uD6C8\uB828\uC7A5 \uD55C\uCABD \uAD6C\uC11D\uBC29. \uBB38\uC744 \uC5F4\uC790 \uC5B4\uB460 \uC18D\uC5D0\uC11C \uD654\uBA74 \uC5EC\uB35F \uC7A5\uC774 \uD55C\uAEBC\uBC88\uC5D0 \uD658\uD558\uAC8C \uCF1C\uC9C4\uB2E4. \uAC01\uAC01 \uB2E4\uB978 \uAC01\uB3C4\uC758 \uD6C8\uB828\uC7A5\uC774 \uBE44\uCE58\uACE0, \uAC00\uC6B4\uB370\uC5D0\uB294 \uB3C4\uD2B8\uB85C \uB9CC\uB4E0 \uC791\uC740 \uACF5\uB8E1\uC774 \uD640\uB85C\uADF8\uB7A8\uC73C\uB85C \uB5A0 \uC788\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "", body: "\uADF8 \uC55E\uC5D0 \uB178\uB780\uC0C9 \uBFB0\uC871 \uD6C4\uB4DC\uB97C \uB4A4\uC9D1\uC5B4\uC4F4 \uC288\uD14C\uAC00 \uC758\uC790\uC9F8\uB85C \uB3CC\uC544\uC549\uB294\uB2E4. \uD5E4\uB4DC\uD3F0 \uD55C\uCABD\uC774 \uADC0\uC5D0\uC11C \uBE44\uC2A4\uB4EC\uD788 \uB0B4\uB824\uC640 \uC788\uACE0, \uC190\uC5D0\uB294 \uB0A1\uC740 \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uC950\uC5B4\uC838 \uC788\uB2E4.", nextId: "n3" },
    { id: "n3", speaker: "\uC288\uD14C", body: "\u2026\uC654\uC5B4, \uC624\uB354? \uBB38 \uB2EB\uC544. \uBE5B \uC0C8\uC5B4 \uB098\uAC00\uBA74 \uD654\uBA74 \uBC18\uC0AC\uB3FC.", nextId: "n4" },
    { id: "n4", speaker: "", body: "\uC5F0\uAD6C\uC6D0\uC774 \uBB38\uC744 \uB2EB\uC790 \uBC29 \uC548\uC740 \uD654\uBA74 \uBE5B\uB9CC \uB0A8\uB294\uB2E4. \uD654\uBA74 \uC18D\uC5D0\uC11C\uB294 \uB3C4\uB514\uAC00 \uD6C8\uB828 \uCF54\uC2A4\uB97C \uB6F0\uACE0 \uC788\uB2E4. \uB3C4\uB514\uC758 \uBC1C\uAC78\uC74C\uB9C8\uB2E4 \uC288\uD14C\uC758 \uC190\uAC00\uB77D\uC774 \uCEE8\uD2B8\uB864\uB7EC \uC704\uC5D0\uC11C \uD568\uAED8 \uC6C0\uC9C1\uC778\uB2E4.", nextId: "n5" },
    { id: "n5", speaker: "\uC288\uD14C", body: "\u2026\uB3C4\uB514, \uC67C\uCABD. \uC544\uB2C8, \uC624\uB978\uCABD. \uADF8\uAC70 \uC544\uB2C8\uB77C\uB2C8\uAE4C? \u2026\uB410\uC5B4, \uC548 \uB4E4\uB9AC\uC9C0. \uD1B5\uC2E0 \uAEBC\uC838 \uC788\uC5C8\uB124.", nextId: "n6" },
    { id: "n6", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uC288\uD14C\uAC00 \uD654\uBA74\uC5D0 \uC2DC\uC120\uC744 \uB454 \uCC44 \uD55C \uBC15\uC790 \uB2A6\uAC8C \uC5F0\uAD6C\uC6D0 \uCABD\uC73C\uB85C \uACE0\uAC1C\uB97C \uB3CC\uB9B0\uB2E4.)", choices: [
      { id: "ask", label: "\uC65C \uD654\uBA74\uC73C\uB85C\uB9CC \uBCF4\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4", nextId: "n7a" },
      { id: "sit", label: "\uB9D0\uC5C6\uC774 \uC606\uC790\uB9AC\uC5D0 \uC549\uC544 \uD654\uBA74\uC744 \uBCF8\uB2E4", nextId: "n7b" }
    ] },
    { id: "n7a", speaker: "\uC288\uD14C", body: "\u2026\uC9C1\uC811 \uBCF4\uBA74 \uC804\uCCB4\uAC00 \uC548 \uBCF4\uC5EC. \uC5EC\uB35F \uC7A5\uC774\uBA74 \uD55C \uBC88\uC5D0 \uB2E4 \uB3FC. \uB208\uC740 \uB450 \uAC1C\uBFD0\uC774\uC796\uC544.", nextId: "n8" },
    { id: "n7b", speaker: "\uC288\uD14C", body: "\u2026\uC549\uC558\uB124. \uBB50, \uAD1C\uCC2E\uC544. \uAC70\uAE30 \uC549\uC73C\uBA74 \uB3C4\uB514 \uD654\uBA74\uC774 \uC81C\uC77C \uC798 \uBCF4\uC5EC.", nextId: "n8" },
    { id: "n8", speaker: "", body: "\uD654\uBA74 \uC18D \uB3C4\uB514\uAC00 \uCF54\uC2A4 \uB05D\uC5D0 \uB2FF\uB294\uB2E4. \uC288\uD14C\uC758 \uC5B4\uAE68\uAC00 \uC544\uC8FC \uC870\uAE08 \uB0B4\uB824\uAC04\uB2E4. \uCEE8\uD2B8\uB864\uB7EC\uB97C \uC954 \uC190\uC758 \uD798\uC774 \uD480\uB9B0\uB2E4.", nextId: "n9" },
    { id: "n9", speaker: "\uC288\uD14C", body: "\u2026\uC798\uD588\uB124. \uADF8\uB7ED\uC800\uB7ED.", nextId: "n10" },
    { id: "n10", speaker: "\uC288\uD14C", body: "\u2026\uC624\uB354. \uC774 \uBC29\uC740 \uC544\uBB34\uD55C\uD14C\uB3C4 \uC548 \uBCF4\uC5EC \uC92C\uC5B4. \uBE44\uBC00\uC774\uC57C. \uB098\uAC08 \uB54C \uBB38 \uCC9C\uCC9C\uD788 \uB2EB\uC544." }
  ]
};
var CHAPTER_626 = {
  id: "bond.shute.6",
  startNodeId: "n1",
  titleCard: { title: "\uD55C \uBC15\uC790 \uB2A6\uC740 \uB300\uB2F5", subtitle: "\uC288\uD14C \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 2" },
  nodes: [
    { id: "n1", speaker: "", body: "\uC5F0\uAD6C\uC2E4 \uC55E \uBCF5\uB3C4. \uB3C4\uB514\uAC00 \uC288\uD14C\uB97C \uBD99\uC7A1\uACE0 \uB9D0\uC744 \uAC78\uACE0 \uC788\uB2E4. \uC288\uD14C\uB294 \uD5E4\uB4DC\uD3F0\uC744 \uBC18\uCBE4 \uAC78\uCE5C \uCC44 \uADF8\uB97C \uC62C\uB824\uB2E4\uBCF8\uB2E4. \uB300\uB2F5\uC774 \uD55C\uCC38 \uB3CC\uC544\uC624\uC9C0 \uC54A\uB294\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uB3C4\uB514", body: "\uC288\uD14C, \uC5B4\uC81C \uC9C0\uC2DC \uACE0\uB9C8\uC6E0\uC5B4! \uADFC\uB370 \uB9C8\uC9C0\uB9C9\uC5D0 \uC65C \uAC11\uC790\uAE30 \uC870\uC6A9\uD588\uC5B4? \uB0B4\uAC00 \uBB50 \uC798\uBABB\uD588\uC5B4?", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uC288\uD14C\uC758 \uB208\uC774 \uB3C4\uB514\uB97C \uD55C\uCC38 \uBC14\uB77C\uBCF8\uB2E4. \uCEE8\uD2B8\uB864\uB7EC\uB97C \uC954 \uC190\uAC00\uB77D\uC774 \uD5C8\uBC85\uC9C0 \uC704\uC5D0\uC11C \uC791\uAC8C \uC6C0\uC9C1\uC778\uB2E4. \uC785\uC220\uC774 \uB2EC\uC2F9\uC774\uB2E4\uAC00 \uBA48\uCD98\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC288\uD14C", body: "\u2026\uC544\uB2C8. \uC798\uBABB\uD55C \uAC70 \uC5C6\uC5B4. \u2026\uB9C8\uC9C0\uB9C9\uC5D4 \uD560 \uB9D0\uC774 \uC5C6\uC5B4\uC11C \uADF8\uB7AC\uC5B4. \uC798 \uAC00\uACE0 \uC788\uC5C8\uAC70\uB4E0.", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uB3C4\uB514\uC758 \uC5BC\uAD74\uC774 \uD658\uD558\uAC8C \uD480\uB9B0\uB2E4. \uC288\uD14C\uB294 \uADF8 \uBC18\uC751\uC744 \uBCF4\uACE0 \uACE0\uAC1C\uB97C \uC0B4\uC9DD \uB3CC\uB9B0\uB2E4. \uADC0 \uB05D\uC774 \uC870\uAE08 \uBD89\uB2E4.)", choices: [
      { id: "praise", label: "\uC288\uD14C\uC758 \uC9C0\uC2DC\uAC00 \uC815\uD655\uD588\uB2E4\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n6a" },
      { id: "wait", label: "\uB300\uB2F5\uC774 \uB2A6\uC5B4\uB3C4 \uAE30\uB2E4\uB824 \uC904 \uC218 \uC788\uB2E4\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uC288\uD14C", body: "\u2026\uC815\uD655\uD55C \uAC74 \uB2F9\uC5F0\uD558\uC9C0. \uADFC\uB370 \uADF8\uB7F0 \uB9D0\uC740\u2026 \uADF8\uB7ED\uC800\uB7ED \uB4E3\uAE30 \uC88B\uB124. \uD55C \uBC88\uB9CC \uB354 \uD574 \uBD10.", nextId: "n7" },
    { id: "n6b", speaker: "\uC288\uD14C", body: "\u2026\uAE30\uB2E4\uB824 \uC900\uB2E4\uACE0? \uB2E4\uB4E4 \uC911\uAC04\uC5D0 \uB2E4\uB978 \uC598\uAE30 \uD558\uB358\uB370. \u2026\uACE0\uB9C8\uC6CC. \uC774\uAC74 \uC9C4\uC2EC\uC774\uC57C, \uC624\uB354.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uC288\uD14C\uAC00 \uCEE8\uD2B8\uB864\uB7EC\uB97C \uB9CC\uC9C0\uC791\uAC70\uB9AC\uB2E4\uAC00 \uCC9C\uCC9C\uD788 \uC785\uC744 \uC5F0\uB2E4. \uD3C9\uC18C\uC640 \uB2EC\uB9AC \uB9D0\uC774 \uD55C \uBC88\uC5D0 \uAE38\uAC8C \uC774\uC5B4\uC9C4\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "\uC288\uD14C", body: "\uD654\uBA74 \uC18D\uC5D0\uC11C\uB294 \uB9D0\uC774 \uBC14\uB85C \uB098\uAC00. \uADFC\uB370 \uC0AC\uB78C \uC55E\uC5D0\uC120 \uD55C \uBC15\uC790 \uB2A6\uC5B4. \uBA38\uB9BF\uC18D\uC5D0\uC11C \uBA3C\uC800 \uC9C0\uC2DC\uB97C \uB2E4 \uC9DC\uC57C \uD558\uAC70\uB4E0. \uD2C0\uB9B0 \uB9D0 \uD558\uBA74 \uB204\uAC00 \uB2E4\uCE58\uB2C8\uAE4C.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uB3C4\uB514\uAC00 \uB208\uC744 \uD06C\uAC8C \uB72C\uB2E4. \uC288\uD14C\uB294 \uB9D0\uC744 \uB9C8\uCE58\uC790\uB9C8\uC790 \uD5E4\uB4DC\uD3F0\uC744 \uC62C\uB824 \uC4F0\uACE0 \uC678\uBA74\uD55C\uB2E4. \uD558\uC9C0\uB9CC \uCEE8\uD2B8\uB864\uB7EC\uB97C \uC954 \uC190\uC740 \uBC29\uAE08\uBCF4\uB2E4 \uD6E8\uC52C \uAC00\uBCCD\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uC288\uD14C", body: "\u2026\uC774 \uC598\uAE30 \uB4E4\uC740 \uAC70 \uC78A\uC5B4. \uC544\uB2C8, \uC78A\uC9C0 \uB9C8. \uC544\uB2C8, \uB458 \uB2E4 \uC544\uB2C8\uACE0\u2026 \uADF8\uB0E5 \uC54C\uACE0\uB9CC \uC788\uC5B4, \uC624\uB354." }
  ]
};
var CHAPTER_826 = {
  id: "bond.shute.8",
  startNodeId: "n1",
  titleCard: { title: "\uD55C \uBA85\uB9CC", subtitle: "\uC288\uD14C \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 3" },
  nodes: [
    { id: "n1", speaker: "", body: "\uD6C8\uB828\uC7A5\uC758 \uC624\uD6C4. \uC288\uD14C\uC758 \uBC29 \uD654\uBA74 \uC5EC\uB35F \uC7A5 \uC911 \uC77C\uACF1 \uC7A5\uC774 \uAEBC\uC838 \uC788\uACE0, \uD55C \uC7A5\uC5D0\uB9CC \uD30C\uB8E8\uC544\uAC00 \uD06C\uAC8C \uBE44\uCE5C\uB2E4. \uC288\uD14C\uB294 \uADF8 \uD55C \uBA85\uC5D0\uAC8C \uB04A\uC784\uC5C6\uC774 \uC9C0\uC2DC\uB97C \uBCF4\uB0B4\uB294 \uC911\uC774\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uC288\uD14C", body: "\u2026\uC624\uB978\uCABD \uC5F4\uC5B4. \uC9C0\uAE08. \uC544\uB2C8, \uBC18 \uBC15\uC790 \uB4A4. \uC88B\uC544. \uC774\uC81C \uB4E4\uC5B4\uAC00. \uC228 \uC26C\uC5B4. \uAD1C\uCC2E\uC544, \uC798\uD558\uACE0 \uC788\uC5B4.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uD654\uBA74 \uC18D \uD30C\uB8E8\uC544\uAC00 \uAC11\uC790\uAE30 \uBC1C\uC774 \uAC78\uB824 \uB118\uC5B4\uC9C4\uB2E4. \uC288\uD14C\uC758 \uC190\uAC00\uB77D\uC774 \uCEE8\uD2B8\uB864\uB7EC \uC704\uC5D0\uC11C \uC5BC\uC5B4\uBD99\uB294\uB2E4. \uBC29 \uC548\uC758 \uBAA8\uB4E0 \uC18C\uB9AC\uAC00 \uC0AC\uB77C\uC9C4\uB2E4. \uD5E4\uB4DC\uD3F0 \uC18D\uC5D0\uC11C \uC0C8\uC5B4 \uB098\uC624\uB358 \uC9C0\uC2DC\uB3C4 \uB69D \uB04A\uAE34\uB2E4.", cue: "impact", nextId: "n4" },
    { id: "n4", speaker: "", body: "\uC5F0\uAD6C\uC6D0\uC774 \uBC29 \uBB38\uC744 \uC5F4\uC790 \uC288\uD14C\uAC00 \uD654\uBA74 \uC55E\uC5D0\uC11C \uAF3C\uC9DD\uB3C4 \uD558\uC9C0 \uC54A\uB294 \uCC44 \uC549\uC544 \uC788\uB2E4. \uC785\uC220\uC774 \uD558\uC597\uAC8C \uC9C8\uB824 \uC788\uB2E4.", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uD654\uBA74 \uC18D \uD30C\uB8E8\uC544\uB294 \uACE7 \uC77C\uC5B4\uB098 \uBB34\uB98E\uC744 \uD138\uACE0 \uC788\uB2E4. \uD6C8\uB828 \uC911 \uD754\uD55C \uB118\uC5B4\uC9D0\uC774\uB2E4. \uD558\uC9C0\uB9CC \uC288\uD14C\uB294 \uC544\uC9C1 \uC6C0\uC9C1\uC774\uC9C0 \uC54A\uB294\uB2E4.)", choices: [
      { id: "shoulder", label: "\uC5B4\uAE68\uC5D0 \uC190\uC744 \uC5B9\uACE0 \uAD1C\uCC2E\uB2E4\uACE0 \uB9D0\uD55C\uB2E4", nextId: "n6a" },
      { id: "screen", label: "\uD654\uBA74 \uC18D \uD30C\uB8E8\uC544\uAC00 \uC77C\uC5B4\uB09C \uAC83\uC744 \uAC00\uB9AC\uD0A8\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uC288\uD14C", body: "\u2026\uC190 \uCE58\uC6CC. \uC544\uB2C8, \uADF8\uB300\uB85C \uC788\uC5B4. \u2026\uB098 \uC9C0\uAE08 \uC228 \uC548 \uC26C\uACE0 \uC788\uC5C8\uC5B4, \uC624\uB354. \uC54C\uC544. \uC54C\uACE0\uB294 \uC788\uC5B4.", nextId: "n7" },
    { id: "n6b", speaker: "\uC288\uD14C", body: "\u2026\uBD24\uC5B4. \uC77C\uC5B4\uB0AC\uC9C0. \uC77C\uC5B4\uB09C \uAC74 \uC544\uB294\uB370, \uB118\uC5B4\uC9C4 \uC21C\uAC04\uC740 \uADF8\uB300\uB85C \uB0A8\uC544. \uBA38\uB9AC\uC5D0\uC11C \uC548 \uC9C0\uC6CC\uC838.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uC288\uD14C\uAC00 \uCC9C\uCC9C\uD788 \uC228\uC744 \uB0B4\uC270\uB2E4. \uCEE8\uD2B8\uB864\uB7EC\uB97C \uC954 \uC190\uAC00\uB77D\uC774 \uD558\uB098\uC529 \uD480\uB9B0\uB2E4. \uD5E4\uB4DC\uD3F0 \uC18D\uC5D0\uC11C \uB2E4\uC2DC \uC9C0\uC2DC\uAC00 \uD758\uB7EC\uB098\uC628\uB2E4. \uC774\uBC88\uC5D0\uB294 \uC544\uC8FC \uB0AE\uC740 \uBAA9\uC18C\uB9AC\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "\uC288\uD14C", body: "\u2026\uD30C\uB8E8\uC544, \uAD1C\uCC2E\uC544? \uC77C\uC5B4\uB0AC\uC5B4? \u2026\uADF8\uB798, \uCC9C\uCC9C\uD788. \uC11C\uB450\uB974\uC9C0 \uB9C8. \uC774\uC81C\uBD80\uD130\uB294 \uB0B4\uAC00 \uB2E4\uC2DC \uC55E\uC5D0\uC11C \uBD10 \uC904\uAC8C.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uD654\uBA74 \uC18D \uD30C\uB8E8\uC544\uAC00 \uCE74\uBA54\uB77C\uB97C \uD5A5\uD574 \uC190\uC744 \uB4E4\uC5B4 \uC62C\uB9B0\uB2E4. \uC288\uD14C\uC758 \uC5B4\uAE68\uAC00 \uC791\uAC8C \uB5A8\uB9B0\uB2E4. \uD558\uC9C0\uB9CC \uC785\uAF2C\uB9AC\uB294 \uC62C\uB77C\uAC00 \uC788\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uC288\uD14C", body: "\u2026\uD55C \uBA85\uB9CC \uBD99\uC7A1\uB294 \uC774\uC720 \uC54C\uB824 \uC904\uAE4C, \uC624\uB354. \uD55C \uBA85\uB9CC \uBCF4\uBA74 \uC548 \uB193\uCCD0. \uADF8 \uD55C \uBA85\uC774 \uB118\uC5B4\uC9C0\uBA74\u2026 \uB098\uB3C4 \uAC19\uC774 \uBA48\uCD94\uC9C0\uB9CC. \uADF8\uAC74 \uB410\uC5B4." }
  ]
};
var CHAPTER_1026 = {
  id: "bond.shute.10",
  startNodeId: "n1",
  titleCard: { title: "\uADF8\uB7ED\uC800\uB7ED\uC758 \uB73B", subtitle: "\uC288\uD14C \xB7 \uC560\uCC29 \uC774\uC57C\uAE30 4" },
  nodes: [
    { id: "n1", speaker: "", body: "\uD6C8\uB828\uC7A5 \uD55C\uAC00\uC6B4\uB370. \uC5F0\uAD6C\uC6D0\uC774 \uD63C\uC790 \uCF54\uC2A4 \uCD9C\uBC1C\uC120\uC5D0 \uC11C \uC788\uB2E4. \uCC9C\uC7A5\uC758 \uC791\uC740 \uB4DC\uB860\uC774 \uAE5C\uBE61\uC774\uBA70 \uC2E0\uD638\uB97C \uBCF4\uB0B4\uACE0, \uD5E4\uB4DC\uD3F0 \uC18D\uC5D0\uC11C \uB0AE\uC740 \uBAA9\uC18C\uB9AC\uAC00 \uB4E4\uB824\uC628\uB2E4.", nextId: "n2" },
    { id: "n2", speaker: "\uC288\uD14C", body: "(\uD5E4\uB4DC\uD3F0) \u2026\uB4E4\uB824, \uC624\uB354? \uC624\uB298\uC740 \uB0B4\uAC00 \uCC98\uC74C\uC73C\uB85C \uC5EC\uB35F \uD654\uBA74\uC744 \uB2E4 \uB044\uACE0 \uC624\uB354 \uD558\uB098\uB9CC \uBCFC\uAC8C. \uC2DC\uC791\uD574.", nextId: "n3" },
    { id: "n3", speaker: "", body: "\uC5F0\uAD6C\uC6D0\uC774 \uCCAB\uAC78\uC74C\uC744 \uB5C0\uB2E4. \uACE7\uBC14\uB85C \uADD3\uC18D\uC5D0\uC11C \uC9C0\uC2DC\uAC00 \uB530\uB77C\uC628\uB2E4. \uC624\uB978\uCABD, \uB450 \uAC78\uC74C, \uBA48\uCDB0, \uC5F4\uC5B4. \uD55C \uB9C8\uB514 \uD55C \uB9C8\uB514\uAC00 \uC815\uD655\uD558\uACE0 \uBE60\uB974\uB2E4.", nextId: "n4" },
    { id: "n4", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uCF54\uC2A4 \uC911\uAC04\uC5D0\uC11C \uBC1C\uC774 \uAC78\uB9B4 \uBED4\uD55C\uB2E4. \uD5E4\uB4DC\uD3F0 \uC18D\uC5D0\uC11C \uC228\uC744 \uB4E4\uC774\uCF1C\uB294 \uC18C\uB9AC\uAC00 \uB0AC\uB2E4.)", nextId: "n5" },
    { id: "n5", speaker: "\uC5F0\uAD6C\uC6D0", body: "(\uCF54\uC2A4\uC758 \uB9C8\uC9C0\uB9C9 \uAD6C\uAC04 \uC55E\uC774\uB2E4. \uC288\uD14C\uC758 \uBAA9\uC18C\uB9AC\uAC00 \uD55C \uBC15\uC790 \uB2A6\uAC8C \uC774\uC5B4\uC9C4\uB2E4.)", choices: [
      { id: "trust", label: "\uC9C0\uC2DC\uB97C \uADF8\uB300\uB85C \uBBFF\uACE0 \uC55E\uC73C\uB85C \uB098\uC544\uAC04\uB2E4", nextId: "n6a" },
      { id: "ask", label: "\uB9C8\uC9C0\uB9C9\uC740 \uC5B4\uB290 \uCABD\uC774\uB0D0\uACE0 \uB418\uBB3B\uB294\uB2E4", nextId: "n6b" }
    ] },
    { id: "n6a", speaker: "\uC288\uD14C", body: "(\uD5E4\uB4DC\uD3F0) \u2026\uADF8\uB300\uB85C \uAC00. \uAC70\uAE30. \uC88B\uC544. \uC815\uD655\uD574. \uC624\uB354, \uC190 \uB193\uC9C0 \uB9C8. \uAC70\uC758 \uB2E4 \uC654\uC5B4.", nextId: "n7" },
    { id: "n6b", speaker: "\uC288\uD14C", body: "(\uD5E4\uB4DC\uD3F0) \u2026\uBB3C\uC5B4\uBD10 \uC918\uC11C \uACE0\uB9C8\uC6CC. \uC67C\uCABD\uC774\uC57C. \uC624\uB978\uCABD\uC740 \uD568\uC815\uC774\uACE0. \uADF8\uAC70 \uC544\uB2C8\uB77C\uB2C8\uAE4C, \uC624\uB978\uCABD \uC544\uB2C8\uC57C. \uADF8\uB798, \uC67C\uCABD.", nextId: "n7" },
    { id: "n7", speaker: "", body: "\uC5F0\uAD6C\uC6D0\uC774 \uCF54\uC2A4 \uB05D\uC120\uC744 \uB118\uB294\uB2E4. \uD5E4\uB4DC\uD3F0 \uC18D\uC774 \uD55C\uB3D9\uC548 \uC870\uC6A9\uD558\uB2E4. \uADF8\uB9AC\uACE0 \uC228\uC744 \uD06C\uAC8C \uB0B4\uC26C\uB294 \uC18C\uB9AC\uAC00 \uB4E4\uB9B0\uB2E4.", nextId: "n8" },
    { id: "n8", speaker: "\uC288\uD14C", body: "(\uD5E4\uB4DC\uD3F0) \u2026\uC624\uB354. \uC9C0\uAE08 \uC5EC\uB35F \uD654\uBA74 \uB2E4 \uAEBC\uC838 \uC788\uC5B4. \uB208\uC55E\uC5D0 \uC624\uB354 \uD558\uB098\uB9CC \uC788\uC5B4. \uB193\uCE5C \uAC70 \uD558\uB098\uB3C4 \uC5C6\uC5B4.", nextId: "n9" },
    { id: "n9", speaker: "", body: "\uC7A0\uC2DC \uB4A4 \uAD6C\uC11D\uBC29\uC758 \uBB38\uC774 \uC5F4\uB9AC\uACE0 \uC288\uD14C\uAC00 \uC9C1\uC811 \uAC78\uC5B4 \uB098\uC628\uB2E4. \uD5E4\uB4DC\uD3F0\uC740 \uBAA9\uC5D0 \uAC78\uACE0, \uCEE8\uD2B8\uB864\uB7EC\uB294 \uD55C \uC190\uC5D0 \uC954 \uCC44\uB2E4. \uC5F0\uAD6C\uC6D0 \uC55E\uC5D0 \uC11C\uC11C \uD55C\uCC38 \uB208\uC744 \uBABB \uB9DE\uCD94\uB2E4\uAC00 \uACE0\uAC1C\uB97C \uB4E0\uB2E4.", nextId: "n10" },
    { id: "n10", speaker: "\uC288\uD14C", body: "\u2026\uADF8\uB7ED\uC800\uB7ED. \uC774 \uB9D0, \uC544\uBB34\uD55C\uD14C\uB098 \uC548 \uD574, \uC624\uB354. \uB2E4\uC74C \uD310\uB3C4 \uB0B4 \uC624\uB354 \uB4E4\uC5B4. \u2026\uBD80\uD0C1\uC774\uC57C." }
  ]
};
var SHUTE_STORY = {
  relicId: "shute",
  fossilRecord: "\uCC44\uC11D\uC7A5 \uBC14\uB2E5\uC758 \uC774\uC554\uC5D0 \uB4F1\uD310 \uC5F4\uC77C\uACF1 \uC7A5\uC774 \uBB34\uB108\uC9C0\uC9C0 \uC54A\uACE0 \uB450 \uC904\uB85C \uB298\uC5B4\uC120 \uCC44 \uB0A8\uC544 \uC788\uC5C8\uB2E4. \uD310\uB9C8\uB2E4 \uD608\uAD00\uC774 \uC9C0\uB098\uAC04 \uD648\uC774 \uCD18\uCD18\uD574, \uBCF5\uC6D0 \uC5F0\uAD6C\uB294 \uADF8 \uD648\uC774 \uC5F4\uC744 \uBC84\uB9AC\uB294 \uAE38\uC778\uC9C0 \uC2E0\uD638\uB97C \uBCF4\uB0B4\uB294 \uAE38\uC778\uC9C0\uBD80\uD130 \uAC08\uB77C\uC57C \uD588\uB2E4.",
  diary: "\uBCF5\uC6D0 \uD6C4 \uC288\uD14C\uB294 \uAD00\uC81C\uD0D1\uC5D0 \uC62C\uB77C\uC624\uC9C0 \uC54A\uB294\uB2E4. \uC81C \uBC29\uC5D0 \uD654\uBA74\uC744 \uC5EC\uB35F \uC7A5 \uB744\uC6CC \uB193\uACE0 \uAC70\uAE30\uC11C \uC804\uC7A5\uC744 \uBCF8\uB2E4. \uB9D0\uC744 \uAC78\uBA74 \uB300\uB2F5\uC774 \uD55C \uBC15\uC790 \uB2A6\uACE0 \uB300\uCCB4\uB85C \uC9E7\uC9C0\uB9CC, \uD55C \uBA85\uC744 \uC815\uD574 \uB193\uACE0\uB294 \uADF8 \uD55C \uBA85\uC5D0\uAC8C\uB9CC \uB05D\uC5C6\uC774 \uB9D0\uD55C\uB2E4 \u2014 \uC5B4\uB514\uB85C \uB3CC\uC544\uB77C, \uC9C0\uAE08 \uB4E4\uC5B4\uAC00\uB77C, \uADF8\uAC70 \uC544\uB2C8\uB77C\uB2C8\uAE4C. \uB4F1\uD310\uC740 \uADF8\uB54C \uC0C9\uC774 \uB3C8\uB2E4. \uD310\uC774 \uBC1D\uC544\uC9C4 \uBC29\uD5A5\uC5D0 \uC815\uD655\uD788 \uADF8 \uC544\uC774\uAC00 \uBCF4\uACE0 \uC788\uB294 \uACF3\uC774 \uC788\uC5B4, \uC8FC\uBCC0 \uB300\uC6D0\uB4E4\uC740 \uC288\uD14C\uC758 \uB4F1\uC744 \uBCF4\uACE0 \uC804\uD669\uC744 \uC77D\uB294 \uBC95\uC744 \uB530\uB85C \uC775\uD614\uB2E4. \uC798\uD588\uB2E4\uACE0 \uD558\uBA74 \uD654\uBA74 \uCABD\uC73C\uB85C \uACE0\uAC1C\uB97C \uB3CC\uB9AC\uACE0 \uADF8\uB7ED\uC800\uB7ED\uC774\uB77C\uACE0\uB9CC \uD55C\uB2E4.",
  /** 일지 맨 끝에 회색으로 서는, 슈테가 연구원에게 건네는 한마디. 뽑기 대사와 다른 일상의 목소리다. */
  closingLine: "\u2026\uC654\uC5B4, \uC624\uB354? \uBB38 \uB2EB\uC544. \uD654\uBA74 \uBC18\uC0AC\uB3FC. \uC624\uB298\uC740 \uB204\uAD6C \uBCFC \uAC70\uC57C?",
  questions: [
    {
      id: "shute-screens",
      prompt: "\uD654\uBA74\uC740 \uC65C \uC5EC\uB35F \uC7A5\uC774\uB098 \uB744\uC6CC \uB194?",
      choices: [
        {
          id: "whole",
          label: "\uC804\uCCB4\uB97C \uD55C\uB208\uC5D0 \uBCF4\uB824\uACE0 \uADF8\uB7EC\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\u2026\uC751. \uB208\uC740 \uB450 \uAC1C\uBFD0\uC774\uC796\uC544. \uD654\uBA74\uC740 \uC5EC\uB35F \uAC1C\uB2C8\uAE4C \uB124 \uBC30\uC57C. \uB300\uC2E0 \uBCF4\uB294 \uAC74 \uD55C \uBA85\uC774\uC57C.",
          note: "\uC804\uCCB4\uB97C \uBCF4\uB824\uACE0 \uADF8\uB7EC\uB290\uB0D0\uACE0 \uBB3B\uC790 \uD654\uBA74 \uD558\uB098\uB97C \uAC00\uB9AC\uCF30\uB2E4. \uC5EC\uB35F \uC7A5\uC744 \uB744\uC6CC\uB3C4 \uC815\uC791 \uBCF4\uB294 \uAC83\uC740 \uD55C \uBA85\uC774\uB77C\uACE0 \uD55C\uB2E4."
        },
        {
          id: "dark",
          label: "\uBC29\uC774 \uB108\uBB34 \uC5B4\uB461\uC9C0 \uC54A\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC5B4\uB450\uC6CC\uC57C \uD654\uBA74\uC774 \uC798 \uBCF4\uC5EC. \uADF8\uB9AC\uACE0\u2026 \uBD88 \uCF1C\uBA74 \uC0AC\uB78C\uC774 \uB4E4\uC5B4\uC62C \uAC83 \uAC19\uC544\uC11C. \uC774\uAC74 \uBE44\uBC00\uC774\uC57C.",
          note: "\uBC29\uC774 \uC5B4\uB461\uC9C0 \uC54A\uB290\uB0D0\uACE0 \uBB3B\uC790 \uC5B4\uAE68\uB97C \uC73C\uC4F1\uC600\uB2E4. \uBD88\uC744 \uCF1C\uBA74 \uC0AC\uB78C\uC774 \uB4E4\uC5B4\uC62C \uAC83 \uAC19\uB2E4\uACE0 \uC791\uAC8C \uB367\uBD99\uC600\uB2E4."
        },
        {
          id: "dino",
          label: "\uAC00\uC6B4\uB370 \uB5A0 \uC788\uB294 \uB3C4\uD2B8 \uACF5\uB8E1\uC740 \uBB50\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\u2026\uADF8\uAC70? \uCC98\uC74C \uB9CC\uB4E0 \uAC8C\uC784 \uCE90\uB9AD\uD130\uC57C. \uB3C4\uD2B8 \uC5F4\uC5EC\uC12F \uAC1C\uB85C \uB9CC\uB4E4\uC5C8\uC5B4. \uC544\uC9C1 \uAC54\uAC00 \uC81C\uC77C \uB9C8\uC74C\uC5D0 \uB4E4\uC5B4.",
          note: "\uB3C4\uD2B8 \uACF5\uB8E1\uC744 \uBB3B\uC790 \uCEE8\uD2B8\uB864\uB7EC\uB97C \uB9CC\uC9C0\uC791\uAC70\uB838\uB2E4. \uCC98\uC74C \uB9CC\uB4E0 \uAC8C\uC784 \uCE90\uB9AD\uD130\uB77C\uC11C \uC544\uC9C1\uB3C4 \uB744\uC6CC \uB454\uB2E4\uACE0 \uD55C\uB2E4."
        }
      ]
    },
    {
      id: "shute-praise",
      prompt: "\uC288\uD14C\uAC00 \uB9D0\uD558\uB294 \u300C\uADF8\uB7ED\uC800\uB7ED\u300D\uC740 \uC5B4\uB5A4 \uB73B\uC774\uC57C?",
      choices: [
        {
          id: "best",
          label: "\uC0AC\uC2E4\uC740 \uCD5C\uACE0\uC758 \uCE6D\uCC2C\uC774\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\u2026\uB204\uAC00 \uADF8\uB798. \uC544\uB2C8, \uB9DE\uC544. \uB9DE\uB294\uB370 \uADF8\uAC78 \uB208\uCE58\uCC44\uBA74 \uC774\uC81C \uBABB \uC4F0\uC796\uC544. \uB208\uCE58\uCC44\uC9C0 \uB9C8, \uC624\uB354.",
          note: "\uCD5C\uACE0\uC758 \uCE6D\uCC2C\uC774\uB0D0\uACE0 \uBB3B\uC790 \uD55C \uBC15\uC790 \uB2A6\uAC8C \uC5BC\uAD74\uC744 \uB3CC\uB838\uB2E4. \uB208\uCE58\uCC44\uBA74 \uBABB \uC4F4\uB2E4\uACE0 \uD22C\uB35C\uB314\uB2E4."
        },
        {
          id: "plain",
          label: "\uADF8\uB0E5 \uBCF4\uD1B5\uC774\uB77C\uB294 \uB73B\uC774\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uBCF4\uD1B5\uC774\uB77C\uB294 \uB73B\uC774\uBA74 \uB9D0\uC744 \uC548 \uD558\uC9C0. \uB9D0\uC744 \uD588\uB2E4\uB294 \uAC74 \uADF8\uB7ED\uC800\uB7ED \uC774\uC0C1\uC774\uB77C\uB294 \uAC70\uC57C.",
          note: "\uBCF4\uD1B5\uC774\uB77C\uB294 \uB73B\uC774\uB0D0\uACE0 \uBB3B\uC790 \uB208\uC379\uC744 \uC62C\uB838\uB2E4. \uB9D0\uC744 \uD588\uB2E4\uB294 \uAC83 \uC790\uCCB4\uAC00 \uCE6D\uCC2C\uC774\uB77C\uACE0 \uD55C\uB2E4."
        }
      ]
    },
    {
      id: "shute-one",
      prompt: "\uC65C \uD55C \uBC88\uC5D0 \uD55C \uBA85\uB9CC \uB530\uB77C\uB2E4\uB140?",
      choices: [
        {
          id: "miss",
          label: "\uC5EC\uB7FF\uC744 \uBCF4\uBA74 \uB193\uCE58\uB294 \uAC8C \uC0DD\uACA8\uC11C\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\uC751. \uC5EC\uB7FF \uBCF4\uBA74 \uD55C \uBA85\uD55C\uD14C\uB294 \uB2A6\uC5B4. \uB2A6\uC73C\uBA74 \uB118\uC5B4\uC838. \uD55C \uBA85\uC774\uBA74 \uC548 \uB2A6\uC5B4.",
          note: "\uC5EC\uB7FF\uC744 \uBCF4\uBA74 \uB193\uCE58\uB290\uB0D0\uACE0 \uBB3B\uC790 \uACE0\uAC1C\uB97C \uB044\uB355\uC600\uB2E4. \uD55C \uBA85\uC774\uBA74 \uB2A6\uC9C0 \uC54A\uB294\uB2E4\uACE0 \uD55C\uB2E4."
        },
        {
          id: "fall",
          label: "\uADF8 \uD55C \uBA85\uC774 \uC4F0\uB7EC\uC9C0\uBA74 \uC5B4\uB5BB\uAC8C \uD558\uB290\uB0D0\uACE0 \uBB3B\uB294\uB2E4",
          reply: "\u2026\uBA48\uCDB0. \uC228\uC774 \uC548 \uC26C\uC5B4\uC838. \uADFC\uB370 \uC77C\uC5B4\uB098\uBA74 \uB2E4\uC2DC \uC2DC\uC791\uD574. \uADF8\uAC8C \uB0B4 \uBC29\uC2DD\uC774\uC57C, \uC624\uB354.",
          note: "\uC4F0\uB7EC\uC9C0\uBA74 \uC5B4\uB5BB\uAC8C \uD558\uB290\uB0D0\uACE0 \uBB3B\uC790 \uD55C\uCC38 \uB9D0\uC774 \uC5C6\uC5C8\uB2E4. \uC77C\uC5B4\uB098\uBA74 \uB2E4\uC2DC \uC2DC\uC791\uD55C\uB2E4\uACE0 \uC9E7\uAC8C \uB2F5\uD588\uB2E4."
        },
        {
          id: "me",
          label: "\uB2E4\uC74C\uC5D4 \uC790\uAE30\uB97C \uBD99\uC7A1\uC544 \uB2EC\uB77C\uACE0 \uB9D0\uD55C\uB2E4",
          reply: "\u2026\uC624\uB354\uB97C? \uC704\uD5D8\uD574, \uC624\uB354\uB294 \uAC00\uB054 \uC774\uC0C1\uD55C \uB370\uB85C \uAC00\uC796\uC544. \uADF8\uB798\uB3C4\u2026 \uD55C \uBC88\uCBE4\uC740 \uD574 \uBCFC\uAC8C. \uC57D\uC18D\uC740 \uC548 \uD574.",
          note: "\uC790\uAE30\uB97C \uBD99\uC7A1\uC544 \uB2EC\uB77C\uACE0 \uD558\uC790 \uB208\uC774 \uBC18\uC9DD\uC774\uB2E4 \uAE09\uD788 \uC228\uC5C8\uB2E4. \uC57D\uC18D\uC740 \uBABB \uD558\uC9C0\uB9CC \uD55C \uBC88\uCBE4\uC740 \uD574 \uBCF4\uACA0\uB2E4\uACE0 \uD588\uB2E4."
        }
      ]
    }
  ],
  bondStories: { 4: CHAPTER_426, 6: CHAPTER_626, 8: CHAPTER_826, 10: CHAPTER_1026 },
  bondLines: [
    // 0 — 낯선 사이.
    ["\u2026\uC288\uD14C\uC57C. \uBC29 \uBC16\uC5D0\uC11C\uB294 \uCC98\uC74C \uB9D0\uD574 \uBCF4\uB124. \uBB50, \uBC18\uAC00\uC6CC.", "\uC624\uB354\uB77C\uACE0 \uBD80\uB97C\uAC8C. \uC774\uB984\uC740 \uAE38\uC5B4\uC11C \uBABB \uC678\uC6CC. \uC544\uB2C8, \uC678\uC6E0\uB294\uB370 \uC624\uB354\uAC00 \uB354 \uD3B8\uD574.", "\uADF8\uAC70 \uC544\uB2C8\uB77C\uB2C8\uAE4C? \u2026\uC544, \uC544\uC9C1 \uC544\uBB34\uAC83\uB3C4 \uC548 \uD588\uAD6C\uB098. \uBBF8\uC548."],
    // 1
    ["\uD654\uBA74 \uC5EC\uB35F \uAC1C \uC911\uC5D0 \uC624\uB354\uB294 \uBA87 \uBC88\uC9F8\uC5D0 \uC788\uC5B4? \u2026\uC544\uC9C1 \uC548 \uC815\uD588\uC5B4. \uC815\uD558\uBA74 \uB9D0\uD574 \uC904\uAC8C.", "\uCEE8\uD2B8\uB864\uB7EC \uC190\uC5D0 \uC950\uACE0 \uC788\uC73C\uBA74 \uC548\uC2EC\uB3FC. \uC774\uAC70 \uC5C6\uC73C\uBA74 \uC190\uC774 \uC2EC\uC2EC\uD574.", "\uD5E4\uB4DC\uD3F0 \uD55C\uCABD\uC740 \uC77C\uBD80\uB7EC \uB0B4\uB824\uB194. \uD55C\uCABD\uC740 \uC138\uC0C1 \uC18C\uB9AC, \uD55C\uCABD\uC740 \uC9C0\uC2DC \uC18C\uB9AC\uC57C."],
    // 2
    ["\uB300\uB2F5\uC774 \uB2A6\uB294 \uAC74 \uC0DD\uAC01\uD558\uB294 \uAC70\uC57C. \uBB34\uC2DC\uD558\uB294 \uAC8C \uC544\uB2C8\uC57C. \uC54C\uC9C0?", "\uC624\uB298\uC740 \uB3C4\uB514\uB97C \uBD24\uC5B4. \uAC54\uB294 \uC9C0\uC2DC\uB97C \uD55C \uBC88\uC5D0 \uC54C\uC544\uB4E4\uC5B4. \uC2E0\uAE30\uD574.", "\uB0B4 \uBC29 \uC598\uAE30\uB294 \uC544\uC9C1 \uD558\uC9C0 \uB9C8. \uC18C\uBB38\uB098\uBA74 \uBB38 \uC7A0\uAE00 \uAC70\uC57C."],
    // 3
    ["\uB4F1\uD310 \uC0C9\uC774 \uBCC0\uD558\uB294 \uAC70, \uC77C\uBD80\uB7EC \uD558\uB294 \uAC70 \uC544\uB2C8\uC57C. \uC9D1\uC911\uD558\uBA74 \uC800\uC808\uB85C \uADF8\uB798.", "\uADF8\uB7ED\uC800\uB7ED\uC774 \uCD5C\uACE0\uC758 \uCE6D\uCC2C\uC774\uB77C\uACE0? \u2026\uB204\uAC00 \uADF8\uB798. \uB0B4\uAC00 \uADF8\uB7F0 \uB9D0\uC744 \uD588\uC5B4?", "\uD55C \uBA85\uB9CC \uBCF4\uB294 \uAC74 \uD3B8\uD574. \uC5EC\uB7FF \uBCF4\uBA74 \uBA38\uB9AC\uAC00 \uD130\uC9C8 \uAC83 \uAC19\uC544."],
    // 4 — 장 4 이후: 화면 여덟 장.
    ["\uADF8\uB0A0 \uBC29\uC5D0 \uC624\uB354 \uC549\uC740 \uC790\uB9AC, \uB3C4\uB514 \uD654\uBA74\uC774 \uC81C\uC77C \uC798 \uBCF4\uC774\uB294 \uC790\uB9AC\uC57C. \uACC4\uC18D \uC549\uC544\uB3C4 \uB3FC.", "\uD654\uBA74 \uC5EC\uB35F \uC7A5 \uBCF4\uC5EC \uC900 \uC0AC\uB78C\uC740 \uC624\uB354\uAC00 \uCC98\uC74C\uC774\uC57C. \uADF8\uAC78 \uC54C\uC558\uC73C\uBA74 \uD574.", "\uB3C4\uD2B8 \uACF5\uB8E1 \uB208\uC744 \uD558\uB098 \uB354 \uCC0D\uC5C8\uC5B4. \u2026\uD2F0 \uB098?"],
    // 5
    ["\uC624\uB298\uC740 \uD30C\uB8E8\uC544\uB97C \uBD24\uC5B4. \uAC54\uB294 \uC9C0\uC2DC \uC548 \uD574\uB3C4 \uC54C\uC544\uC11C \uC798 \uAC00. \uC2EC\uC2EC\uD588\uC5B4.", "\uCEE8\uD2B8\uB864\uB7EC \uBC84\uD2BC\uC774 \uB2F3\uC544\uC11C \uC0C8\uB85C \uBC14\uAFC0\uAE4C \uC0DD\uAC01 \uC911\uC774\uC57C. \uADFC\uB370 \uC190\uC5D0 \uC775\uC740 \uAC8C \uC88B\uC544.", "\uC624\uB354, \uC624\uB298\uB3C4 \uB2A6\uAC8C\uAE4C\uC9C0 \uC548 \uC790? \u2026\uB098\uB3C4 \uADF8\uB798. \uD654\uBA74 \uB044\uAE30 \uC2EB\uC5B4\uC11C."],
    // 6 — 장 6 이후: 한 박자 늦은 대답.
    ["\uBC29\uAE08 \uB300\uB2F5 \uB2A6\uC5C8\uC9C0. \uC544\uB294\uB370, \uAE30\uB2E4\uB824 \uC92C\uB124. \u2026\uADF8\uAC70 \uC740\uADFC\uD788 \uD3B8\uD574.", "\uB3C4\uB514\uD55C\uD14C\uB3C4 \uC870\uAE08\uC740 \uB9D0\uC744 \uAE38\uAC8C \uD574 \uBCF4\uB824\uACE0 \uD574. \uC544\uC9C1 \uB450 \uBB38\uC7A5\uC774 \uD55C\uACC4\uC57C.", "\uC624\uB354\uD55C\uD14C \uD55C \uB9D0 \uC911\uC5D0 \uBBF8\uB9AC \uC548 \uC9E0 \uAC70, \uBC29\uAE08 \uAC70\uC57C. \u2026\uD2F0 \uB0AC\uC5B4?"],
    // 7
    ["\uC624\uB354 \uC62C \uC2DC\uAC04\uC5D4 \uD5E4\uB4DC\uD3F0 \uD55C\uCABD\uC744 \uB0B4\uB824\uB194. \uB9D0 \uAC78\uBA74 \uBC14\uB85C \uB4E4\uC73C\uB824\uACE0.", "\uCEE8\uD2B8\uB864\uB7EC \uBC84\uD2BC\uC774 \uB610 \uC548 \uC62C\uB77C\uC640. \uC624\uB354\uAC00 \uACE0\uCCD0 \uC904\uB798? \uBD80\uD0C1\uC740 \uC544\uB2C8\uACE0.", "\uD654\uBA74 \uC18D \uCF54\uC2A4\uB294 \uC678\uC6E0\uC5B4. \uC624\uB354\uAC00 \uD2C0\uB9AC\uAC8C \uAC00\uB3C4 \uB530\uB77C\uAC08 \uC218 \uC788\uC5B4."],
    // 8 — 장 8 이후: 한 명만.
    ["\uD30C\uB8E8\uC544\uAC00 \uB118\uC5B4\uC9C4 \uB0A0 \uC228 \uC548 \uC26C\uACE0 \uC788\uC5C8\uC5B4. \uC624\uB354\uAC00 \uC5B4\uAE68 \uC9DA\uC5B4 \uC918\uC11C \uB3CC\uC544\uC654\uC5B4.", "\uC624\uB354, \uC5B4\uC81C \uCF54\uC2A4 \uB3CC \uB54C \uBC1C\uBAA9 \uC2E0\uACBD \uC4F0\uC600\uC9C0. \uC544\uCE68\uC5D0 \uD55C \uBC88 \uB2E4\uC2DC \uBD24\uC5B4. \uBC14\uB2E5\uC5D0 \uD131 \uD558\uB098 \uC788\uB354\uB77C.", "\uB2E4\uC74C\uC5D0\uB3C4 \uB0B4\uAC00 \uBA48\uCD94\uBA74 \uC5B4\uAE68\uB97C \uC9DA\uC5B4 \uC918. \uBD80\uD0C1\uC774\uC57C."],
    // 9
    ["\uC624\uB354\uB97C \uD55C \uBC88 \uBD99\uC7A1\uC544 \uBCF4\uACE0 \uC2F6\uC5B4. \uC704\uD5D8\uD574\uB3C4 \uD574 \uBCF4\uACE0 \uC2F6\uC5B4. \uC774\uC0C1\uD558\uC9C0?", "\uD654\uBA74 \uD55C \uC7A5\uB9CC \uCF1C \uB450\uACE0 \uC624\uB798 \uC788\uB294 \uC5F0\uC2B5 \uC911\uC774\uC57C. \uC544\uC9C1 \uD55C \uC2DC\uAC04\uC774 \uD55C\uACC4\uC57C.", "\uC624\uB354 \uBAA9\uC18C\uB9AC\uB294 \uD5E4\uB4DC\uD3F0\uC73C\uB85C \uB4E4\uC73C\uBA74 \uB354 \uB0AE\uAC8C \uB4E4\uB824. \uC758\uC678\uB85C \uC548\uC2EC\uB3FC."],
    // 10 — 마음을 연 사이. 그 한 명이 된 사이.
    ["\uC624\uB354 \uD55C \uBA85\uB9CC \uBD99\uC7A1\uC740 \uB0A0, \uB193\uCE5C \uAC8C \uD558\uB098\uB3C4 \uC5C6\uC5C8\uC5B4. \uADF8\uB0A0\uC774 \uB0B4 \uCD5C\uACE0 \uAE30\uB85D\uC774\uC57C.", "\uADF8\uB7ED\uC800\uB7ED\uC774\uB77C\uACE0 \uD588\uC9C0\uB9CC \uC0AC\uC2E4 \uD6E8\uC52C \uC704\uC57C. \uADF8 \uC774\uC0C1\uC740 \uC544\uC9C1 \uB9D0\uC774 \uC548 \uB098\uC640.", "\uB2E4\uC74C \uD310\uB3C4 \uB0B4 \uC624\uB354 \uB4E4\uC5B4. \uB300\uC2E0 \uB098\uB3C4 \uC624\uB354 \uBD80\uD0C1\uC740 \uB2E4 \uB4E4\uC744\uAC8C. \uC57D\uC18D\uC774\uC57C."]
  ]
};

