      const newId = mapId(oldId);
      if (Object.hasOwn(result, newId)) throw new SaveDataError(`${label}\uC5D0 \uAD6C\uD615/\uC2E0\uADDC \uB810\uB9AD ID\uAC00 \uD568\uAED8 \uC788\uC2B5\uB2C8\uB2E4: ${newId}`);
